/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20230821-7","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"厚生委員会","time":"午後 １時００分～午後 ４時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"こんの委員","kind":"意見","question":"前例のとおり、報告の前にお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"令和５年度高齢者福祉行事","agenda":"令和５年度高齢者福祉行事","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなところで、高齢者の行事が様々ある中に、そういう熱中症に対しての啓発というところもぜひ入れていただきたいなと思ったのですけれども、その点についても伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"司会進行も全て区のほうで行わせていただきますので、熱中症対策、こまめに飲物を飲んでいただくこと、あと帽子等かぶって実施していただくことは、事前に競技を参加される方に説明をしていくような形です。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"熱中症に対しての啓発というものが、もう本当にやってもやっても、これで終わりという感じのものがないくらい、私は啓発をすべきではないかなというような思いが、もう本当に実感しているのですけれども、そのようなところで、このようなイベントを通じて、そういう啓発もぜひしていただきたいと思うのですが、その辺のところは、区として熱中症に対しての啓発というところはどのように捉えて。","respondent":"菅野高齢者福祉課長","answer":"高齢者の熱中症対策につきましては、区としても、環境省のほうからもチラシ等を頂いておりますので、そちらのほう、普段から窓口、在宅介護支援センターや、あとは支え愛・ほっとステーションの窓口などで配付させていただいたり、あとは７月の地区民協のときに、民生委員に。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"まだまだ知識として持てていないという思いがしているのです。そのようなことなので、機会あるごとに熱中症という、例えば具体的に水分はこれぐらいのものが必要だとか、暑さを感じないというようなことで、もう客観的に見る習慣だったり、そのようなことも含めて、熱中症の高齢者に対しての知識の普及と啓発というようなところを、ぜひとも進めていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"贈呈事業の中から２つお伺いしたいと思います。１つは、施設入所の敬老の祝い品、これは参考までに、どのようなもの、どのようなお菓子を贈呈されているのかと。そうしたところも含めてなので、施設でのお祝いと、町会・自治会等でのこの１万円という予算、これの考え方について伺いたいと思います。お願いします。","respondent":"東野福祉計画課長","answer":"町会の祝金１万円というものはなかなか難しい、たくさんの方がご参加されてという部分につきましては、お祝いというところで１つの町会・自治会にお配りするというようなこと、公平にといいますか、公正にお配りするということで伺っていますので、社会福祉協議会としては。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"社会福祉協議会の事業と前提があるわけなのですけれども、そこを確認させてください。そもそもこの事業が、社会福祉協議会の事業としてしている。区としての事業等になっていないというところはなぜなのかというところを確認させてください。","respondent":"東野福祉計画課長","answer":"町会に対しましては、あくまでも社会福祉協議会のところで任意で行っているということになりますので、今のところ区のほうとして、改めて町会に対してというような事業ということは考えていないのですけれども、実態を踏まえて今後研究してまいりたいと思います。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"でも人数が増えて、年齢を引き上げるというか、６５歳からではなくて、集いを７０歳からとか、町会によっては７５歳からとか、そうなると逆に今度集いに出てこられない方が多くなってしまうとか、この線引きが非常に難しいという声も聞いておりますので、何かその辺の実態もつかんでいただきながら、社会福祉協議会と連携を取って、その辺何か集い、町会・自治会が行う敬老の日の在り方というようなものを。","respondent":"東野福祉計画課長","answer":"社会福祉協議会とも、その辺につきましては連携を取って、どのようなことができるのか、また地域活動課などでも、たくさん行事のほうの支援をしておりますので、その辺とのバランスを持って、考えていきたいと思います。","id":"exchange-007"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この町会・自治会敬老祝金についてですが、よく町会で７５歳以上の方にお祝い品などをお届けしているということがあるのですけれども、それはあくまで町会の団体としての行事であって、それとはこれは別という理解でよろしいのでしょうか。","respondent":"東野福祉計画課長","answer":"恐らく町会の中での決まり事として、そのようなものに取り組んでいらっしゃる町会がいらっしゃると思われます。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問","question":"なかなか敬老会というものも、全町会でやっているところとやっていないところがあるかなと思うのですけれども、その点の認識というか、状況というものをお聞きしたいということと、あと町会によっては、人数が町会ごとに違うと思うので、それで一律１万円というのは在り方としてどうなのかと思っているのですが、その辺り、この一律１万円で十分なのかということは。","respondent":"東野福祉計画課長","answer":"この１万円だけでは心もとないのではないかという部分につきましては、町会・自治会の規模にもよりますし、どういった内容の敬老会をするかというところにもなりますので、あくまでもそれに対して一律というようなことで、決まりを持ってやっていると伺っております。","id":"exchange-009"}]},{"id":"topic-03","title":"（仮称）小山七丁目障害者グループホームの整備・運営事業者の選定","agenda":"（仮称）小山七丁目障害者グループホームの整備・運営事業者の選定","exchanges":[{"speaker":"ひがし委員","kind":"質問・要望","question":"事業者を選定した理由というものがここに６行で示されていると思うのですけれども、このいろいろと別紙でついているものは公募の内容になっていると思うので、実際に１社手を挙げたということで、その方々を評価した具体的な内容というところ、これは具体的にどのようなところがよかったのかということを６行以外であれば教えていただきたいということと、あと細かい評価した内容が多分あると思うのですが。","respondent":"川崎障害者施策推進課長","answer":"２つ目としてバックアップ施設です。区内に複数障害福祉関連の事業所を運営していることから、夜間帯などにおける緊急事態の対応などのために、関係機関との連携および支援体制の確保ができるということが期待できます。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先ほど説明にありました、高齢化や重度化にも対応できるというところはすごく大切なところだと思いますので、精神疾患のみならず、もし障害、そのほかのものが出たときに対応できる事業所を選んだということで理解をいたしました。ぜひ決めた理由というところを示していただけるように要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問","question":"ちょっと基本的なところを伺いたいのですけれども、これ無償の貸付ということで３０年ということになっているのですが、なぜ３０年なのか、３０年たったら、ここを全部更地にして返すようにということになっていると思うのですけれども、３０年後にグループホームが必要なくなるということにはならないのではないかと思うのですが、なぜ３０年で廃止して更地で返すようにという。","respondent":"川崎障害者施策推進課長","answer":"ただ、区としましても、入居する利用者の安定した地域生活を支援していくために、３０年後に向けた用地確保の見通しを定期的に運営事業者に確認やヒアリングはしてまいります。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、ここは３０年たったら、もう公有財産管理規則によって、必ず更地にして返すというようなことが決まりなので、ここでそのまま続けるということはできないというような仕組みで、その方の安定のためには、ほかのところをまた別に品川区が確保して補償するという、そのようなことにしないとできないということになっていくのでしょうか。そして、その３０年後に、これは区の土地なわけですよね。","respondent":"川崎障害者施策推進課長","answer":"それで、３０年後ですけれども、区の土地ということではあります。そのときの社会情勢などもありますので、地域活性化や防災機能といった、そのときの地域のニーズを踏まえまして、今後の計画をしていくことになるかと考えております。","id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"そのような手法にしたほうが継続もできるし、品川区が責任を持って運営も、何というのですか、指定管理者に委託するとしても、品川区がフォローもするというようなこともできますし、障害者の方々、入る方にとっても安定した施設として提供できることになると思うのですけれども、なぜそれは指定管理者、区立にして指定管理者にせずに、このような形で、無償貸付で３０年後には廃止する。","respondent":"川崎障害者施策推進課長","answer":"重度の方の対象のグループホームというものも、２３区では民間の社会福祉法人でも運営しているという実績があります。品川区としましても、民間事業者でも運営可能なものは民間参入を促していくという方針であります。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"同じ時期の出石つばさの家のほうが、ではなぜ指定管理者にして、こちらは民設民営ということにしたのか、そこの違いというものは何なのですか。","respondent":"川崎障害者施策推進課長","answer":"出石つばさの家は、地域生活支援拠点の機能の充実を図るという名目です。今後、区の地域生活支援拠点の障害者グループホームの運営法人とも連携していく上では、区立という位置づけで運営していくことが求められておりますので、指定管理として今回指定をさせていただきました。","id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、出石のほうは拠点という位置づけが必要だったので区立にしたけれども、今後はそのような形ではなく、民設民営という方針でいくという、区の方針そのものがそうだというようなことで捉えていいのか、ちょっとその点も確認させてください。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"意見","question":"ということは、建設費も今回げんきのほうが持つということになりますよね。そうすると、建設費を減価償却していくという、そのような考え方になっていくのか。そうすると、利用者負担に跳ね返るということはないのか、家賃が、民間と区立のところでのグループホームの家賃というものが、今差があると思うのですけれども、そのような点では、区立と同じ家賃で利用できるようになるのか。","respondent":"川崎障害者施策推進課長","answer":"家賃につきましては、区と民間ではやはり差はあります。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"提案","question":"ということは、どれぐらいの家賃、多分もう計画書が出ていると思うのですけれども、どのような運営をしていくかということは、様々ここでも計画を出していますよね。それから家賃が、ではどれぐらいに具体的になっていくのか、その家賃の額についても、提出書類の中で多分提案されていると思うのですけれども、その辺はどうなっているのか、その点についても伺います。","respondent":"川崎障害者施策推進課長","answer":"収入に対する人件費などに関しても、社会福祉法人の平均の負担になりますし、また、基本報酬以外にも、加算分や活用可能な補助金を全て盛り込まれて、緻密に計算がされているというところです。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"提案","question":"指定管理者をげんきはやっていますよね。全て区立のグループホームというものは、年間５００万円とか、７００万円とか、そのような形で補助金を出しているわけです。そのような中で、そういう補助金もなしに、しかも建設費用を自らが出して、そしてほかの指定管理者で受けている、そのようなグループホームと同じ条件で運営ができるのか、そういう提案になっているのか、その辺はどうなっているのか伺います。","respondent":"川崎障害者施策推進課長","answer":"ただ、今、げんきのほうでは重度の方の受入れもされておりますので、そういった実績を踏まえて、今回民設民営でこちらを運営していくことで手を挙げていただきました。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"提案","question":"質問に答えられていないのですけれども、同じ条件であれば、同じ待遇というのですか、条件で入ることができるという、そのような提案になっているのかどうかということなのです。それが建設費もこれだけげんきが出し、そして運営費の補助金も、毎年毎年指定管理者では数百万円ずつ出しているというようなことも全くない中で、そのようなことができるのですかということなのです。","respondent":"川崎障害者施策推進課長","answer":"貸付費用の面を考慮しますと、仮に減額が最大限適用された場合においても、事業者の経済負担が大きく、事業者の参入が見込めないので、今回無償貸付ということで使用貸借契約を結び、３０年間の貸付けで民設民営で行うものになっております。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"ちょっと質問の意味が分からないのですか。無償貸付となっているのだから。だけれども、建設費はげんきが出すわけではないですか。建設費は。その上に、今まで指定管理者のげんきがやっている指定管理者は、区が建設費も出して、区立ですからね、建設費も出して、しかも毎年毎年、委託の委託料が数百万円出ているわけではないですか。そこのところどうなっているのですかと伺っているのですけれども。","respondent":"松山障害者支援課長","answer":"ただし、障害者施策推進課長が説明しましたように、げんきの家賃設定についてはまだこれからと伺っておりますので、同様の金額でということは、区としてはお願いしたいところです。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのほかに東京都の補助というものは、今回幾らぐらい出るのか、そしてグループホームの建設費というものは、およそ幾らぐらいかかるのか、その補助金の割合というものが何％ぐらいになるのか、だからその、何というのですか、げんきが持ち出すというか、建設費としてげんきが出さなければならないお金というものはどれぐらいになるのか、ちょっとその点を伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"補助金についてのご質問です。建設費としては、大体１ユニット１億円近くかかりますので、２ユニットになると２億円近くにはなります。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この募集、公募の実施要領の２ページのところなのですけれども、ここで重度、中・重度の障害者の方も見込んでの整備促進も図るというようなことになっているのですが、その場合、ここのところで身体障害との重複を含むということでなっているので、施設そのものとしては、バリアフリーでエレベーターもついているという、そのような施設ということに、きちんとこの重度の方も受け入れられるということで。","respondent":"川崎障害者施策推進課長","answer":"高齢化・重度化に対応した障害者グループホームになりますので、重度化に対応した障害者グループホームとして設備は整う予定です。具体的には、スロープであるとか、手すりであるとか、エレベーターが設置されているほか、あとスプリンクラー設置もご提案をいただいております。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"中・重度の障害者の方々が入れるグループホームということになりますので、この重度というものは、どの程度までの重度の方を受け入れられるということになっていくのか。そうすると、入浴の設備など、そのようなところも、何というのですか、重度の方が入れるような入浴設備など、そのようなところも整えられていくのか、その点についても伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"入浴につきましても、介護用の入浴ということで提案をいただいております。配置に関しましても、男性、女性と配慮をするような形で設定をするということでご提案をいただいております。もう１点、すみません。重度の程度ですか。ごめんなさい。もう１回質問いいですか。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この建設予定の建物というものは何階建ての予定でいらっしゃいますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"２階建てです。","id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"確認","question":"３０年だったらまだまだ利用ができるし、利用されている方も当然いらっしゃると想定できるので、ニーズがあって使える状況があるのに、わざわざ更地にして返すのは非常にもったいないかなということが、ごく普通の感覚になるのですけれども、区のルールとして貸付期間を３０年までと決まっていて、これは現状、原状回復で更地にして返すというようなルールになっているということで、改めてですけれども。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これに関して、このルールを変えることが難しいのであれば、やはり一般的な市民の感覚として、例えば３０年たって、何であれ、あそこの施設まだまだ使えそうだし、入居をされている方いらっしゃるのに、なぜ壊してしまうのだろうねという、多分一般的な感覚でそうなると思うので、ぜひルールを、ここで変えられるものではないと思いますけれども、やはりルールを変えるような検討をしていただくとか。","respondent":"川崎障害者施策推進課長","answer":"現在、区の公有財産管理規則では３０年と書いてはおりますが、協議により更新もできるですので、そのときの社会情勢を踏まえて、そのときの方針というものは考えてまいりたいと思います。","id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"質問","question":"協議により更新ということでお伺いして、非常にそれはいいことだなと思うので、それに関しては、何かこう取決めといいますか、例えば３０年たつ、何年ぐらい前からこのような話合いがスタートするとか、具体的なことというものはどのような取決めになっていますでしょうか。","respondent":"川崎障害者施策推進課長","answer":"取決めに関してですが、区として総合的に判断ということになりますので、今ここで何年前からということをお示しすることはできません。ただ、その都度、その都度の地域のニーズというものがありますので、そういったものを反映しながら決定していくことになるかと思います。","id":"exchange-028"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、一応ルールとして３０年になっているけれども、例外的事例も考えられるというような受け止めでよろしいでしょうか。","respondent":"川崎障害者施策推進課長","answer":"協議により更新できるということで進めていくことになります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"確認","question":"確認として、民設民営というものは、これいわゆるＰＦＩ、プライベート・ファイナンス・イニシアチブの方式ということでよろしいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"ＰＦＩではございません。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"民設民営は、私が調べたＰＦＩというものが同義だということだったのですけれども、ではこれは単純に、民設民営と指定管理者制度の違いというか、仕組みとしては、全部この社会福祉法人げんきが工事をして、それで運営はげんきがやられるということで、区の関与としては最初の土地の提供をしたというだけといいますか、そういった理解でよろしいのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"区としては、もちろん土地の貸付けを行っておりますので、今後も区が関与しないというわけではございません。もちろん定期的にヒアリング等はさせていただきながら、その都度お話合いを進めていくということになります。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"現状、その民設民営の運営形態を取っている品川区の福祉施設は、大体どのくらいなのでしょうか。障害者に限らずなのですけれども、お分かりになればお願いします。","respondent":"川崎障害者施策推進課長","answer":"今、区立として障害者グループホームは４つあるのですが、それ以外は民間ということになります。箇所数としては、今２２か所グループホームあるうちの４か所が区立、それ以外は民間ということになります。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"今後区としては、その方針として、方向性として、民設民営というものを増やしていくというようなお考えなのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。民間活力を使って、民間整備による障害者グループホームを促進していくと考えております。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問","question":"この小山七丁目のグループホームについては、住民説明会も何回かされてきていると思うのですけれども、この４回目の説明会のところが公開をされていましたので、ちょっとここのところから伺いたいのですが、隣接するところに小山の家と小山倶楽部があります。そのようなところでは、声はかけられたのか、あとかけられたところはどのようなところにかけられたのか、その点もちょっと伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"区のホームページで公表する前に、区内および近隣区等でグループホーム等の運営実績のある法人に対して、郵送やファクス等で周知は行いました。その数は４００件余りにはなります。実際説明会には５社の法人に参加いただきましたが、結果的に応募が１社という形になりました。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"出石のほうも、長岡福祉協会１か所というようなことでしたけれども、そのようなところでは、ほかのグループホームの運営もすごい厳しくて大変だという、そのようなお話も伺っているのですが、そういうところからすると、グループホームの運営そのものが、すごく運営事業者にとっては大変厳しいものがあるというようなところがそこに表れているのかなという思いがするのです。","respondent":"川崎障害者施策推進課長","answer":"今回は、応募参加辞退された方の事業者の回答によりますと、やはりこの障害者グループホームが中・重度の方を受け入れるということで、重度の方に対応できる対応技術を持った職員の確保が困難であるためという回答もございました。","id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"その適宜ということが、例えば１年間に１回はチェックをするなど、そのようなことというのは、何というのですか、マニュアルのようなものはなくて、何かがあったときに検査するというようなことになっているのか、そこの仕組みについて伺いたいということなので、お願いしたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"指導検査について私のほうからお答えします。指導検査は大体３年に一度の頻度で行ってまいります。ただ、何か事故等ございましたら、それはこちらのほうでも権限として、適切な運営がなされているかということは適宜指導しております。私からは入居者選定についてお答え申し上げます。委員おっしゃられるとおり、区が全く無関係でつくられたところにつきましては、直接、今も事業者と区民の方が直接契約となっております。","id":"exchange-036"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、例えば区の補助金をもらって、自分の土地に民設民営で建てたなどという、区の補助金を使った、または区の土地に建てた、無償で提供している、そのようなところは、もちろん区立はそうなのですけれども、そのようなところは区が一緒になって誰を入れるかということは関与していくという、そういう捉え方でいいのでしょうか。","respondent":"松山障害者支援課長","answer":"委員がおっしゃられるとおりです。最終的には、ただし事業者と区民との契約というものは、今の制度上はそのようになっておりますが、何かしらの形で区の関与というものが必ずあります。","id":"exchange-037"},{"speaker":"鈴木委員","kind":"提案","question":"この要領のほうで、最後のページのほうに提出書類というものをいろいろ出されているのですけれども、そこのところで、利用者の満足度を向上させる取組というものが提案されているということで書かれているのですが、これはどのような、具体的にどのようなことが提案されているのかということと、各室の面積表というものも提出されてるということなのですけれども。","respondent":"川崎障害者施策推進課長","answer":"こうした家族の認知機能が低下するよりも前に、早い段階で利用者の将来に向けた確認と手続が必要となるため、今後保護者には、例えば重度化・高齢化に伴う医療行為の開始とか、あと成年後見制度の活用であるとか、検査の範囲を含めて生活環境全般。","id":"exchange-038"},{"speaker":"鈴木委員","kind":"質問","question":"部屋の面積は７.４３m2よりも上回るということなのですけれども、具体的にどれぐらいかということは、分かったら教えていただけると。","respondent":"川崎障害者施策推進課長","answer":"今回身体障害の方も含みますので、例えば車椅子をご利用されている方も、居室として無理なく安定した生活を送れるような、ゆとりのある面積ということで提案をされております。","id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろ伺いましたけれども、改めて私は、区が民間の運営ノウハウも活かしながらというようなことで言われていますが、どちらにしても、指定管理者であっても民間が運営するということになるわけですから、そのようなところでは、区立のグループホームというところで方針を切り替えて、ぜひそのような方向でこれからは進めていただきたいということで、改めて要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"やなぎさわ委員","kind":"提案","question":"今鈴木委員がおっしゃられたように、民間の活力で民設民営という流れが進んでいることに対してのご提案ありましたけれども、先ほど、今回の公募で４００社ぐらい声かけをして、説明会に５社来て、応募が１社だったということで、説明に来られた５社の中で、実際応募しなかった法人から、重度介護者への対応は困難というようなご意見があったということで、改めてそのような受け止めでよろしいでしょうか。","respondent":"川崎障害者施策推進課長","answer":"重度化に対応できる技術を持つ職員確保は困難であるためという意見もございました。そのほかのご意見もございました。","id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そのほかの意見というと、ほかには何がございましたでしょうか。","respondent":"川崎障害者施策推進課長","answer":"１０人の、２ユニットを建てて本当にぎりぎりの面積ですので、実際２ユニットの設置が厳しいのではというご意見もありました。傾斜地になっておりますので、傾斜部分を平らにするという負担も含めると、工程も含めると難しいという意見もございました。","id":"exchange-042"},{"speaker":"やなぎさわ委員","kind":"質問","question":"となると、重度介護の対応困難というものは、あくまで少数意見というところでしょうか。","respondent":"川崎障害者施策推進課長","answer":"今回の説明会にいらした５社の中で、そのご意見をいただいたのは１社です。","id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"提案","question":"結局重度対応できないので、軽度の方向けのサービスに移行してしまうというか、そちらばかり増えてしまうというようなことも聞くので、ぜひ、やはりその点に関して、本当に民間の活力がどこまで当てにできるのか、自前でそういった能力、人材を持っているということは非常に強いことだという、力になる、強みになるということをぜひ考えていきたいと思いましたという提案と、あとすみません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"もう一度その内訳、大体でいいので教えていただいてよろしいですか。","respondent":"川崎障害者施策推進課長","answer":"都の補助金が７,９００万円ほど、品川区の整備費補助が５,０００万円です。それから開設に関わる補助金として、東京都のほうで５０万円ほど、そして品川区のほうの開設準備で１５万円ほど、そのほか借入金などもあります。","id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"というのは、つまり２億円、大体２億円で建設します。それで、お伺いする限り１億３,０００万円ぐらいは補助が出ますと。これ１億２,０００万円、３０年で割ると月３５万円なのです、大体。先ほど２階建ての施設というようにお伺いしたので、貸付面積３７８m2ということで、単純に倍にすると、７５０m2とか、それぐらいだと思うのですけれども。１００万円は確実に安くなるのです。長くなりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問","question":"この土地は区が取得しているわけですけれども、幾らで取得したのか、この額も教えてください。それからこれ、土地所有者から区への売却意向があって、区が購入するということになったと思うのですけれども、この土地所有者というものはもともと個人の方から売却意向があったのか、ちょっとそのところも教えていただけたらと思います。","respondent":"川崎障害者施策推進課長","answer":"ただ、現在計画を予定している隣の用地が小山在宅介護支援センター、小山の家がありまして、町会が役員会などで利用する際のスペース等については、小山の家と連携して町会と調整いただくようお話はしております。","id":"exchange-047"}]},{"id":"topic-04","title":"品川区介護予防・日常生活圏域ニーズ調査の結果報告","agenda":"品川区介護予防・日常生活圏域ニーズ調査の結果報告","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"すみません。１点だけお願いします。グラフの一番下にある、要支援のｎ４３の、この４３名の方というものは、ここの調査実施方法にある、1)番、調査対象の、原則要介護認定者は対象外とするが、認定時期等により含まれているという方の４３人と認識してもよろしいのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今回の調査対象が、原則要介護認定者、要介護１以上となりますので、この２ページで記載されています要支援（ｎ＝４３）というものが要支援１・２の方、そしてその上の事業対象者、ｎ＝３となってちょっと人数が少ないのですけれども、この方は介護認定を受けていないのですが。","id":"exchange-048"},{"speaker":"おぎの委員","kind":"意見","question":"分かりました。ちょっと下のほうの分類が分からなかったので、ありがとうあります。ほかには品川区独自にフレイル対策などもされているので、今回、第九期品川区の介護保険事業計画においてのタイミングのアンケートでしたけれども、こういった結果をその策定だけにとどまらず、関係する所管課などでも絶対共有して、いい方向に進めていけたらなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これ第九期の介護保険事業計画の策定に当たってということでの調査ということなのですけれども、国がニーズ調査の実施を推奨しているということで、実施していただきたい調査というところで、このような項目が国のほうでも出されていることを受けてされたことだと思うのですが、ここのところでも、区のほうの資料でも、目的のところに地域課題の把握。","respondent":"菅野高齢者福祉課長","answer":"今後、こちらが６５歳から７４歳までということで、今回は調査を取らせていただきましたが、こちら７５歳以上は高齢者地域支援課実施の介護予防把握事業でも同じように、要介護認定を受けていない方もはつらつ健康チェックといって。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問","question":"今のところは、その地域課題の把握というところが明確にはなっていないので、７５歳以上のそのようなものと併せて、これから地域課題がどのようなものがあるのかということを明らかにして第九期に反映をさせていくという、そのようなスタンスということでいいのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"委員おっしゃるとおりです。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実施していただきたい調査と実施を検討いただきたい調査というものが国のほうからは出されていて、検討していただきたいというものは区で検討して、やるかやらないかは決めてくださいというものだと思うのですけれども、在宅介護実態調査というものは、ぜひ国としては実施していただきたいという、そのようなものとして出されていると思うのですが、そのことについては、区としてはどうされるのか伺います。","respondent":"菅野高齢者福祉課長","answer":"こちらにつきましては、区のほうは、従来から給付適正化の通知の中で、実際に要介護認定を受けている方、約２,０００人に対しまして、毎年モニタリングアンケートというものを実施しています。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２,０００人に対して、そのような把握をしているからということですけれども、ではそれがどのような形ではまとめられているというものはあるのでしょうか。そのようなところで、どのように検討されているのかということを伺いたいと思います。それで、ここでもう本当に問題にされていることが、やはり介護離職の問題だと思うのです。","respondent":"菅野高齢者福祉課長","answer":"その方が３年に１回一巡して、給付費の通知が行くようにさせていただいているのですが、そのときに、せっかくだからということで、モニタリングアンケートのほうを実施させていただきまして、ケアマネジャーが定期の訪問のときに聞き取りをさせていただきながら。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"例えば、もう在宅では無理だったらば施設という、そのようなところも含めてのサービスにつなげていくということがすごく大事だと思いますので、そのような実態が現れるような形でぜひとも調査もしていただきたいし、まとめもしていただきたいし、そういう形でまとめたものがあるということであれば、介護保険のこれからの第九期の介護保険事業計画というものが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ご質問です。このアンケート、設問の中で、２１ページの「なるべく家族や周りに迷惑をかけずに暮らしたいか」という質問があるのですが、これはどういった意図といいますか、何を探りたいなというか、調査したいなという、意図があれば教えていただきたいのですけれども。","respondent":"菅野高齢者福祉課長","answer":"それで、実態としましては、やはり９３.９％の方がそう思うというところで、それが介護予防や健康づくり、健康維持などについての気持ちにつながっていくのかなというところで捉えているところです。","id":"exchange-055"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そういった意図だということは理解しました。別のところで、すみません、２３ページです。大まかな、今回のアンケートに関しての、これからの取組というものはこれからということでお伺いしているので、ぜひお願いしたいところで、この参加したいと思う「通いの場」というところで、１位は趣味の活動と。２位の体操、この２つが４０％を超えていて、かなりずば抜けていると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"ひがし委員","kind":"質問・要望","question":"はもう１点、先ほどあった介護のこと、２３ページの「通いの場」のところの内容と、あと国のほうで指定しているところ、７ページのところに介護予防のための「通いの場」への参加頻度というところ、そこを見ていてすごく思ったのですけれども、参加していないという方がもう９０％近く、男性は９１.８％で、女性は８６.７％ということで、もしかするとこの「通いの場」というところが。","respondent":"菅野高齢者福祉課長","answer":"今回、アンケートの質問についてお配りできていないので、質問の仕方についてどのように質問したかというところが少し分かりづらかったところが申し訳なかったのですが、こちら質問するときに、注釈として、「通いの場」の捉え方が。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"意見","question":"区として限定していたとしても、やはりもう少し参加しているという方々が増えていったほうが、せっかく区の中でもいろいろな事業をやられていて、素敵な事業多いなと思うのですけれども、ＳＮＳなどにアップしても、それ知らないと言われて、せっかくこのようなものがあるのでとお勧めするようなことも多いので、もちろん区議としても、区役所としても、発信というところはやはりもっともっと品川区。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"こんの委員","kind":"確認","question":"第八期で課題として出ていたものが、第九期を計画するに当たって、八期での課題はクリアされている、そういった理由で、新たな設問をここで第九期として必要で、質問の設問にしたのか、その辺の設問の設定の仕方というか、考え方をまず確認させてください。","respondent":"菅野高齢者福祉課長","answer":"耳の聞こえにつきましては、やはり区のほうで補聴器助成のほうが始まっておりまして、区の施策として進めていくに当たって、せっかくのこのアンケートを取るので、ここについて少し触れさせていただこうかなというところで取り入れさせていただきました。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問","question":"その狙いでこの３点が今回ニーズ調査をされたということで、ほかにも多分ニーズを把握しておかなければいけない内容というものはあったのではないかと思われるのですけれども、あまり設問が多くなるとというところもあって、絞ってこの３点にしたと。ほかにニーズ調査が必要だと、課題だと思っている点があれば、その点教えてください。","respondent":"菅野高齢者福祉課長","answer":"やはり今後高齢者がどんどん増えていく中で、少しでも介護件数が抑えられて、そして皆元気に、健康寿命を延ばしていくためにはというところで、やはり健康維持や介護予防というものは重要だろうというところで、前回に引き続き対応させていただいたというところと。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問","question":"だけれども、その辺の手が、なかなか介護の認定もない中で、総合的な支援もありますが、その辺の、どういった体制を、仕組みをつくっておいたほうが今後いいのか。その辺、いや、別のところでそうした細かいところはニーズをきちんと拾い集めて、第九期に反映をさせていくように準備をしているのだとか、そのようなものがあれば、その辺教えていただければと思うのですが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"それらでいろいろな地域の相談事などを吸い上げて、例えば支え愛・ほっとステーションで介護が必要だなという状態が分かったときには在宅介護支援センターのほうにご紹介するし、在宅介護支援センターのほうでは、まだ介護サービスではないけれども。","id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"とても残念な話で恐縮なのですが、私今年になって、孤独死をされた方を３人知っています。ですから、孤独死対策もそうですし、お独り暮らしの方の見守り、それから生活支援、こうしたところが、やはりお独り暮らしの方も増えています。ヤングケアラーという問題もありますし、そうした観点からのニーズ調査というところも必要だろうと考えますけれども、重ねていかがでしょうか。","respondent":"菅野高齢者福祉課長、東野福祉計画課長","answer":"反対にあなたが心配事や愚痴を聞いてあげる人はいますか、そのような設問がなされておりまして、こちらについては、やはり回答としましては配偶者が１番で、あとは友人、あと兄弟姉妹などとなっております。国から孤独・孤立対策室のほうの成立に当たりましても、区として、それに対しての、孤独・孤立に対する考え方を十分これから浸透させていきたいと考えていますので、そういったところと併せ持って。","id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"今後、３年に一度のニーズ調査だというところですので、設問が、いわゆる３年後、また新たな設問、そのときのニーズ、社会情勢も併せてされるということだと思うのですけれども、国の考え方や、この設問の在り方が変わらない限り、国の設問は触ってはいけませんよ、区独自のものは独自で設問を考えていいですよということだと思うのですが、その辺、もし国のものも少し触っていいということになったときには。","respondent":"菅野高齢者福祉課長","answer":"委員のおっしゃるとおり、やはりそういった地域の、今介護サービスになかなかつながっていない方をいかに拾い上げるかというのか、手を伸ばせるかということは大きな課題だと思いますので、様々な手法を考えながら。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問","question":"有効求人倍率、訪問介護などというものは非常に高くて、人手不足という現状があります。これ質問なのですけれども、８ページのところで、収入のある仕事への参加というところなのですが、これ、していますともし答えた方に、例えばどのような理由で収入のある仕事をしているのですかというような、仕事をしている理由というものを深掘りして聞いたりしているような設問というものはありますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"こちらが問５になりますので、国の指定の質問の仕方というようになっております。それで、収入のある仕事というところで、この集計表にもあるように、週４回以上、週２～３回週１、月１～３回、年に数回という、この設問の仕方でしか聞いていないという実態です。","id":"exchange-064"},{"speaker":"やなぎさわ委員","kind":"質問","question":"かしこまりました。ですから、これが高齢者の貧困、物価高もあったり、アンケートを取ったときはまだそうではないのかな、でもそういった、働かざるを得ないというような状況もあるのかなということで、ちょっとお伺いさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"筒井委員","kind":"確認","question":"ちょっと聞き漏らしていたかもしれないのですけれども、確認で、このアンケートを６５歳から７４歳までにした理由というものは何でしょうか。その７５歳以上の方の把握というものはやられないのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"７５歳以上の方につきましては、高齢者地域支援課実施で、介護予防把握事業というものを毎年行っております。","id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。なかなか難しいことだと思うのですけれども、これ、今現状どうお考えなのか、そしてこの課題が解消されていなかったら、第九期にどのように反映されていくのか、区のお考えをお聞きしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"その中でも、委員から課題等もいろいろと、地域のお声などもいただきまして、それらも踏まえて、第九期に向けてブラッシュアップさせていただいて、新しい課題は取り入れつつ、さらに進めなくてはいけないもの、国のほうも、地域包括ケアのさらに進化というところで。","id":"exchange-067"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。孤独死の問題だとか、これからどんどん高齢者の方が増えていって、そしてそのつながり、行政とのつながりをどうするのかという大変難しい課題かと思うのですけれども、ぜひブラッシュアップして進めていっていただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのような点では、ますます介護人材の確保の状況というものは深刻な状況が広がっていると思うのですけれども、そこのところは、区として、これは厚労省で検討いただきたい調査ということなので、何が何でもやらなければいけないということにはなっていないのですが、そのような点では、区としては、この介護人材実態調査については、やる、やらないということは検討されたのか、また。","respondent":"菅野高齢者福祉課長","answer":"介護人材の部分につきましては、令和３年度に区のほうで、介護職員確保戦略の作成に取り組ませていただきました。","id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問・要望","question":"介護の福祉の専門学校にしても、それを頑張って続けているというところは評価するところですけれども、定数に満たないということがずっと続いていますし、それだけではとても賄い切れるというような状況ではないので、そこのところは、実態調査で実態を浮き彫りにする中で、やはり改善をさせていくという具体的なところが求められていると思いますので、そのような、つながるような方向で、第九期に向けて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]},{"id":"topic-05","title":"品川区立平塚高齢者多世代交流支援施設（平塚ゆうゆうプラザ）指定管理者候補者の選定","agenda":"品川区立平塚高齢者多世代交流支援施設（平塚ゆうゆうプラザ）指定管理者候補者の選定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"これまで福栄会が５年間やってきて、基本的に福栄会でということで審査をするということになっていくということですよね。それで、９月に選定委員会および予備委員会、選定委員会をやるということになっているので、もう既に選定委員会や予備委員会がどのようなメンバーなのかということは決まっているのかなと思うのですけれども、そのメンバーについて教えていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"予備委員会に関しましては、庁内の関係管理職員５名で予定をしています。次に、選定委員会につきましては、選定予備委員会の内容の結果を踏まえまして、庁内の管理職員２名、および有識者委員として外部より２名、１名が行政の経験者、１名が学識の経験者をお呼びする予定です。","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この予備委員会も区内の関係の理事者になると思うのですけれども、そこは具体的にはどのようなところなのかということと、有識者の外部からの２名というものも、誰なのかということは、ここで報告をいただくことは可能であれば、もう決まっていると思いますので、その点についても教えていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"今、こちらの委員会の報告につきましては、あくまでもこれから実施をする予定ということで申し上げる形です。具体的な人員の内容につきましては、次回の報告の際に決定という形でご報告を申し上げたいと考えています。","id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問","question":"これまで福栄会が５年間指定管理者ということで受けてきたわけですけれども、ちょっと私もモニタリングの結果などを見てくればよかったなと思ったのですが、それをちょっと見てきていないのですけれども、福栄会が行って、何というのですか、今、平塚ゆうゆうプラザのところでの課題、解決すべき課題など、そのようなものがあったら、どのようなものなのかということもお聞かせください。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました、現指定管理者が実施する上での、運営上の課題についてあればということのご質問です。私どもの課で認識をしていますのは、これまで約２年から３年間、コロナで地域に向けた事業が実施できない形でおりました。","id":"exchange-073"},{"speaker":"鈴木委員","kind":"提案","question":"今回同じ福栄会ということで、審査されるに当たっても、多分提案だったり、これからこうしていきますよという計画というものは出されるわけですよね、書類としても。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問","question":"この選定の方法について、公募によらず特定の事業者を選定ということで、いつもだと公募型のものでやっていることが多いかなと今まで認識していたと思うのですけれども、この施設の設置目的や事業内容などに特別な理由がある場合は、公募によらず特定の事業者を選定することができるものとするとあるのですが、この特別な理由というものは何か教えていただけますでしょうか。","respondent":"川原高齢者地域支援課長","answer":"平塚ゆうゆうプラザに関しては、ほかの高齢者福祉施設と大きな違いが１つございまして、１階が高齢者がメインの施設になっているのですけれども、２階が在宅子育て支援事業がメインのオアシスルーム、ポップンルームの一部のお子様の預り事業をやっている親子の広場。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問","question":"管理に関わる経費といったところでは、いわゆる施設の、建物だったり、設備だったり、そうしたもののことをおっしゃっているのか、いわゆるこの縮減といったところは非常に大事なところではあるのですけれども、それによって、運営自体に何か支障というか、その縮減をするために何か違う、いわゆるサービスにとか、そうした運営に関わってしまうようなことになっては本末転倒だなと考えるのですが。","respondent":"川原高齢者地域支援課長","answer":"はもう一つ、設備の修繕というところ、本末転倒にならないようにというところがございまして、大規模な修繕、施設整備課が関わるような大きな修繕に関しては、区のほうできちんと予算要求を別でいただいて出しているような形ですので。","id":"exchange-076"},{"speaker":"こんの委員","kind":"質問・要望","question":"よく分かりました。サービス向上というところでは非常にありがたい話です。選定委員会のときに。ぜひその辺のサービス向上というところも今後期待をし、その辺のお話もよく引き出していただきたいなと思います。経費のところも同じです。その辺の運営の仕方についてのことも、しっかり聞き取っていただきたいというか、といったところをお願いして、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"}]},{"id":"topic-06","title":"新型コロナウイルスワクチン令和５年秋開始接種","agenda":"新型コロナウイルスワクチン令和５年秋開始接種","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"今回、国でこのように、９月から全世帯に向けての接種が、新たなＸＢＢなどというワクチンですか、やるということですけれども、まず、この上から順番にお聞きしますと、生後６か月から４歳までの対象の方が新たに今回入ったということで、この接種の接種券、接種券も併せてなのですけれども、発送は、だから６０歳以下になりますから、９月１１日以降という形でいいのか、確認です。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"それ以外の６０歳未満の方につきましては、９月１１日に発送です。次に２番の接種券についても、接種された方と接種されない方の認識ですが、委員のお見込みどおりの対応となっております。","id":"exchange-078"},{"speaker":"こんの委員","kind":"質問・要望","question":"６か月から４歳は分かりました。それから、同時接種というところを１つ伺いたいのですけれども、インフルエンザと同時接種可能でしたよというものが、たしか３月に行われた予防接種、今年のものではインフルエンザと同時接種が可能というものがあったかと思うのですけれども、今、帯状疱疹の予防接種が始まって、そちらをしたいという方との同時接種というものはどうなのでしょうか。その辺も教えてください。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"接種状況等を踏まえながら、特に接種の勧奨がある方たちに関しての、何らかの周知方法というものも、接種状況を見ながら検討を進めてまいりたいと考えています。","id":"exchange-079"},{"speaker":"こんの委員","kind":"質問・要望","question":"２週間空けるということですけれども、最低でも２週間空けての接種といったところの、その間隔も、ぜひこのお知らせの中にでも入れていただくことが可能であれば、そういった文言も入れておくということも１つかなと思うのですが、もうその準備が、９月の上旬、中旬でもう発送の準備ができているということなので、そのお知らせに入れることは今の現時点では難しいとなれば。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"１点目、未使用の接種券をお持ちの方で、今回発送対象外となる方にも周知をですが、こちらも接種の状況等を踏まえながら、例えばこれまで接種勧奨はがきのようなものを送っていた事例もありますので、あと今回接種勧奨がある６５歳以上の方等に向けて。","id":"exchange-080"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですから、関心のある方は接種しようという方ですけれども、そうでない方は、いろいろなお考えがあって接種する、接種しないというようにはあると思うのですが、今このオミクロン株のＸＢＢという型が流行というか、増えているという現状からすると、こうしたことも打っておいていただきたいという、その発信は、やはり区からの発信は非常に大事だなと思いますので、その体制を取ることも、今までの実績等。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"質問","question":"今マスクを外すようになって、コロナが増えているという医療現場からのお話もある中で、ワクチンを接種してほしいということは区からも発信していくとは思うのですけれども、そこに対して、やはり不安を持っている方もいるのではないかなと思っていて、特に新しいワクチン、このＸＢＢという新しいものに、打つと何か副作用が、何が出るのだろうなどという不安を抱えている方々に対しての対応。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"以下、ご質問ありました接種券等の問題も含めまして、希望される方が接種をしていただけるような体制を組んでまいりたいと考えています。","id":"exchange-082"},{"speaker":"ひがし委員","kind":"質問・要望","question":"やはり不安を抱えている方々というものは、ワクチンを打とうと思わないですし、そのような方々の声を聞いてしまうと、やはり実施率が下がってきているという状況がある中で、ワクチンを打ちに行くことも時間がかかっていますし、そのようなところで考えると、やはり普及をしていくための安全性の周知というところはしっかりと品川区でも示していかなければいけないなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら質問というより要望なのですが、もちろん希望される方もいらっしゃる一方で、実際打ってかなりひどい、重症な副反応が出てしまった方、被害者の会の方から話を聞くことが最近多いのですが、症例を聞きますと、人によってはかなり壮絶な内容で、非常に生活も困難になってしまっている方もいらっしゃいます。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"接種の際にも、副反応や安全性等を説明していくよう、医療機関のほうにはお伝えしていきたいと思います。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問","question":"これ区だけの問題ではないと思うのですけれども、最近変異株、新しい変異株ＢＡ２.８６というものが出て、東京都のホームページでも載るようになりましたが、こういった場合、このＸＢＢ.１.５に、ＢＡ２.８６が、既存のワクチンが反応しなくなる可能性もあるという指摘が出ていて、そうした場合、この今までのＸＢＢ.１.５しか通用しないワクチンはやはりやめたとか、そういった変更の措置を取るとか。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"国のほうでおきましては、流行している主流株の対応したワクチンを使っていくことが望ましいと示されておりますので、今回の秋開始接種におきましては、ＸＢＢ.１.５対応のワクチンを使うということが示されておりますが、今後流行主流株のほうが変わっていきましたら。","id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問","question":"コロナに感染したときに、特に高齢者の方が重症化して、命にも関わるという問題になる、それが問題だと思うのですけれども、そのような点で、高齢者施設に入所されている高齢者の方や、在宅でこのような医療機関まで行けない方のワクチンの接種の体制というものはどうなっているのかお伺いしたいと思います。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"重症化リスクの高い高齢者の方に対する対応ですが、区でこれまで高齢者、障害者等も、入所施設の方向けに巡回接種を実施しておりまして、こちら秋開始接種におきましても継続をしていきたいと考えています。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"確認","question":"先ほど委員というか、どなたの委員か分からないですが、確認なのですけれども、基本的には打ってくださいというか、打ってくださいね、打ってほしいというようなスタンスなのでしょうか。ワクチンに関して、コロナの。品川区のお考えはいかがでしょうか。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"接種につきまして、希望される方は接種いただく体制を取ってまいります。今回、特に接種の勧奨や努力義務があります６５歳以上の高齢者の方、基礎疾患のある方等につきましては、接種のほうをお勧めしていきたいと考えております。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"周知という意味でいうと、例えば基礎疾患ある方というように考えると、介護施設、デイサービスに通われているような利用者の方というのは、ほぼ基礎疾患がある方ですので、周知という意味でいうと、例えばそのような介護施設などにポスター掲示をお願いしたり、そういったことも１つ有効な周知の方法だと思うのですけれども、そういったことというのはお考え、予定はありますでしょうか。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"重症化リスクが高い高齢者の方、特にデイサービスに通われている要介護者の方への周知ですが、これまでも高齢者福祉課等、所管部署と連携しまして、高齢者施設に対してそういった周知をしていただくようなお願いをしています。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ただ、別に私は打て打てと言っているわけではなくて、それはやはり、打つ打たないは個人の自由だと思うので、それは自由として、やはりそのリスクとリターンの考えられるというか、どちらでも選べるような環境で、あとはそういった情報を極力開示して、選択していただくということが大事だと思うので、ほかの委員の方もおっしゃられたと思うのですけれども、選べる判断材料というか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"}]},{"id":"topic-07","title":"その他","agenda":"その他","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"この頂いているパンフレットというか、チラシは、これもう実物ということでよろしいですか。","respondent":"松山障害者支援課長","answer":"取り急ぎ、こちらのほう印刷させていただきましたが、印刷中でございまして、完成版がありますので、改めてご案内申し上げます。こちらのほうはそのまま印刷に委託をしているものですので、情報は変わらないのですが、改めて別途、委員の皆様にはご案内申し上げます。","id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":61895,"voices":243}},{"id":"r05-20230821-8","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"建設委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年９月区民住宅（空き室）入居予定者登録募集","agenda":"令和５年９月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これまでの応募倍率などを含めて、募集の状況を伺いたいと思います。それと、去年の議事録を見たところ、入居された方がこの間結構増えているのですけども、令和２年度が３０件、令和３年度が６０件ということで倍に増えているわけですが、この増えている理由を伺いたいと思います。","respondent":"竹田住宅課長","answer":"近年、入居者数が多くなっている件ですが、考えられるところでは２つございまして、一つは、今までお住まいの方が退去をされた関係で、お部屋の空きが出ると入居者数が必然的に増えるということが一つと、もう一つは、かねてより空き室対策を様々行ってまいりましたので。","id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"なるべく多くの利用希望者に利用していただきたいという視点から、お伺いしたいのですが、申込書の配布期間が９月１２日から２２日までに対しまして、受付が２９日まであるわけですが、そうすると、２２日から２９日の間は、受付はするけれども配布されていないので、区民の方としては、申込用紙を入手することはできないというふうに受け止めてしまっていいのでしょうか。","respondent":"竹田住宅課長","answer":"２点のお尋ねです。申込用紙の配布期間ですが、ルール上は先ほど申し上げた日付までですが、皆様コロナ等様々なご事情がありますので、内容によっては柔軟に対応していきたいと考えております。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"申込数と比べると入居者は少ないです。１００％入っていないですよね。そうなってくると、品川区民の皆様方にとってこの区民住宅の魅力がどうなのかな。そして、当初の目的と、かなり意味合い的なところが変わってきてはいないかと思うのですけど、その辺はいかがですか。","respondent":"竹田住宅課長","answer":"全体の入居率というのは９５％なのですが、施設によって若干、人気の高いところ、そうでないところがありますので、人気が高いところはこれ以上仕方ないのですが、人気がもう一つというところも、お部屋のリニューアルとか。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"なので、そうすると品川区の予算の中にこれが今後入ってくるのか。区民住宅の、人気のあるところはいいとしても、人気がなくなってきているところについては、ほかの転用だって考えなければいけない部分が出てくるのではないかなと思うのですが、品川区の全体の住宅事情に対しての区民住宅の意味合いというのはどういうふうに捉えられて、これから進められていくのでしょうか。","respondent":"竹田住宅課長","answer":"区民住宅の全体の考え方ですが、まだ築年数が浅いものも多いですし、まだまだ使える施設が多いと考えていますので、大事にメンテナンスしながら使っていくのですが、委員おっしゃられたとおり、まちの再開発等、まち全体が変わっていくという中では、そのまちの形成に基づいて。","id":"exchange-004"}]},{"id":"topic-02","title":"戸越６丁目地区における地区計画の変更","agenda":"戸越６丁目地区における地区計画の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"２月に説明会を実施されたということで、この素案説明会ではどんな意見や質疑があったのかというところを伺いたいと思います。そして、アンケート調査も行ったということで、その中でも意見や質問があれば、そこのところも伺いたいというふうに思います。今回、その範囲を拡大するということで、東地区のところでの変更点はあるのかどうかも伺います。","respondent":"小川木密整備推進課長","answer":"３点目、現在の東地区の内容で何か変更があるのかというご質問ですが、東地区の内容については変更等はございません。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"建て替えへの支援の延長などを求めるというような声も出ておりました。今回、既に東側の地区でやっているところですけども、補助２９号線を前提とした変更であるということもありますので、やはりそうした、住民が追い出され、暮らしが壊されると、商店街も存続できるのかということになってしまいますので、補助２９号線を前提とした計画を進めていくというのはやめるべきだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"だけど、実際そこに住んでおられる方がどういう影響があるのかというのは、やはり具体的なところがないと想像できないというところで、分からないという人が多いのかなというふうに私は感じたのですけれども、特にこの2)の、敷地面積の最低限度６０m2という、これ、前々からこの近隣の地域もそういう形になって設定をしているのですが、では、これより小さい家をどうするのですかと。","respondent":"小川木密整備推進課長","answer":"２点目の具体的な内容等が分からないといった地域の皆様からのご意見等ですが、この意見に関しましては我々もしっかりと受け止めて、協議会、説明会、また、まちづくりニュース等を発行していますので、そういった中で、丁寧な説明に努めてまいりたいというふうに考えてあります。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"この地区施設の設定というのは、地区施設になると何かメリットがあるのですか。知識がなくてすみません。ちょっとそれを教えてください。これ、いろいろと対策を品川区の中で取られていたと思うのです。なので、初めからご理解いただくように、ほかの地域の事例であったり、いろいろな策を取っていますよというようなことを具体的に、ぜひ示していただきたいと考えていますので、その辺はいかがでしょうか。","respondent":"小川木密整備推進課長","answer":"敷地面積の６０m2以下に関しましては、委員おっしゃられたとおり、しっかりと説明していきたいといったところで、やはり敷地の細分化による、密集の再生産、そういったものには絶対ならないように、我々もこれは必要なことだと考えておりますので。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"要は、それぞれのご事情もあるのでしょうが、例えばですが、相続などでここを分割しなくてはいけないというような場合に１２０m2以上ないと、この地区ではそういう分割ができなくなってしまうわけですが、その辺の理解をどれだけ得ていくかということが私は必要だと思っていて、これまでの東地区の地区計画を指定する際には、まずは、そもそもは地元発案で。","respondent":"小川木密整備推進課長","answer":"それで、そちらの勉強会が検討委員会となりまして、その検討委員会から、戸越６丁目東地区のまちづくり案というものが提出され、今現在定められている地区計画に至っているところです。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、四間通りは、恐らく６ｍはあるのかなと思えるので、防災生活道路としての要件というか、その形だけのものは満たされているのかな、大原通りはちょっと確認が必要なところもあるのかなと思うのですが、要はその外周の部分が防災生活道路とかに指定されていない、あるいはＢ、Ｃ、Ｄのような地区割りがされていない理由は何なのかをお聞かせいただきたいと思います。","respondent":"小川木密整備推進課長","answer":"ただ、大原通り等に関しましては、防災生活圏事業でその防災生活道路という位置づけもありますので、そういった意味では大原通りに関しましては、しっかりと位置づけのほうを行ってあります。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"東京都が発表している地域危険度の地図でも、戸越６丁目よりもその近隣の豊町のほうが総合危険度が高いという示されもしておりますので、たまたまというか、ここは戸越５丁目と豊町６丁目の区域との接続部分で、豊町３丁目、４丁目もあるのでしょうか、半分ということなので、地区計画としては指定されていないということで、そこの全体の防災の視点からは、そこもしっかり続けていただきたいと思いますが。","respondent":"小川木密整備推進課長","answer":"連続立体交差事業と今回の地区計画の変更との関係で素案説明会でいただいたご意見に対しましてですが、委員おっしゃられるとおり、この防災生活道路、２号と３号がちょうどこの連続立体交差化計画が影響するところですが、こちらの２か所につきましては。","id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"何か具体的に、例えば、今まで東京都の見直した想定だと、ここでは何棟倒壊するのをこういうことによって何棟に抑えるとか、さっき道路の幅が６ｍというのはお聞きしたのですけれども、ちょっとそこら辺、地元に対してどういう、さっき地元の住民の方も、もう少し何か具体的にというのは、多分そういうことなのかなと思うのですけど、もう少しご説明いただきたい。","respondent":"小川木密整備推進課長","answer":"今回のこの地区計画の指定ですが、この地区計画は、ある意味では強制力といいましょうか、建築物等を建てる際のルールが、これは条例で定められることになりますので、建て替える際、土地を６０m2以下に分割して建て替えることはもうできなくなるといったり。","id":"exchange-012"},{"speaker":"若林委員","kind":"質問","question":"そういうのは、今のこの密集とか不燃化の中ではできないのだという、いわゆる指導とかご案内とか、今、国はこういう制度があって、助成制度があってというご案内はできるけども、一定の強制力を持つことは、この２つの、今ある制度の中ではできないのだと。だから、今回の新しい地区計画で、いわゆる今おっしゃられたような制度をしっかりとつくっていくのだという理解でよろしいでしょうか。","respondent":"小川木密整備推進課長","answer":"今の不燃化特区、また、密集住宅市街地整備促進事業ではできないという形なのですが、ただ、側面が違うというか、あくまでも、不燃化特区に関しては助成事業ですし、密集住宅市街地整備促進事業に関しましてはまちづくりの方向性を示すものです。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで少し期間が空いて、令和８年４月から建設が始まって、令和９年６月末頃に終わるという予定ですけども、この間、分室がなくなってしまうというところで、この事業の継続はどうなってしまうのかというところを伺いたいと思います。それで、今回、３施設統合することで、荏原庁舎と西小山分室、中延中継所のところが空くと思うのですけれども、その後施設の活用などはどのように考えているのか、伺います。","respondent":"品川品川区清掃事務所長","answer":"２点目、解体の間につきましては、品川庁舎、大崎のほうの品川清掃事務所のほうに人員のほうは持っていく予定です。それから、出入口、ここは委員おっしゃるとおり、山手通りですぐ曲がったところになります。それから、少し下りにもなっているところです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"統合したというところではいろいろ、コスト面とかお話がありましたけれども、２０１９年の予算特別委員会では、多分、北品川分室のところかな、大崎のほうに統合したいというような方向性で考えているという話だったのですが、それが変わって今回、移転するというところでの検討の経緯というのはどういったことがあったのかを伺えればと思います。","respondent":"品川品川区清掃事務所長","answer":"２０１９年時点でのお話のほうですと、これはあくまでもほかの分室を残すというような考え方の中で進めていたものです。ある程度北品川分室に限定して考えていったところというのもありますので、今回に至っては、やはり品川区内の分室全体の在り方について検討した結果です。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問・要望","question":"分かりました。対象がどういう方なのか、もちろん公園の利用者とか、子ども、保護者などが参加できるようにしていただきたいと思うのですけれども、いかがでしょうか。そうすると、使い勝手という面でどうなるのかなという心配があるのですけども、そこは使いやすいようにしていただきたいと思うのですが、区のお考えを伺いたいと思います。","respondent":"高梨公園課長","answer":"詳細については、今年度と来年度で実施する設計の中で決めていきたいなというふうに思いますが、大きく野球場の場所を動かすと、既存樹木をどうしても移植や伐採をしなければいけないということにもつながってまいりますので、現在植えている樹木の状態や。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうですね。この児童相談所を造ったときに、いろいろ、かいじゅうが撤去されたりとかで、やはり住民の皆さんあるいは子どもたちが悲しんだということがありましたので、今回、整備に当たってそういったことがないように、やはり十分に、利用者の方、保護者の方にも周知をしていっていただいて、子どもの声をしっかりと反映していっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません。１点確認が、子供の森公園のほうですけれども、野球場があったのです。それも入って、ここの子供の森公園という形で配置換えをするという理解でよろしいでしょうか。児童センターもあるのです。そういう人たちにもぜひ聞いていただきたいです。なので、清掃事務所のほうも、やはりそういう車の行き来がとても怖いなと思っているのですが、ここは何か特別、整備をするとか何かあるのでしょうか。","respondent":"高梨公園課長、品川品川区清掃事務所長","answer":"周知につきましては、児童相談所建設の際も、複数回にわたる説明会や、その結果を受けての、公園内での掲示等々、様々周知を行ってきたところですので、今回も１０月に説明会を行いますが、しっかりと、利用者や近隣の方々に。やはり、非常に危ない位置だというところは我々も認識をしておりますので、例えば回転灯の設置だとか、それから誘導体制、こういったところなどを今後建築するに当たって工夫していきたいというふうに考えております。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、例えば、小さいお子さんだと絵を描いてもらうとか、こういう経緯でこういう意見をもらったよ、こういう形になってきたよと、その経緯というのか、ワークショップやるのはいいのですが、子どもたちのアイデアを活かした公園というのを非常に手がけてやっていることはいいのですが、もう一歩進めて、どんな意見があったの、どんな夢を語ってくれたのという、そういうのも紹介するとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、清掃事務所の庁舎分室の移設ということで、確かにご説明の中にもあったとおり、東京都から清掃事業が移管されて、品川区が直接担うことになった中で、東京都から移管を受けた施設をそのまま使い続けていたけれども、ということなので、いよいよここで正式に、その平成１２年だったか、清掃事業が区に移管されたときの。","respondent":"品川品川区清掃事務所長","answer":"議会とのやり取りの点ですけども、再編に当たっては今回案件を出すのは初めてですので、これまではなかったというふうにお答えするのが一番よいかと考えています。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、もう少し具体的に言うと、すみません、私も事務事業概要を見ている中で見落としがあったのかもしれませんが、中延の中継所というのがありますが、事務事業概要には載っていないのですけれども、これ具体的にどういうものなのかということと、今後は、荏原地区のそういう施設を品川の庁舎とこの北品川分室で全てを賄うという中で、外に対しての交通の安全性ということは今、るる指摘がありまして。","respondent":"品川品川区清掃事務所長","answer":"要するに、荏原地区は狭小地が非常に多いので、軽自動車等で回りながら、中延中継所に大きな清掃自動車を用意しまして、そちらにごみを積み替えるというような場所で、使用しているというものです。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の再編で、公園がある中に児童相談所ができて、さらに、その隣に北品川分室ができるということで、安全性のことももちろん配慮する必要があるのですけれども、また、一方で児童相談所の運営に対しても、私はしっかり配慮していただく必要があるのかなと思います。そこだけ１点、ご決意のほどをお聞かせいただきたい。","respondent":"品川品川区清掃事務所長","answer":"児童相談所の件ですが、既にこの計画を進めていく中で、児童相談所のほうとは話を進めておりまして、現在のところでは、いろいろと話合いをしている中で問題点等は発生していないのですが、今後また、発生するようなことがあれば、建設時等にも対応策等は考えていきたいと。","id":"exchange-022"},{"speaker":"まつざわ副委員長","kind":"質問","question":"私も、移設される清掃事務所の入り口はやはり反対側が、山手通りの２車線から１車線になる、それで危険でというのはよくニュースでもやっているので、確かにあそこは、逆側は２車線のまま行くからちょっと広いですけど、基本１車線ですから、確かに何か止まっていると渋滞して危ないなというのがあるので、そこら辺は相当気をつけて注意喚起していただければと思っています。","respondent":"高梨公園課長","answer":"残せる設備であったり樹木であったりというものは当然出てくるかもしれませんけども、考え方といたしましては、全面の改修、再整備改修工事ということで捉えていただければと思います。","id":"exchange-023"}]},{"id":"topic-03","title":"Ｏ歩道橋補修工事","agenda":"Ｏ歩道橋補修工事","exchanges":[{"speaker":"田中委員","kind":"確認","question":"それが直結したときに、相当の人数がまた、この歩道橋を利用する可能性があるわけですが、そういったことも、今のＯ歩道橋の構造的なものを踏まえた強度になっているのか、ちょっとそこを確認したい。","respondent":"森道路課長","answer":"当然、今３０ｍ以上はある橋ですけれども、真ん中に支柱がなくても、３０ｍの橋がきちんと保たれると、それで耐震上も大丈夫だというふうな形で、主要部材の構造が決まっているということもありますので、通行量が増えても。","id":"exchange-024"},{"speaker":"若林委員","kind":"質問・要望","question":"工事期間が８月１５日からということで、既に月日上は始まっているということで、来年の１月３０日まで。一番下の、夜間作業のところ、あと交通規制のところだけ聞きたいのですが、夜間作業の何か具体的な時間帯とか日にちとかが出ていれば、まず教えていただきたいと思います。","respondent":"森道路課長","answer":"あそこの下の都道につきましては、片側２車線、合計４車線ありますけれども、それを１車線ずつ通行規制しながら、少しずつずらしていくというような形になりますので、基本は、片側１車線、片側２車線というのは確保しながら進めていくというふうに考えておりますが。","id":"exchange-025"},{"speaker":"木村委員","kind":"質問","question":"今この写真を見ていて、一番下段の右側にあります、この画像、外装版の補修ですか、道路と陸橋との段差がありますよね。できればこういうことに対しても全て改修をしていただければと思っているのですが、ご意見をお聞かせください。","respondent":"森道路課長","answer":"今、委員ご指摘のように、車椅子とか、あるいはベビーカーを押される方、ご高齢の方、バリアフリーは道路としてもしっかりと取り組んでいく必要があると考えておりますので、現場を再確認させていただいて、例えば、黄色と黒のテープでまずは周知をするということもありますし。","id":"exchange-026"},{"speaker":"木村委員","kind":"質問・要望","question":"よろしくお願いしたいのですが、やはり本当に自分がそういう体になって初めて、そういうつらさというのがよく分かりますので、できればそういう点について細心の注意を払っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"この歩道橋は品川区の持ち物なのですねということなのですが、本当に勉強不足で申し訳ないのですが、ここはＪＲのところを使っているのでＪＲと折半で造っているのかななどという思いはあったのですけど、ここは完全に品川区の持ち物という形で整備がなされて、予算立てのほうも品川区の財源から出ていますよということなのでしょうか。そこを確認させてください。","respondent":"森道路課長","answer":"Ｏ歩道橋につきましては、大崎ニューシティ側のところ、大崎ニューシティの敷地のほうに入る部分が、約８ｍ弱ぐらいなのですけれども、そこの８ｍぐらいの部分については、大崎ニューシティ管理組合の持ち物という形で。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"自分のところもかかっているからということなのでしょうけれども、もうちょっと協力してもらいたいなという部分があるのですが、ぜひここに限らず、全体の利用者の方々の利便性がよくなるように、いろいろとこういう協力体制を取られている部分があるので、ぜひ前に一歩一歩、ちょっと違うところからも関係性づくりというのをお願いしたいなというふうに思っているのですけれども、その点はいかがでしょうか。","respondent":"森道路課長","answer":"その５分の１で費用負担を案分しているということになりますので、なかなかこれ以上お願いするというのは難しいのかなというふうに思いますけれども、何かしら改修なりしていく中で引き続き、様々、意見調整していければというふうに思っています。","id":"exchange-029"}]},{"id":"topic-04","title":"荏原中央公園改修工事","agenda":"荏原中央公園改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"日陰ができるようにしていただくのが一番いいという声もあったのですけれども、よしずですとかミスト、荏原南公園にもミストがあると思うのですが、そういったものですとか、あとは水遊びが少しできるといいなと思いまして、夏でも遊べる公園にしていただきたいと思いますが、いかがでしょうか。ぜひそうした複合遊具があるので、同じようなものなのかどうかというところを確認させていただきたいと思います。","respondent":"高梨公園課長","answer":"新しく改修する公園につきましては、遊具のメーカー等からもヒアリングをするなどし、暑さに対応できるような材質があれば、そういったものを積極的に活用するなど、暑さへの対策については、検討と対策を進めてまいりたいというふうに考えているとともに。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ声を聞いて考えていただいているということですので、ぜひ住民の皆さん、利用者の声を反映していっていただきたいと思いますが、１点、トイレのところでは子どもたちからの汚いとか臭い、暗いということ、あと洋式化をということだったのですけども、今回のトイレの改修ではどのようになるのか伺いたいと思います。","respondent":"高梨公園課長","answer":"最後に、保育園の園庭で利用している園数ということなのですが、園数のデータ、すみません、今手元にございませんが、周辺の保育園、また、幼稚園等には、工事について情報提供をするとともに、ほかの公園のご案内等々、しっかりと対応してまいりたいというふうに考えてあります。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"この件に関してだけではなくて、トイレに関しての考え方をお聞きしたいのですけれども、女子専用のトイレがなかったということで、今回造るということなのですが、品川区の今後、公園を改修するときに、トイレはどういう形式を考えられているのでしょうか。","respondent":"高梨公園課長","answer":"大きな公園でありますと、今回の荏原中央公園もそのような形で整備いたしますが、男性専用、女性専用、それにバリアフリートイレが共用トイレという形で整備するのが、現在の公園のトイレの在り方としましては一番スタンダードの形なのではないかなというふうに考えてありますが。","id":"exchange-032"},{"speaker":"西本委員","kind":"意見","question":"トイレは非常に、防災の関係も含めると大切なのです。そのときに、議題に入るかどうか分からないのですけど、その中で聞いてみるとか、どういう方向性がいいのだろうとかというのを一つの意見として、これからいろいろ法整備もされる中で変わってくるかと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、先ほどの子供の森公園のところの記載にもあったのですけれども、やはり公園のひとつ配慮すべき点は、死角をいかになくすかということがあると思うのですが、ちょうどここは入り口から入って、トイレの左奥が、ちょっとここは死角になってしまう場所でもありますので、その公園内の安全性ということもご配慮いただく視点で、ぜひここは。","respondent":"高梨公園課長","answer":"しっかりと防犯カメラ監視中というようなことを掲示して啓発するような対応等、ソフト対策も含めてやってまいりたいというふうに考えてあります。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/216259?Template=document&Id=4386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":35788,"voices":108}},{"id":"r05-20230821-9","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"文教委員会","time":"午後 １時００分～午後 ３時１０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年度品川区立学校使用教科用図書の採択","agenda":"令和６年度品川区立学校使用教科用図書の採択","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"教科書を採択した教育委員会がいつの開催だったのか伺いたいと思います。教科書展示が併せて行われると思うのですけれども、その期間はいつからいつだったのかも伺います。それと、ついでと言ってはあれですけれども、道徳は東京書籍ということなのですが、市民科はオリジナルの教科ということなので品川区で作っていると思うのですけれども、こちらのいわゆる教科書会社は何かあるのでしょうか。伺います。","respondent":"丸谷教育総合支援センター長","answer":"展示会の期間ですけれども、２会場ございまして、教育総合支援センター内にあります教科書センターで６月２４日から７月２２日まで、日曜、祝日の休館日を除きます。品川図書館では６月２７日から７月２０日までとなっています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"仮採択が７月１８日まで４回でやって、本採択が７月２５日ということなのですけれども、教科書展示の期間は今伺ったのですが、６月２４日から始まって７月２２日までということなのですけれども、展示をして意見を募っている間に仮採択は先行してやっているということなのですけれども、これはどう考えればいいのかというか、仮採択であっても、かなり本採択に近いような状況だと思うので、普通に考えれば。","respondent":"丸谷教育総合支援センター長","answer":"教育委員会の仮採択と並行して展示会が行われているというところですけれども、実際に採択に当たって、教科用図書の調査検討委員会という委員会を立ち上げております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"展示会で、やはり広く区民から意見を聞くということが、手続をしているわけですから、やはり仮採択に入る前に、仮採択を行うときにそれがまだ続いていて意見を募集中というときに仮採択という手続は、私は合理性がないのかなと思うので、これは順番を今後工夫していただきたいのですけれども、つまり、仮採択は展示会が終わって意見が集められた後にやっていただきたいと思うのですけれども。","respondent":"丸谷教育総合支援センター長","answer":"これらの意見がどのように教育委員会で報告されるかというところですけれども、現在、集計をしているところですので、整った段階で教育委員会にも報告してまいります。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"どういう期間なのか、事情は分かりましたけれども、どういうふうに進めていくことが望ましいのか、あるいは、現場の教師の意見をどのように反映させていくのかということについては、私もよく研究して、また提案したいと思います。これが１つ目です。これが２点目です。よろしくお願いします。","respondent":"丸谷教育総合支援センター長","answer":"展示会の周知方法についてですけれども、広報しながわやホームページ上には期間を掲載しております。会場の掲示、案内方法につきましては、表示が見づらいというようなご意見かと思いますので、来場された方が迷わないような掲示方法については、改めて考えていきたいと思います。","id":"exchange-004"},{"speaker":"吉田副委員長","kind":"質問","question":"これまで使われていた教科書について、きちんと把握していないので申し訳ないのですが伺いたいと思います。これまで採用されていた会社と変わったのか変わっていないのか、そのことについて伺いたいと思うのですけれども、どうやって伺うのがいいでしょうか。変わったところを伺ったほうがいいですか。それを教えてください。","respondent":"丸谷教育総合支援センター長","answer":"資料に１３種類の教科書がありますけれども、そのうち８種類が会社が変更になっております。順番に申し上げます。社会が教育出版から東京書籍に変わります。","id":"exchange-005"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"教育委員会の議事録は、今は逐語で全部拝見できますよね。そこで、例えばそういうふうに変わった理由とか、そういうことについては議論がされるのですか。要は、議事録を見れば、そういうことが把握できるのか。もしできないのであれば、ぜひ変わった理由とか、今、全部おっしゃるのは難しいから、どこかに資料があればいただきたいのですけれども、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"採択の理由につきましては、今、議事録を基に集約しているところで、今後、ホームページに掲載予定ですので、それまでお待ちいただければと思います。","id":"exchange-006"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"先ほど、安藤委員からもありましたけれども、教科書展示の期間は、どうしてこういう期間で決まっているのかなということがあるのと、それから、たしか以前、小学校ではなくて中学校のほうでしたか、第３庁舎で教科書展示の場所があったような記憶があるのですけれども、地域の方たちにとってはどうなのか分かりませんけれども、議員として、教科書の内容に関心を持っている場合は。","respondent":"丸谷教育総合支援センター長","answer":"法定展示は６月から始めるということになっておりますので、この期間になっているです。展示会の場所ですけれども、今、教育総合支援センター内の教科書センターと、今回は品川図書館で、２会場で行いました。","id":"exchange-007"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"今回は採択のための法定ということで決まっているということなのですけれども、日頃から、もう少し多くの市民の方たちに子どもたちの教材について関心を持っていただくということも必要ではないかと思いますので、これは要望です。これは、もし何かコメントがあったら、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"展示会の場所につきましては、見本本の数ですとか、展示場所の確保、また、会場の人員、そういったものが確保できれば、また検討していきたいというふうに考えております。","id":"exchange-008"}]},{"id":"topic-02","title":"ヤングケアラー支援事業のこれまでの取り組み状況","agenda":"ヤングケアラー支援事業のこれまでの取り組み状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"コーディネーターですけれども、仕事の内容と、あと、１日、子ども家庭支援センターにどれぐらい配置をされているのかということが知りたいのと、あと、相談件数なのですけれども、４月１日からの相談件数、ＰＲの相談件数と、ＬＩＮＥは７月３日からということですが、現在どうなっているのでしょうかということが２つ目。","respondent":"染谷子ども家庭支援センター長","answer":"コーディネーターの仕事の内容ですけれども、先ほどご説明をさせていただきました本人やご家族からの相談を受けるというのがまず１つ。それから、研修等を行って啓発をしていくという場合の講師をやっていただくということも委託の内容に含まれております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"確認","question":"１点だけ分からなかった点が、配置の時間と相談の関係なのですが、今おっしゃっていただいた配置状況ですと、相談したいときにコーディネーターがいないというふうにはならないのかと少し思ってしまったので、そこら辺の、いつ、ある程度、月曜日から金曜日、１１時から２０時の間はコーディネーターの方が相談を受けられるという体制になっているのかということだけ確認させてください。","respondent":"染谷子ども家庭支援センター長","answer":"実際に子ども家庭支援センターに勤務して相談に応じるのが、毎週水曜日と金曜日の８時半から１７時１５分というような形での体制で、今、実施をしています。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"(3)の実態調査についてなのですが、私、聞き漏らしていたら申し訳ないのですけれども、記名式でやられるのかどうかだけ１点教えていただきたいのと、周知方法についてですが、今、ほかの委員からもありましたとおり、コンビニとかドラックストア、スーパーマーケットなどで周知をしていくというのは、これは非常に重要なのです。それこそ区役所職員よりも。２点、教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"周知方法ですけれども、委員おっしゃるとおり、様々、大人がふだんヤングケアラーと接する機会があるようなところを中心に周知をしていくことが重要であるというふうには認識しておりまして、よく元ヤングケアラーの方のお話の中で。","id":"exchange-011"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ただただお手伝いでお買物をしているのではなくて、その裏側には何かあるのかもということを少しでも意識を持っていてもらえると、また変化にも気づいてもらいやすくなるので、私はぜひこれを、せっかくこうやってすばらしい事業を品川区でやっていただけるのであれば、もう一歩踏み込んだ支援策をぜひ検討していただいて、早期に、この周知方法を含めて取り組んでいただきたいと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ヤングケアラーの支援事業がこうやって進んでいくことは大変すばらしいことと思うので、ぜひさらに進めていっていただきたいのですが、実態調査のほうをお尋ねするのですけれども、予算で１,０３０万円ぐらいということなのですけれども、これは委託をしていくのか、それとも職員の方々が様々な作業をするのか、分析も踏まえて、そこをお願いします。それから２つ目は、対象の方に郵送する形です。","respondent":"染谷子ども家庭支援センター長","answer":"ここの部分につきましては、私立ですとか公立ですとか、そういったことは特に限定せずに、対象の生年月日の方について対象者を抽出させていただきまして、その上で、区立の学校に通われるお子さんにつきましては、教育委員会事務局のほうで学籍の情報がありますので。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうあります。委託をするということですので、各課と協力しながらというか、連携を取りながらということをお聞きしたので、それはすばらしいと思うので、特に内容をよく連携して進めてください。最後、全員に配って、区立学校に行っている子は、みんな、それを出してやりましょうねというふうに学校で説明するということで、そういう理解でよろしいですか。最後にそれを。","respondent":"染谷子ども家庭支援センター長","answer":"最後のアンケートの対象者への郵送等の方法の部分ですけれども、私立に通われているお子さんは直接郵送というところ、その同じタイミングに、学校のほうにアンケートに関する２次元コード等の入ったお知らせを直接お子さんに手渡しをしていただきたいというところで。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"すみません、最後のところ、先ほど、生年月日で対象をまず抽出し、教育委員会のほうで学籍が分かるので、その分は郵送しないという認識でよろしいですか。すみません、最後にそれだけ。","respondent":"染谷子ども家庭支援センター長","answer":"委員おっしゃるとおりで、区立のお子さんについては郵送はしない予定です。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"確認","question":"実態調査の実施のことなのですけれども、先ほど、センター長からもご説明があった内容について、設問は３０問を想定しております。これは確認です。小学生には分かりやすくというご発言がありましたけれども、中学生、高校生、年齢に分けて実施するということなのだけれども、これ、設問は、小学生には分かりやすい設問というのは、これ、３０問をやはり想定しているわけですか。","respondent":"染谷子ども家庭支援センター長","answer":"小学生中学年、４年生については、３０問の設問については少しボリュームがあるかなというふうに考えておりますので、全体を通じて最大で３０問程度を想定しておりますけれども、そういった年齢の若いお子さんにつきましては、もう少し少ない設問で、現在。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"はい、分かりました。それで、特に私が思っているのは、４年生以上の小学生なのですけれども、日常的にしていることの中で、一番精神的に、ケアを日常的にしているというのは、すごい、ご本人にとっても、本当に精神的なダメージが、当然お分かりになっていると思いますけれども、そこも設問の中にかみ砕いた質問を、何か記入できるようにしていただけたらありがたいなと思っています。これは私の要望です。","respondent":"染谷子ども家庭支援センター長","answer":"町会、自治会の皆様への周知という部分につきましては、まず、青少年対策地区委員会の中で、その地区委員の方たちに対するご説明と、それからあと、民生委員協議会のほう、地区の民協にも一度お邪魔をさせていただいて、全てではないですけれども。","id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"先ほど、安藤委員からもお話があった件で、ＳＮＳの相談窓口で、約１か月の間で７件の、今継続して相談をされているということなのですけれども、現在、何名体制で体制を整えて運営をされているかということと、これから周知と啓発がどんどん進んでいけば、さらに継続して相談をされる方プラス新規でまた継続して相談をされていかれる方が数多くなってくると思われるのですけれども、今後の見立てとして。","respondent":"染谷子ども家庭支援センター長","answer":"今後、新規で増えていくというところについては、もちろんそういった相談が増えていくことが望ましいことかと思いますので、周知を積極的に図っていくことに合わせて、協会のほうとも体制についてご相談をしながら、メッセージを送ったにもかかわらず。","id":"exchange-018"},{"speaker":"ゆきた委員","kind":"意見","question":"品川区としても、特に先駆的な取組だと実感しております。非常にすばらしい取組だと感じております。さらに引き続き、人員の確保と、ヤングケアラーの浸透、啓発、さらなる支援をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"実態調査については、生活者ネットワークもずっと求めてまいりましたので、ようやくこういう形で取り組まれるということについては、本当によかったと考えています。そういう方たちこそ自分たちで発信ができないわけではないですか。そういう実態調査については、何か別の方法で取り組まれるのか伺いたいのですが、いかがでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"ただ、そういったお子さん、ご本人になかなか自覚がなくても、例えば、学校の生活の中で、少し様子がほかのお子さんと違っているところですとか、そういったところがあって、まず一番大事なのは、ご本人からの発信ももちろんですけれども。","id":"exchange-020"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"その点について、既に何か方針をお持ちなのかということが１点と、それから、今回は文教委員会での議論ですので、ここまでだと思うのですが、将来的には、やはりその方たち、今は相談とか実態調査ですけれども、具体的な支援策というのは、ほかの所管と連携しながら考えて、ここの所管も合わせて考えていくべきだと思うのですが、そういうことについても、今はもうこれで。","respondent":"染谷子ども家庭支援センター長","answer":"実態調査を今後継続して実施していくかというところにつきましては、まずは今回、正に具体的な支援策を、庁内連携して支援策を検討していくに当たっての資料として実態調査をさせていただきたいと考えておりますので、その部分につきましては、当然ながら。","id":"exchange-021"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"たしか去年の文教委員会で埼玉県のヤングケアラーの現状を視察に行かれたと思うのですが、私たちも、一般社団法人ヤングケアラー協会で、埼玉の事例を伺いながら勉強させていただいたのですが、あそこも物すごい、何部か、幾つかの部を横断的に構築しないと支援策ができなかったというふうに伺っていますので、ぜひ品川区もそういうふうに各所管が連携するような働きかけを。","respondent":"染谷子ども家庭支援センター長","answer":"実態調査、先ほど、ほかの委員からもお話がありましたけれども、調査することが目的ではございませんで、そこから例えば今年度もう既に予算化しておりますけれども、家事援助等の訪問支援ですとか、それからあと、今後想定される事業の中で、例えば、配食サービス。","id":"exchange-022"}]},{"id":"topic-03","title":"品川区立ぷりすくーる西五反田指定管理者候補者の選定","agenda":"品川区立ぷりすくーる西五反田指定管理者候補者の選定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回、特定の事業者を選定ということなのですが、この施設の設置目的や事業内容などに特別な理由がある場合だということなのですが、今回の特別な理由というのは何なのか伺いたいということが１つ。それと、現在、福栄会だったと思うのですけれども、これは、選定、こちらを変更するということなのか、それとも継続するという考えなのか、その辺をお伺いさせてください。","respondent":"立木保育課長","answer":"現在の事業者、指定管理者であります社会福祉法人福栄会を、指定管理者候補者として継続して選定をする予定です。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"どう考えたらいいのかなというのは、少し私も悩ましいところなのですけれども、継続性は必要だとは思うのですけれども、今の課長の特別な理由というところだけで言うと、今の業者でないと駄目だというふうにはならないのではないかと思うので、公募ということもあり得ると思うのですけれども、なぜ今回、公募にしないのか、もう一度、もう少し説明していただかないとなと思うのですけれども。","respondent":"立木保育課長","answer":"よって、引き続き、現指定管理者に続けてやっていただくのがよいだろうという判断の下、今回、公募をせずに現指定管理者を候補者として選定するという考えに至ったです。","id":"exchange-024"},{"speaker":"吉田副委員長","kind":"意見","question":"そうすると、指定管理者の指定を選定をするときに、連続性だけだったら、これ、永遠に、永遠にという言い方がいいかどうか分かりませんけれども、一旦この指定管理を取ったら、連続性だけが特別な理由ということであれば、ずっと続くことになってしまうと思うのですけれども、であれば、では、どのようなことがあれば変わるのかとか、それから、前の運営事業者から福栄会に変わったときに。","respondent":"立木保育課長","answer":"これは当初、区とともに立ち上げをいたしましたＮＰＯ法人の理念が、今現在も、現指定管理者の福栄会に引き継がれているというところでは、やはりこれも連続性を大事にするという意味合いでは特別な理由に当たると考えているところです。","id":"exchange-025"},{"speaker":"吉田副委員長","kind":"質問","question":"であれば、具体的に、例えばこの指定管理の間に、こういう２つの保育と教育というようなところを合わせたような何か具体的な運営のノウハウとか、これこそが福栄会が取り組んだ結果、獲得したような運営方法であるとか、そういうようなことを品川区としても何か把握をされているのか、そこに特別な理由があれば、連続性も含めて妥当なのかなと思うのですが、その辺に何か事業者として。","respondent":"立木保育課長","answer":"現指定管理者の社会福祉法人福栄会につきましては、令和３年から指定管理をしています。令和３年より前は、この施設の立ち上げ当初から指定管理をしておりましたＮＰＯ法人子育て品川が指定管理を継続してやっていたところです。","id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"なので、そのときもたしか文教委員会では大きな議論になったかというふうに私は記憶をしておりますが、例えば、そういうふうに連続性を重視するとしたら、この間、福栄会として、こういうようなノウハウというか、運営の仕方を確立してきて、そこをほかではできない特別な理由というふうに認めるということ、何か特別なそういうところがあれば、なるほどというふうに思うので。","respondent":"立木保育課長","answer":"そうした中で、ぷりすくーる西五反田がこれまでやってきました質の高い特色ある乳幼児教育を福栄会もノウハウとして手に入れているというところ、さらに加えましては、福栄会は障害者福祉の面でも社会福祉法人としての実績がありますので。","id":"exchange-027"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"最後に、これ以上伺っても同じようなやり取りになってしまうと思いますし、今回はご報告ということですので、事業者については継続を重視するということで、福栄会ということで了解をいたしますが、ぜひ今後は、今おっしゃられたような、具体的にこれこそが品川区が目指す認定こども園としてのノウハウであるというものを、ぜひ福栄会にも確立していただきたいということを要望いたしまして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"区内保育園等あり方検討に関する経過","agenda":"区内保育園等あり方検討に関する経過","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"取り組んでいないものをこれから付加するということなのか伺いたいと思います。そういったことを踏まえて、最初の１番のところの文章の中に、「区立保育園としての役割を明確化」とあるのですが、これ、全体を見て、何なのかというか、明確になっていないような気がするのですが、一言で言うと、この区立保育園の役割を明確に、どのような役割だというふうにご説明されるのでしょうか、伺いたいと思います。","respondent":"立木保育課長","answer":"今、検討を進めているこちらの案の拠点園に関しましては、子ども・子育て支援事業計画の６区域の中に統括する拠点園をそれぞれ置いて、そのエリアの中で中心的な役割を担わせるというような、そういうようなイメージです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"なぜなのか、それはいろいろ労働環境とかあると思うのですけれども、今、相当な業務を無理してやっているというふうに、こういうものが根底にあると思うので、私は、これは理念は分かりますけれども、これをやるのであれば、しっかりと体制強化、人的配置が必要だというふうに思いますけれども、そこら辺はやっていただけるのでしょうかということを１つ質問したいと思います。そこら辺を伺いたいと思います。","respondent":"立木保育課長","answer":"一足飛びに人員増強という形は、公立は難しいところがあるので、業務の効率化とか、定員の見直しとか、あとは施設の再配置等を考えた中で人員を生み出しつつ、こういった新しい役割を持たせていく、そういうような考え方で、今、検討を進めているところです。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"したがって、重ねて言いたいのは、公立の区立認可保育園を減らす状況にはないと。減らすのではなくて、むしろ園庭など保育環境のさらなる充実、配置基準の充実、正規保育士の配置を増やすとか、私は充実こそすべきだというふうに思います。私の意見ですけれども、いかがでしょうか。最後に伺いたいと思います。","respondent":"立木保育課長","answer":"こちらの検討を進めていく中では、先ほど申し上げたとおり、区内どこのエリアでも同じ子育て支援が受けられるということを目指してこういったことを考えていくところがあります。","id":"exchange-031"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"すみません、この図が、私、うまく読み取れないのですけれども、ごめんなさい、繰り返しの説明を求めるようでしたら誠に申し訳ないのですが、拠点園の機能として赤い楕円で「保育の質の向上の特化」というものがあるのですけれども、これ、保育の質の向上というのは、全ての保育園に求められるところかと思うのですが、そこの機能を拠点園が担うという意味なのでしょうか。いかがでしょうか。","respondent":"立木保育課長","answer":"少し分かりにくくて申し訳ないのですけれども、これをより明確に機能として、事業として持たせるという、そういうようなイメージで、この２つの赤丸をつけているところです。","id":"exchange-032"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"すみません、今のご答弁の中にも出てきましたと思うのですけれども、保育の質の向上というのは、例えばどこの保育園にも求められることなので、そこの、特に拠点園が、ほかのサブ拠点園も含めて、保育の質の向上を具体的に担うということなのでしょうか。それが在宅子育て世帯の定期的な預かりということになるのですか。もう一度お話を伺いたいのですが。","respondent":"立木保育課長","answer":"全ての園で同じ在宅子育て支援、例えば預かりができるようになったりとか、あと、この地域連携の中心的役割をそれぞれの園が担えばいいというようなことは、もちろん間違いありません。","id":"exchange-033"},{"speaker":"吉田副委員長","kind":"質問","question":"品川区も、こういうことを１つの足がかりとして、ぜひそういう方向に進めていただければありがたいと思いますし、それから、今、あり方検討に関する経過ということですので、今後の報告とか、今後の見直しも含めて、もう出てくるかと思うのですが、それはまた改めてご報告をいただけるというふうに理解してよろしいのでしょうか。その点についても伺いたいと思います。","respondent":"立木保育課長","answer":"品川区、どこの地区にお住まいでも、どういうような形で子育てされていても、やはり等しく質の高い子育て支援を受けられるということが、理想の目標として、この検討の中で置いているところです。","id":"exchange-034"}]},{"id":"topic-05","title":"育児休業にかかる児童の預かり時間拡大","agenda":"育児休業にかかる児童の預かり時間拡大","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"子育て支援という点では、利便性も向上しますし、いい制度変更なのかなと思うのですけれども、この変更の動きの背景について、もう少しご説明いただきたいと思いまして、これまでのルールの理由も含めて、変更の動きの背景についてご説明ください。","respondent":"立木保育課長","answer":"ただ、昨今、様々ライフスタイルが変化していく中、また、育児を取り巻く環境、例えば３世代で近くに暮らしているというような状況が大分少なくなってきている中では、これを突き詰めてしまいますと、孤育てという形になってしまって。","id":"exchange-035"},{"speaker":"安藤委員","kind":"意見","question":"今の子育て環境といいますか、そういったものにしっかりと実態に対応していただいて、制度も適切に見直していただくということが必要だと思いますので、引き続き必要な変更などはお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問","question":"１点だけ。なぜ今この時期に急に制度変更するようになったのか。聞き逃していたら、ごめんなさい。教えてください。","respondent":"立木保育課長","answer":"年度の切替えの時が一番、分かりやすい時期なのかなと思うのですが、例えば、来年の４月からというふうにしてしまいますと、今、子育てに少し難しさを感じているご家庭とか、そういったご家庭に影響が出てしまう可能性があるので。","id":"exchange-037"},{"speaker":"ゆきた委員","kind":"質問","question":"質問なのですけれども、令和４年４月の入園の保育園のご案内、保育課で出されていると思うのですけれども、この令和４年４月の入園の保育園のご案内には、「保護者の方が第２子以降の出産にあたる場合、出産月を挟んだ前後２ヶ月間（計５ヶ月間）については出産要件として、在園しているお子様をお預かりします」とあって、「産休・育休中の保育時間は。","respondent":"立木保育課長","answer":"産休に関しましては、短時間、それから標準時間、どちらもご家庭の状況に合わせて認定申請を出していただくことが可能です。必要であれば、例えば配偶者の方の勤務時間に合わせて、例えば１０時間とか、そういったお預かりも可能です。","id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問","question":"ということは、令和４年から令和５年になった際に改正されて、今までは午前９時から午後４時までの間の預かりだったものが、令和５年からは、上の子を預けていた場合、育児休業に入って妊娠した場合は、時間は最長１１時間まで預けることができるという認識でよろしいでしょうか。","respondent":"立木保育課長","answer":"産休の場合は、例えば臨月や出産直後というのは、なかなか保育園のお迎え等も難しいというところがあるので、そこは案内のほうも外した形で、今現在やっているところです。","id":"exchange-039"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"今回、育児休業にかかる児童の預かり時間の拡大ということで、令和５年１０月から改正されるということになると思われるので、この産前産後の育児休業についても、ご案内の中では少し分かりにくいところもあるので、これと同時に改正、適用されると同時に、産前産後の育児休業についてもこうであるということを、より周知していただければと思いますので、こちらは要望でよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"確認なのですが、各家庭へ、このチラシが郵送されて周知されるということでよろしいですかということと、それと、これは申請がないと支給されないという仕組みなのでしょうか。そこを伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"基本的に東京都から対象者へ、各家庭に通知が行くということです。そこの通知の中身が、振込先等も記入をしてもらうということなので、申請をしないといただけないというふうにこちらでは判断しております。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"制度そのものは、かなり報道されたのであれですけれども、やる方も多いかと思うのですが、制度そのものについての存在と、あと、申請をしないと支給されないということなので、申請漏れがやはりないように、品川区としても何か制度周知の工夫をしたほうがいいのではないかと思うのですけれども、そちらについては何か考えていらっしゃることはありますでしょうか。","respondent":"飛田子育て応援課長","answer":"区のほうだと、もちろん戸籍住民課もそうですし、各地域センターのほうにも、こちらのお知らせを配布する予定です。我々の窓口だと、引っ越ししてきた方については、児童手当の申請等もありますので、そちらの方々にも通知をお知らせしていきたいと考えております。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/246913?Template=document&Id=5106#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":39636,"voices":128}},{"id":"r05-20230821-5","meetingId":"r05-cm08","date":"2023年8月21日","dateIso":"2023-08-21","committee":"総務委員会","time":"午後 １時００分～午後 １時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年度都区財政調整交付金当初算定結果","agenda":"令和５年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"石田（秀）委員","kind":"確認","question":"これだけ増えてきたのであれば、財調算定というのは毎年ご苦労いただいて、担当課長会でも非常に項目出しをするのであれば、せっかくこれだけ税収が増えているのだから、これは財調算定してくださいという新たな項目というのが、児童相談所以外にそういうものがこれだけ増えましたということがないと、これほど２兆１,０００億円にもなっていて。","respondent":"遠藤財政課長","answer":"そういう部分で、流れといたしましては、第３ブロックの中で協議をしまして、それを特別区のほうに持ち上げていって、最終的にはその中でこれは東京都に要求していこうと、あるいはこれはあまり実際に需要としてやっているところが少ないというところも協議などをして。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"それぐらいの意気込みがないと駄目だと思うのと、それからもう一つ、先ほど言ったように、では各区でいろいろ横でこれはというのが、例えば高校生の医療費、これは都がやると言ったらそれでいいけれども、例えば給食費などという話があるとしたら、これを財調で見るのはやめてくれという話になると私はもう思っているけれども、そのようなところを算定されても。","respondent":"桑村副区長","answer":"今、ブランチ等で東京都としても児童相談所を２３区の中でやっていこうという考え方が一方にあるわけですね。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"先ほど言った５５.１％を５５.０％にしてもう一度という前に、お金があるからといって、さっき言った給食費ではないけれども、本当にそういうものとは別に算定は算定でしっかりいろいろしてくれというものはどんどんやっていただきたいし、ちょっとこういう給食費みたいにぽっと何かあったら、ではこれは本来私は国だと思っているけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"それはやはり地元、この２３区、品川区に、それはやはりどんどん多くなった分は配分していただくというのが筋だと私も思います。質問ではなくて、今後も頑張ってほしいということと、あと、委員長にもお願いしたいのですが、議長と一緒に何か品川区議会でもいい方法、支援できる方法を考えて要望していくような時期に来たのではないかと思います。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]},{"id":"topic-02","title":"区民アンケート","agenda":"区民アンケート","exchanges":[{"speaker":"澤田委員","kind":"意見","question":"子供たちにアンケートを実施する際に、私立学校等とありますけれども、そこに特別支援学校などは含まれているのかということと、あと区ホームページで私立学校等に通う子供たちは実施するということですけれども、どのような形というか、アンケートが載っていて、それに自分たちで書いたものを送るとかそういうことなのかどうなのか、方法がちょっと分からないと思いまして、お教えいただければと思います。","respondent":"辻広報広聴課長","answer":"ホームページ上にそのアンケート機能というのがありますので、そちらで今の区民アンケートもインターネットで回答できるのですけれども、該当のアンケートを押していただいてやるという形で実施する予定です。","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"そうしたら、重複してしまうとか、何度も送ってしまうとかというトラブルは大丈夫でしょうか。","respondent":"辻広報広聴課長","answer":"そのページの最初のところに１人１回ですとか、小・中学生向けのアンケートですということで入れていく、あとは性善説に従ってということでやるしかないかなと考えています。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"恐らく様々努力はされていると思うのですが、町会なども掲示板が多々あると思いますけれども、私は回覧板を含めたり、あとそれぞれ商店街、様々なそういう諸団体に対して、やはり区のほうから回答してくださるようにご協力をお願いしますというような要請をして、せっかくこれだけ皆さんのご意見を聞く場ができたのですから、私はもう１件でも１人でも多くの、お子さんもそうですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"アンケートですが、小学生はタブレットを使用してインターネット回答ということで、学校での周知はどのようにされるのか教えていただきたいのと、また子供向けというところでどのような工夫を、大人の方も区民アンケートということでとっていますけれども、工夫をどうされているのかというところ。","respondent":"辻広報広聴課長","answer":"４点ほどございましたと思います。周知についてですが、まず保護者向けにこういうアンケートを実施しますということで、低学年のお子さんですとなかなか一人では難しい部分もありますので、できる範囲でサポートしてくださいというような通知文を出す予定です。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは意見です。その辺も含めて、タブレットで基本的には回答を求めるというところで、データを修正すれば、もし可能であればそういったところの工夫をしてもらえるとありがたいというところです。ほかで、回収見込みですけれども、６０％ということですが、できるだけ多くの意見を取り入れてもらいたいというところでは、ぜひ回答率を高く回答できるように周知をしていただきたいと思います。","respondent":"辻広報広聴課長","answer":"周知の仕方、今この子供向けのアンケート自体は教育委員会のほうと連携してやっておりまして、そのアンケートの作成ですとか、学校を通じての保護者向けへの通知というのは、教育委員会側で今考えているところですので。","id":"exchange-009"},{"speaker":"塚本副委員長","kind":"意見","question":"２番のところで、郵便の配達状況を踏まえて期間を延長しましたということで、私のところにも、あまりはっきり覚えていないですけれども、８月の上旬には到着したような記憶があるのですけれども、何か郵便配達上で発送が遅れたとか、印刷がどこかで止まったとか、刷り直しがあったとか、何かそういうトラブルがあって、皆さんに配送が遅れたということがあったのか。","respondent":"辻広報広聴課長","answer":"この郵便の配達事情というところですけれども、一度に３６万通近くのものを郵送でまいたときに、一度に問い合わせの電話がかかってきてしまいますと私どものほうでも対応できかねるというところがございまして、配送自体を少し間を空けて配送しています。","id":"exchange-010"}]},{"id":"topic-03","title":"Ｏ歩道橋補修工事請負契約","agenda":"Ｏ歩道橋補修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"Ｏ歩道橋補修工事ですけれども、ここは都道上にある歩道橋なのでしょうか。それなら品川区で予算をかけてやるものではなくて、全額都のほうで負担していただける場所なのでしょうか。それと、目視ですけれども、それほど劣化はしていないように見えますし、確かに塗料のほうは劣化されていますけれども、それほど大型の工事なのかなという感じもちょっと受けたのですが、その２点についてお聞かせください。","respondent":"佐藤（聡）経理課長","answer":"工事内容につきましては所管のほうで実施しているところでありますので、聞いている限りでお答えします。","id":"exchange-011"}]},{"id":"topic-04","title":"荏原中央公園改修工事請負契約","agenda":"荏原中央公園改修工事請負契約","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"もしかしたら所管違いかもしれないですけれども、トイレの改修工事の中のこととかは、ここではなくて建設委員会ですか。では、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/166654?Template=document&Id=2274#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":17476,"voices":41}},{"id":"r05-20230822-14","meetingId":"r05-cm08","date":"2023年8月22日","dateIso":"2023-08-22","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 ２時３３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"そのアクセシビリティの考え方を手引きとしてまとめるということは、このような新庁舎の整備ということを他の自治体も行っているのですけれども、今は大体どこもこのようなことをやられているのかどうかというところが１つです。それと、区内障害者団体７団体に８月の初めにお声をかけたというところです。こちらについては、皆様、了承を得たということでいいのかどうか、教えていただければと思います。","respondent":"山下新庁舎整備課長","answer":"当然、各自治体、こういった視点は持っていらっしゃる前提で設計に臨んでいくというところはあろうかとは思いますけれども、手引きという１つの形としてまとめていくというところにつきましては、新庁舎整備基本構想・基本計画策定委員会の段におきましても、基本計画策定後。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"私から何点か質問させてください。加えてなのですが、各町会・自治会とありますけれども、これは全ての町会・自治会なのでしょうか。そして、どのようにお聞きになるのでしょうかというところ。ここで説明はあると思うのですけれども、また追加的な区民の方からの要望が出てきたときは、手引き修正のところに「修正」と書いてありますので、織り込まれるのでしょうかということでご質問させていただきました。","respondent":"山下新庁舎整備課長","answer":"最後に、区民意見の反映というところにつきましては、今申し上げました区民向けの説明の場でいただいたご意見や、電子意見フォーム等々も活用しまして、電子の形で期日までにいただいたものを手引きの修正に反映させて完成に向けて取り組んでまいりたいと考えています。","id":"exchange-002","title":"町会・自治会支援"},{"speaker":"山本委員","kind":"質問・要望","question":"子育て世代の意見のヒアリングですけれども、オアシスルームの利用者にアンケートしながらというところで理解したのですが、ぜひ、より多くの子育て世代の意見を拾っていただきたいということがありますので、それ以外のヒアリングについてもご検討いただければ幸いです。それから、区民向けの説明のところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"今の、できるだけ区民の方からの意見をというところで言うと、一般的にはパブリックコメントの手法を使うことも考えられるのですけれども、今回は使わない理由はどうなるのでしょうか。","respondent":"山下新庁舎整備課長","answer":"ただ、他方で、ほかの委員からもございましたとおり、区民向けの説明を区民がなるべく多く集まっていらっしゃる場所に出向くことで、基本計画素案の際もそれに努めたところではありますけれども、それ以上に多くのご意見をいただけるように努めてまいりたいと考えています。","id":"exchange-004"},{"speaker":"松本委員","kind":"確認","question":"ここは確認しておきたいのですけれども、説明会に参加された方の意見をその場で聞くのと、電子で聞くというパターンを想定されているのか、あるいは素案を公表して、パブリックコメントではないけれども、素案に対して意見などを電子でも応募することも検討されているのか。これはどちらになるのでしょうか。","respondent":"山下新庁舎整備課長","answer":"ご質問のうち、説明をした際にも、いわゆるチラシのようなものを作成しまして、その場でご意見は思いつかないなという方にも、例えば、ＱＲコードを付した形でスマートフォンやタブレット等から読み込んでいただく形で区の電子意見フォームに飛ぶような形をとりまして。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"でも、説明会には参加されていないという方が意見を言いたい場合にはどのようにすればいいのかというところをお願いいたします。","respondent":"山下新庁舎整備課長","answer":"説明会への来場が難しい方につきましても、ホームページ等々から、そのページより直接リンクを貼って、電子意見フォームに飛ぶ形でご意見をいただければと考えています。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは、区である程度、絞った項目、設問を作って、それぞれ当てはまる団体向けに設問していく形と、要望の聞き取りをやるのか。両方だと思うのですけれども、設問方式でやるのかどうかということを教えていただきたいと思います。","respondent":"山下新庁舎整備課長","answer":"一定、手引きの素案としてまとめていくというところからは、そのゴールに向けて、ある程度設問項目は設けた形で取り組んでいきたいと考えています。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。これは本当に要望で、それぞれの団体から取りまとめてピックアップしていくのは大変だと思うので、ある程度絞って手引書を作っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"５番目の有識者への意見聴取なのですけれども、これはどの段階で有識者の方にお聞きするのか。手引きの修正のところなのか、時期的なところと、有識者の方は、いわゆるヒアリング先に関連した分野の方々、例えば、障害者や性的マイノリティ、子育て世代や高齢者の方など、それぞれの分野ごとに有識者の方を呼ばれるのか。どういった有識者を考えておられるのかを教えてください。","respondent":"山下新庁舎整備課長","answer":"子育て世代のヒアリングにつきまして、今、小学生というご例示がございましたけれども、今回は庁舎の整備に向けたというところでは、日頃から小学生が庁舎に来ることはなかなか想定しづらいところもございまして、ヒアリング等につきましては、オアシスルーム利用者に。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"すみません。２回目ですけれども、一番最初にお伺いしたアクセシビリティの考え方で、使いやすさ、利用のしやすさということでご説明があって、ここにも「誰にでもやさしく便利で機能性にあふれた庁舎」ということが説明で書いてあるのです。だけれども、サービスの部門ですごく要望がある。その辺りの幅を教えていただければと思います。","respondent":"山下新庁舎整備課長","answer":"基本設計の段で反映できるもののほかに、実施設計で検討していくべき項目についてもご意見をいただくことはあろうかと考えています。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点だけ要望です。多分、今回が基本設計、実施設計の前で、私の記憶では、障害に限ったような話になっていますけれども、各種団体から具体的にお話を聞くというのは初めてなのかなと思っています。聞き取っていただければいいなと思っているのですけれども、この点についてはいかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"実際にお話を始めれば、やはり多岐にわたるご意見を頂戴する形になるのかなと考えています。その中でアクセシビリティの手引きに反映できる部分は反映させていただき、それ以外の部分は、また違う形でどのような対応ができるかというところは考えてまいりたいと考えています。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"庁舎跡地等活用検討委員会が設置されて、名簿も出ていました。固有名詞はこれからですか。区内関係団体代表や公募区民というのも、ほぼほぼ決まっているのではないかと思います。今のところ、検討は５回を予定しているということで、来年の６月ぐらいまでということです。今、その辺をどのように捉えていらっしゃるのか、お伺いしたいと思います。","respondent":"泉広町事業調整担当課長","answer":"今回の庁舎跡地等活用検討委員会は、第５回まで開催するわけですけれども、第２回開催以降は、直近の行財政改革特別委員会の中で、庁舎跡地等活用検討委員会の中で説明させていただきました資料や、そのときに出ました主な意見といったところは、そこのところで情報共有します。","id":"exchange-012"},{"speaker":"塚本委員","kind":"確認","question":"今、その都度、庁舎跡地等活用検討委員会開催後にご報告いただいて、質疑の機会もあるということで、ご説明いただきまして、ありがとうあります。一方で、この庁舎跡地等活用検討委員会の報告を受けて、様々、行財政改革特別委員会で賛否に関わるような意見も出るかもしれません。ここも確認させてください。","respondent":"泉広町事業調整担当課長","answer":"出たご意見にもよると思いますけれども、当然、これまでの検討経過に反映しなければならないものにつきましては、こういった行財政改革特別委員会の中でご意見が出たということは、庁舎跡地等活用検討委員会の中でもご紹介させていただきまして。","id":"exchange-013"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。ぜひ、そのように、お互いがそれぞれの立ち位置、それぞれの持ち分で違うところはありますけれども、よりよい跡地活用に集約していけるように、それぞれでしっかり取り組んでいきたいところだと考えておりますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014","title":"町会・自治会支援"},{"speaker":"山本委員","kind":"質問・要望","question":"もしそうだとすると、それについては、どのように庁舎跡地等活用検討委員会で話し合われる予定なのでしょうかというところが１つ目になります。これを公募して、応募のあった民間事業者と対話をすると書かれているのですけれども、公募する前に、事前にサウンディングのような形で民間事業者の方に聞いているのでしょうかというところと、公募して応募がない場合はどのようにお考えなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"４つのご質問をいただきましたので、それぞれ順番にお答えします。１ページ目、しながわ中央公園が入っているというところで、今後、庁舎跡地等活用検討委員会の中でどういった形で議論が進んでいくのかというところのご質問です。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"追加でご質問させてください。アドバイザリー契約の４社の中からＰｗＣアドバイザリー合同会社を選ばれた理由は、どういうところだったのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"そのほかにも、質疑応答の場面でも、担当者の方から非常に適切、かつ簡潔明瞭なご回答があったということで、担当者の信頼性も高いといったところでの評価をさせていただいたところです。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"もう一点、要望のところで言うと、官民連携手法の対話型市場調査ですけれども、今、足元の状況で言うと、一定程度の需要が見込まれるというところではあるとは思うのですが、できるだけ幅広くアイデアを募って、最終的に決めるのは１つになっていくと思うのですけれども、パイが大きければ大きいほど、よりいろいろな意見が出てきて、質が高まるのではないかと思いますので、有力な事業者などには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"確認","question":"幾つか確認をさせていただければと思うのですけれども、もう一回、確認のために聞きますが、庁舎跡地等活用検討委員会がこれからスタートするということです。今回、区議会議員が委員に入らなかったということで、先ほど、塚本委員からも行財政改革特別委員会での質疑が庁舎跡地等活用検討委員会にどのように反映されていくのかという質問がありました。","respondent":"泉広町事業調整担当課長","answer":"今回、区議会議員の皆様に、庁舎跡地等活用検討委員会の委員として入っていただかなかった理由ですけれども、まず、区民の方のご意見を幅広く把握していくといった趣旨でございまして、そういった中で、公募区民の方をたくさん中に入れまして。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"提案","question":"分かりました。幅広く区民の意見を聞きたいがために区議会議員は入れなかったということなのですけれども、１１ページのスケジュールを見ますと、５回ということで、これも以前に説明をいただいて、少し少ないのではないかということで、私も含めて何人かの委員からそのようなお声があったと思うのです。民間が出してきた、区民の意見が反映されていない提案を基に検討するという理解でいいのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"委員会の回数のお話がございました。今回、当委員会は全５回で進めてまいりますけれども、想定される導入機能や導入手法といったところを検証していくわけですが、今回の庁舎跡地等活用検討委員会の中で、そういった機能、手法を絞り込んでいくようなところではございません。","id":"exchange-019","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"提案","question":"ごめんなさい。つまり、この５回、文字面から読むと、そんなにたくさんの検討ができない、実質的な検討は、恐らく３回ぐらいなのかなと読めるのですけれども、そういう中で、民間から提案を受けたものを、このような言い方は少しよくないかもしれませんけれども、追認をしていくような庁舎跡地等活用検討委員会にはならないですかということ。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査は、今回１回限りではございませんで、今後、来年度以降も行われていくものと認識していますので、まずは、幅広く民間事業者からも、区民からも、広くご意見を聞いていくというステージに庁舎跡地等活用検討委員会はいるだろうというところで。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"提案","question":"分かりました。民間の提案があって、こんなにすばらしいものができます、だから、これでほぼ決まりです、皆様、意見どうですかということではなくて、区民の意見を反映したもの、先ほど、整合性をというお話がありましたけれども、その中で、本当に区民が望むような、民間活用ではあるけれども、当然、民間活用ですから、企業も利益を追求しなければいけない部分もあります。","respondent":"多並広町事業担当部長","answer":"先ほど、１０ページでご説明させていただいた、それを基に、今後、具体的に市場とも対話を重ねながら、計画を定める際も、いろいろ対話を重ねながら、もっとブラッシュアップしていって、絞り込んでいくような作業になってきます。","id":"exchange-021","title":"町会・自治会支援"},{"speaker":"あくつ委員","kind":"質問","question":"最後に区民アンケート。これは、今、どのような手法で、どのようなことを聞くということが決まっているというか、検討しているものがありましたら、今、全世帯向けの区民アンケートをやっていますけれども、これとはまた別に跡地活用のアンケートをやるということだと思うのですが、そこについて、どのような内容を考えていらっしゃるのか、今、分かる範囲で教えていただければと思います。","respondent":"泉広町事業調整担当課長","answer":"今のところは、３,０００名程度を無作為に抽出させていただいて、アンケートをとっていくというところで、第３回の庁舎跡地等活用検討委員会の中で、庁舎跡地等の活用の基本的な考え方が出てまいりますので、そういった基本的な考え方につきまして。","id":"exchange-022"},{"speaker":"えのした委員","kind":"質問","question":"私からも何点か。検討範囲とすると、品川区立しながわ中央公園が入っておりますので、高校生、大学生も使ってきて、そこに対する思いなどがあると思いますが、やはりこれからそこを利用するであろう小さなお子様たちの声も、親御さんと一緒であれば、そういった意見も聞くことができるのではないかなと私は考えますが、その辺についてもどのようにお考えか、お聞かせ願えますでしょうか。","respondent":"泉広町事業調整担当課長","answer":"それが、お子様連れでワークショップに参加していただくのか、また、違うやり方で小学生、中学生たちのご意見を聴取していくのかといったところは、今後検討してまいりたいと考えています。","id":"exchange-023"},{"speaker":"えのした委員","kind":"意見","question":"なかなか大人と交じって子どもたちも一緒にということが難しいのであれば、また別の機会でも構いませんので、親子参加型ということも検討いただけると、小さなお子さんの声も、親に対してなら話しやすい、説明も分かりやすい等、あると思いますので、ぜひご検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"松本委員","kind":"提案","question":"一方で、対話型市場調査をやる以上は、企業の方々は、これだけ検討範囲があるので、最終的にしながわ中央公園をどうするのかというところも想定した提案をなされると思うのです。そのときに、もちろん区民のご意見もたくさん聞かないといけないですし、一方で企業のいろいろな提案も受けていくことが、いろいろなアイデアが生まれてくる上で大事だと思っています。その辺りはいかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査の実施要領に関連するご質問かと思います。","id":"exchange-025"},{"speaker":"松本委員","kind":"意見","question":"すごく安心しました。その点は、場合によっては、公園のほうはＰａｒｋ－ＰＦＩでやりたい、現庁舎跡地のほうは別の手法でなど、いろいろなアイデアがあるかと思いますので、その辺りは予断を挟まない形で進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"検討範囲のところなのですけれども、品川区立しながわ中央公園も今回の庁舎跡地の活用として、私の記憶が少し間違っているかもしれないのですけれども、急に出てきたような感があります。今回、この庁舎跡地等活用検討委員会でも、しながわ中央公園について、活用を検討していいということなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"１ページ目の検討範囲、しながわ中央公園の部分ですけれども、今回は、先ほど申し上げた、区民ニーズを幅広く把握していくというところでは、区民ニーズを叶えるために、しながわ中央公園の使い方、機能といったところも十分に勘案して。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"例えば、しながわ中央公園と現庁舎とあるところをデッキでつないだり、中小企業センターの建物のエリアなども、活用しようと思えば、かなり活用できるのかなと考えているのですけれども、その点は、民間事業者としても、そうした大規模に品川区立しながわ中央公園のエリアをいじっていいのかということをお聞きしたいのです。","respondent":"泉広町事業調整担当課長","answer":"そういった提案もあるかもしれませんけれども、いずれにしましても、区民ニーズを叶えるために、庁舎跡地やしながわ中央公園のそれぞれの機能を補完する、または高め合うといったところも検討してまいりたいという趣旨で範囲に含めたものでございまして。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"民間事業者がしながわ中央公園のエリアを大幅に再編というか、いじってくるという可能性もあり得るということでよろしいのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査につきましては、先ほど申し上げたとおり、何か制限を設けるわけではございませんので、今、委員からご指摘いただいたようなご提案もあり得るです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。私としては、別にここを大幅に再編しても構わないとは考えているのです。なぜならば、新庁舎の建設費の区民負担の軽減という目的達成のためには、その辺りも考慮に入れていかなくてはいけないのかなと考えているのです。その辺りの区民負担の軽減という目的の理解、そうした点は共有していくべきだと思うのですけれども、いかがでしょうか。","respondent":"泉広町事業調整担当課長","answer":"対話型市場調査に関連して、民間事業者への目的の共有の仕方ですけれども、先ほど申し上げた、庁舎跡地等活用検討委員会の目的、区民ニーズを叶える、官民連携手法の導入により区民負担を軽減する、庁舎周辺の一体的なまちづくりといったところは。","id":"exchange-030","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。ワークショップと対話型市場調査の結果について、先ほども行財政改革特別委員会との関連性のお話がありましたけれども、ワークショップの実施結果、対話型市場調査の実施結果については、行財政改革特別委員会でも報告していただけるものなのでしょうか。第３回の庁舎跡地等活用検討委員会の前だと思うのですけれども、開催日時をお教えいただければと思います。","respondent":"泉広町事業調整担当課長","answer":"ただし、民間事業者の方も準備にお時間が必要ですので、１０月中には対話型市場調査を実施していきたいということで、９月公募、１０月実施というところで、大きなスケジュールとしては考えてあります。","id":"exchange-031","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問","question":"しっかりと区民の方に対しても、このような２つの委員会があって、庁舎跡地等活用検討委員会ではワークショップもやり、対話型市場調査もやるといったプロセスを分かりやすく区民向けに整理して見せていくということが非常に大事なことかなと思っているのです。その辺りを区はどのようにお考えなのでしょうか。","respondent":"泉広町事業調整担当課長","answer":"今回は、確かに区民意見を幅広く把握していくというところで、１０ページに書いてあるとおり、今後のスケジュールに点線で「活用計画の策定等」と書かせていただいているわけですけれども、委員ご指摘のとおり、分かりづらい面があろうかと思いますので。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２回目になりますけれども、少し教えてください。９ページのところで、これまでいただいた庁舎跡地等に関する意見というところで、導入機能について、かなりの要望、望まれる意見が載っているのです。３つ目が、今回、公募された区民委員の方のご意見ということで、純粋には庁舎跡地に関してのご意見というのは３つ目のみで、あとは新庁舎のほうで望まれていたということでよかったのかどうかということ。","respondent":"泉広町事業調整担当課長","answer":"こういった機能の中から、例えば、親和性の高いものを組み合わせるような形でのお示しになって、それも、１つのパターンではなくて、ひょっとすると複数のパターンもあり得るというところで。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"そうですか。なるほど。もう一回、確認ですけれども、複数を組み合わせてイメージできるようなものが到達点だということでよろしいのでしょうか。","respondent":"多並広町事業担当部長","answer":"これからワークショップであったり、また、庁舎跡地等活用検討委員会の中でも、いろいろなご意見があるかと思います。それをしっかり受け止めることが大事だと思っています。","id":"exchange-034"},{"speaker":"山本委員","kind":"質問","question":"私も２回目で失礼いたします。ほかの委員からお話がありましたところで、２点、さらに質問させてください。区民アンケートについて、無作為で３,０００名を予定されているということだったのですが、それ以外の抽出されなかった方々が意見を言う機会というのは、今回の庁舎跡地等活用検討委員会のプロセスの中でご用意されているのでしょうかということが１点。","respondent":"泉広町事業調整担当課長","answer":"これは、いただいたご意見を反映した形で、この庁舎跡地等活用検討委員会も進めていきたいと考えていますので、戻るというお話がございましたけれども、一定、取りまとめの段階では、しっかりこういったご意見が出て。","id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"区民アンケートですが、包括的な庁舎等のアンケートで幅広くできる、ウェブ上で求めているということで、あえてやるのであれば、それになるということなのですけれども、このように独立して庁舎跡地等活用検討委員会ができているわけなので、分かりやすさの点で言うと、門戸が開かれているということであれば、別途、アンケートを電子上で募っていただくのもいいのではないかと思うので。","respondent":"泉広町事業調整担当課長","answer":"こういった行財政改革特別委員会の場でいただいたご意見も、しっかりと庁舎跡地等活用検討委員会の中に落とし込んでいって、それをまとめの中でしっかり反映していきたいと考えていますので、しっかりフィードバックしていくという考えです。","id":"exchange-036"},{"speaker":"こんの委員長","kind":"提案","question":"私からも山本委員にご説明いたします。行財政改革特別委員会で、今、跡地活用のご意見・ご提案等をいただいております。いわゆる新庁舎の基本設計についての中間まとめはします。そこに、跡地活用の皆様のご意見・ご提案もまとめて提出することになるかと思います。そうした形でよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/994750?Template=document&Id=6154#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":30058,"voices":101}},{"id":"r05-20230823-19","meetingId":"r05-cm08","date":"2023年8月23日","dateIso":"2023-08-23","committee":"災害・環境対策特別委員会","time":"午後 １時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、視察させていただいたところで蓄電池なども設置して、キッチンカーとかにも使っているというお話がありましたけれども、１回充電してしまうと、１回使用したときに、全部はなくならないということだったので、またすぐ充電されて、充電が終わったら、その分は太陽光発電の分を使わないというか、もう少しいい活用の方法があるのではないかと思ったのですが、区のお考えを伺いたいと思います。","respondent":"河内環境課長","answer":"地中熱につきましては、たしか御殿山小学校でしたか、エコルとごしが初めてではないのですが、地中熱は、地下に井戸のようなものを掘りまして、そこの熱反応によって、使える、使えないという場所によっての制約がありますので、そういったところの条件が合えば。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそれを進めていっていただきたい、増やしていっていただきたいと思うのですけれども、伺いたいと思います。それで、先日テレビ報道で、学校の断熱が進んでいないということが報道されていたのですけれども、品川区では学校の断熱というのはどうされているのか、それが省エネに大きく影響してくると思うのですけれども、あと、学校以外のほかの施設でもどうなっているのか、伺いたいと思います。","respondent":"河内環境課長","answer":"あるいは冬場ですが、入射角でいいますと４５度以上、５５度ぐらいになるらしいのですが、そのように傾いてくると、斜めから日が入ってくるので、暖房にも寄与してくれるというところで、自然の理にかなった設計がなされているのだろうなというところで。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、気候変動の問題もあって、猛暑もそうですし、日本でも多くの被害、台風の大型化ですとか、世界的に見れば山火事とか、様々、気候の問題で災害が起こっていると思いますので、それが取り返しのつかないところに至らないように、抜本的に大きな転換が求められていると思いますので、区が身近な自治体として率先していくということをお願いしたいのですけれども、いかがでしょうか。","respondent":"河内環境課長","answer":"ほかの断熱ですが、今ある熱を漏らさずという点で、主に暖房・冷房で魔法瓶のような構造にするものがありますが、こちらは既に民間の中でいろいろ進んでいる中ではありますが、老朽化あるいは建て替えの中で、断熱化された商品も、例えばドア。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"さらにそれを進めていかなければいけないと思うのですけれども、そこで、資料で伺いたいのですが、対策例別の想定削減量を出されておりますけれども、家庭、業務、運輸ということで、それぞれが省エネの行動ということで、２つに集約されているのですが、そこのところでさらに太陽光パネル、断熱化、ＬＥＤと家庭のところでは書いてありますけれども。","respondent":"河内環境課長","answer":"先ほど説明の中で、非常に高ボリュームを占めている３分野、家庭、業務、自動車運輸といったものが、鋭意取り組むべきものだと示したところですが、どこが駄目だったのかというところについて触れておきたいと思います。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"開発されれば、それはしっかり取り入れて、やっていっていただきたいと思うのですけれども、今ある技術をまず使って、削減をしていくということが必要だと思いますので、そうしたことも含めて、国にも意見を言っていかなければ、区の電力の脱炭素化のところでも、結局係数が上がってきてしまえば、削減量が減ってしまうということになってしまうわけですから、区としても。","respondent":"河内環境課長","answer":"いろいろなご意見があろうかと思いますので、今後も検討しながら、きちんと整理して進めていきたいと考えているところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に１点だけ、いろいろな取組がありますけれども、具体的に何をやって、どれだけ進めていき、年度ごとに何がよくて何が悪かったという教訓を引き出しながら、しっかり推進をしていっていただく、よりロードマップを具体化していくということかなと思いますので、そうしたところで進めていっていただきたいと意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"ひがし委員","kind":"質問","question":"今まであった施設とはまた違って、若い方々がどんどん来られる、そして地域との関わりというところも、若い世代が持てるような場所の拠点になるのではないかと思っているのですけれども、今日提示していただいた（３）令和５年度の取組のところで、講座・イベントと書いてあるのですが、ホームページとかを調べてみますと、いろいろな体験の講座などをされているということが載っているのですけれども。","respondent":"河内環境課長","answer":"基本姿勢ですが、一つ、家庭を中心に考えますと、例えば、子どもさんとお母様が一緒に生活の中でヒントを得ながら、具体的行動に結びつけていくというところが大切かなと考えておりまして、そういった関係でありますので、年代といいますと、言い方はあれですけれども。","id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問","question":"特に今、夏休みで、自由研究というのが私のときにもあったのですけれども、そういうのにも活用できるような内容というところも多くあるのではないかと思うところで、実際に募集しているのが、例えば１５名とか２０名とか決まっている中で、そこが埋まっているのか、それとも、まだ広報がなかなか足りていなくて、来ている人が少ないとか、その現状というところも示していただいたほうが、議員の中でも。","respondent":"河内環境課長","answer":"環境講座ですが、ほぼ定員いっぱいでやっている状況で、今後の課題といたしましては、抽せんで漏れた方がいつまでたっても参加できないということを積極的に是正しなければいけませんので、アウトリーチの講座を増やしたり、あるいは講座の人員数を講師と調整しながら増やしたり。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"意見","question":"品川区の議員になって、いろいろとお話を聞いている中で、様々なイベントを企画していて、すごくいいなと思うところが、なかなか区民の皆様に浸透していなくて、参加率が上がらないという現状を聞いていたりしたので、ここもせっかくやっているのにどうかなというところで、参加率が高いということ、また、募集して待っている方もいるという状況は。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"先日の視察で、地中熱とか、雨水利用とか、蓄電池とかの利用も調査されていて、大変すばらしい取組だなと感じております。動画に関しても、すごく興味を引く動画で、すばらしい動画であるなと感じておりました。そこで、他自治体は、エコルとごしが始まってから、どのぐらいの自治体の方が視察に来られているかというのがもし分かれば、教えていただければと思います。","respondent":"河内環境課長","answer":"そういったところの、日本全体というのはおこがましいですが、環境の学習が少しでも推進できるように、私どもの持ち得る知見は、そこで持ち帰っていただくような姿勢で対応していますが、今年度につきましては、週２とか週３ぐらいで多いときには来られていますので。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"非常に注目を集めているということで、品川区としても、様々な自治体として参考に求められているというところがあると思われるのですけれども、令和４年の４月から公募が始まって、今回４回目の公募が開始されている、環境省で開始している脱炭素先行地域という、いわゆる脱炭素のモデル地域に、品川区は応募されているのか、応募されていなければ、今後その見通しがあるのか教えていただければと思います。","respondent":"河内環境課長","answer":"もちろん、チャンスやお役に立てることがありましたらば、企画課などと調整の上、そういったことをやることも検討の視野に入れておりますので、よろしくお願いいたします。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"横浜市のみなとみらいとか川崎市、関東圏でも千葉市とか、モデル地域として、東京圏内ではまだ選定されていないというところもありますけれども、エコルとごしで、本年度６月にはゼロカーボンシティしながわ宣言もされて、注目されていますので、一区民としても、ぜひ選定の応募をしていただければという思いもありますが、一区民の声として、ご要望で上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"一企業の広告に使うことになるので、お考えはいろいろあるかもしれませんけれども、そのようにエネルギーをそこで循環させているというのも、何かアピールになるのではないか、興味を引いてくれる人がいるのではないかと思ったのですが、アピールはそもそも求めているのか、アピールを求めているとしたら、えらく目立たなかった気がすると思ったのですけれども、その辺を伺いたいと思います。","respondent":"河内環境課長","answer":"アピールポイントになるということなので、そういったところも併せて、「ｅａｔ ｆｏｒ…」といいまして、キッチンカーの中で非常に特別区の中でも有名な事業者なので、そういった既存のＳＮＳなどを踏まえまして、そういった発信をしていくべきなのかなと考えたところで。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"強制できることかどうか分かりませんけれども、中での私たちのご案内にはそういうご説明があったので、区として不都合はないのではないかと思いますので、ぜひアピールしていただきたいと思います。でも、あそこの中には今のところないなと、この間も確認したつもりだったのです。ぜひこの姿勢は続けていっていただきたいと思いますので、それは要望としておきます。","respondent":"河内環境課長","answer":"反復学習ではないのですが、環境に対する姿勢は、実は子どもの立ち居振る舞いでありますとか、子どもの発する言葉だとか、そんなところに大人たちはみんな感銘を受け、行動変容を起こしているというところもありますが、一方で。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"これで最後にします。それから、給水スポットは、ずっとこのままいっていただきたいと思います。願わくば、もう少し踏み込んだ内容に、指定管理者のお考えもあると思いますが、ぜひそのことについては、これからも要望を出していきたいと思いますので、どうぞよろしくお願いいたします。残念ながらお花はまだのようですが、来年に期待したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"こしば委員","kind":"確認","question":"エコルとごしについて、まず確認の意味でもお聞きしたいのですけれども、担う役割の中での目標が、次世代につながる「日常的に実践する人」を育てると書かれていまして、括弧の「日常的に実践する人」というのが、まさにその上の、区民および事業者の自主的な環境活動の推進。育てていくというのは人材の育成に尽きるのかなと思うのですけれども、まず、そのとおりでよろしいかどうか。","respondent":"河内環境課長","answer":"様々、環境指針ありますが、やはり実践に結びつけていきませんと、例えばですが、脱炭素の目標しかり、いろいろな目標はありますが、結びつかないというところで、実践に結びつくようなところをキーにして進めているというところは間違いございません。","id":"exchange-016"},{"speaker":"こしば委員","kind":"質問・要望","question":"先ほどひがし委員からも質問がありましたけれども、これまでの講座も含めて、振り返りを教えていただきたいのと、振り返りというのは、行政、運営側の振り返りも当然必要ですけれども、教育を受ける子どもたちの振り返りも、今後の自主的な環境活動の推進に資するものと考えますので、そういった教育を受けた子どもたちの振り返りについても、これまでのことも踏まえて。","respondent":"河内環境課長","answer":"今、子どもたちをメインとしていろいろな取組を進めておりますが、２０３０年、２０５０年、その子たちが社会に出ていって、自分よりも下の年代に教える立場になったときに、少し振り返っていただいて、あのときにエコルとごしに出会えてよかったねとか。","id":"exchange-017"},{"speaker":"こしば委員","kind":"質問・要望","question":"枝葉のことも含めて、しっかりと未来に向かって根を張っていけるように、この目標に向かって、本当にこれは大変長い時間がかかる取組だと思いますけれども、ぜひ取り組んでいただきたいと思いまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"新妻委員","kind":"確認","question":"昨年もエコルとごしに視察をさせていただきまして、１年がたちました。最初に確認でお聞きしたいのですが、今日、カーボンハーフ達成のロードマップを示していただきましたが、エコルとごしの中で、例えばカーボンハーフ、またゼロカーボンに向けての、どれくらいの目標の達成に向けて、現在どこまで来ているのかということが目に見えて分かるような表示というのが、どこかにされていましたでしょうか。","respondent":"河内環境課長","answer":"お客様の興味のあるワードだとか、あるいは知識レベルだとか、そういったものに合わせて変更しているのですが、そうした中にでもこういった考え方を取り入れながら、目標に向かってどういったことが大事かというところ、今はパーツの展開になっていると思うのですが、どこかで。","id":"exchange-019"},{"speaker":"新妻委員","kind":"質問・要望","question":"余談ですが、３・１１の東日本大震災が起きたときに、電力不足が生じて、まちの中が暗くなりました。それと、先ほど、各自治体から視察に多く来られているとお話がありました。エコルとごしが開設をして１年で、まずは品川区の子どもたち、幼稚園・小学校・中学校の子どもたちが一巡して、エコルとごしは全ての学校で見学できているのかというところをお聞かせください。","respondent":"河内環境課長","answer":"そうしたところが、ライフスタイルの変革の中で、何かしら活きてくればというところはあろうかと思いますが、それが何かというのはなかなか難しい面かもしれませんし、今、自動車部門について、ＣＯ２の削減３大要素の一つに挙がっておりますが、本来。","id":"exchange-020"},{"speaker":"新妻委員","kind":"意見","question":"長く皆様にお越しいただける施設となっていくためには、日々、指定管理の方も工夫をして、情報発信もしながら進められていると思いますが、少しずつ、時期等によっては内容の更新もしていかなければ、多くの方に訪れていただけるような施設ではなくなってしまうのかなとも思いますので、その時々のそれぞれのいろいろなテーマを持っていただきながら、内容にも工夫をしていただき、いつでも多くの方が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"澤田委員","kind":"質問・要望","question":"既に様々取り組まれているということでしたので、申し訳ありませんが、子どもたちが、こんなことがあるのだというのを自分たちで考えつつも、さらに発見できるような、分かりやすい何かをつくっていただけたらと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"多くの区民の方が見ても、簡単に身近に理解できるということでは、私は評価されるのではないかと思います。白熱電球をまだ使っているところも、蛍光灯もそうですけれども、あると思うのですが、そういうのも積極的に２０％ぐらいの補助金を出して、区民の皆さんにどんどん取り替えていただくような身近な政策を、国と区も挙げて、私は取り組むべきではないかと考えています。その辺について、どう思われるか。","respondent":"河内環境課長","answer":"ひさしの件につきましては、冬場と夏場では南中高度が違いますので、西日が冬だと相当傾いて、日が差しますので、ひさしがかかっていても、夏場は南中高度が高いので上からになりますので、日が入らないというところで、昔の人はよく考えたなと思うのですが。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"関西のほうでもあったのですけれども、一生懸命、大規模の太陽光発電化が進んで、地域で努力していたのですけれども、あまり電力量が多いと太陽光発電は遮断されるということを、ほとんどの方が知らないかと思うので、そういう問題もあるので、なかなか太陽光発電化も難しいかなと思うのですが、何とかこれから国・都・区で考えていただいて、私はよりいい方向に目指していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"せりざわ委員","kind":"質問","question":"エコルとごしのところで、１点だけ手短に。だから子どもたちも、こうやってタッチしたりして、楽しんで学べる。これはすごくいいところだなと思う一方で、総花的というか、環境のすごく手前の段階を教えてくれている一方で、品川区の施設なので、品川区の制度とか、先ほど澤田委員も少しお話されていましたけれども、そこまでタッチできるといいなという思いも少しだけあります。","respondent":"河内環境課長","answer":"第一目標のクリアが、まずは大前提になってくるのですが、さらに、ここまでエコルとごしの知名度が上がった以上、何らかの形でやりたいというところが思いとしてはありますので、少しまたお時間をいただきながら、検討を進めていきたいと考えています。","id":"exchange-025"},{"speaker":"せりざわ委員","kind":"意見","question":"指定管理者のアクティオがすごく優秀なところなので、とはいえ、多分、制度全体、品川区もそうだし、行政もしくは政治の制度というのは、なかなか追い切れないかなという思いもあるので、常設展示とかいろいろな展示は、引き続きお願いしながらも、環境課とか、いろいろな品川区の情報、もしくは東京都とか国の情報というのをまとめて、例えばですけれども、よく水族館とか、居酒屋もそうですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"西村委員","kind":"質問","question":"１点だけ、すみません。先日はありがとうございました。エコルとごしに関しましては、区内の環境教育を本当に力強く牽引してくださっていると思っていまして、学校の社会科見学が小学４年生で行くのかなと思っていたのですけれども、開設から１年ちょっとたちまして、区内の全学校が訪問されているのかどうか、伺いたいと思います。","respondent":"河内環境課長","answer":"こちらの見学ですが、まだ全校には至っていないというところで、年度ごとに社会科見学の訪問先の希望を募っておりますが、中には学校においては、違うものを学びたいというところもございまして、一巡するのを目標にしておりますが、学校、教育委員会と調整しながら進めて。","id":"exchange-027"},{"speaker":"西村委員","kind":"質問","question":"先ほど新妻委員もおっしゃっていましたけれども、幼稚園、保育園とも担当課と連携していただいて、できる限り区内の子どもたちが行けるようにしてあげたいと思うのですが、なかなか品川区も広いものですから、遠いところから道がなくて、行き方がなくて、大井地域から歩いて行くような学校もあったと伺っておりますので、バスの手配などはなかなか難しいと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"二酸化炭素発生分析における対策例別の想定削減量の中の貨物車両なのですが、これは対象数が１万１,０００台です。この数字は、運輸局の数字から引用されているのかというのと、自家用、事業用、それぞれ両方で約１万１,０００台ということでよろしいですか。","respondent":"河内環境課長","answer":"おっしゃるとおりで、運輸局です。","id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"そうすると、貨物という言葉だけ見ると、事業用だけのイメージがあって、お仕事でも自家用で使っているのを、いわゆる貨物で使って、エコドライブ１０とかというのは、大分前からそういうのをやっていたりすると思うのですが、事業用はぱっとイメージするのですが、自家用の貨物というのはどのような感じの車両のことを言うのでしょうか。","respondent":"河内環境課長","answer":"日本で１万台といいますと、約１年で登録されるバスの台数に匹敵するぐらいなのですが、そういった固い決意を持って、日本にもバス・貨物自動車の電動化を扱う企業が出てきたというところもあって、踏み切ったと書いてありましたが、そうしたことも捉えまして、今あるものは。","id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"事業者、家庭もそうなのですが、家庭については5)で、家庭への次世代自動車の普及という部分であって、貨物車両のほうは自家用・事業用それぞれ、エコドライブしてくださいと。要するに、促して、それを推計でこのぐらいだろうという算定の下でいくのか、具体的に何かつかめるものがあるのかというのを教えてください。","respondent":"河内環境課長","answer":"正確な計量の中で、事業の振り返りといったものができれば、最もいいと考えているのですが、全ての事象に当たって、そういった検討、振り返り、あるいは計量、検定ができるわけではございませんので、その辺りは、現実感を見ながら進めてまいりたいのですが、一方で。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"これについては、今年の予算特別委員会で高橋伸明議員が、こういう動きがありますということで、参画を検討していきますというやり取りがあって、７月３１日の協定なのかなと思うのですが、ただ私も、７月３１日が、品川区が参画したという形では３１日だと思うのですけれども、この枠組みというか連携自体は、２０１９年ぐらいか、もっと前からあって、進んできて。","respondent":"河内環境課長","answer":"今後はその活動の中で、間伐体験や情報発信などを踏まえまして、東京都においては、残りのお金を全部出してくれるということなのですが、現場の体制づくりも含めまして、１０年、２０年かけてしっかり取り組むというところに、まずはバス、電車に乗ってみたというところで。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問","question":"今年度続いているという、予算書とかを見る限り、出てこなかったので、あれなのですが、続いているのだろうなというのは、橋梁のカーボンオフセットがあって、今回の協定の中にも、今ご答弁あったことに合わせて、カーボンオフセットについても触れられていたりする中で、先ほどのいろいろな家庭とか業務とか運輸の取組も併せて、今回の連携の協定を活用したカーボンオフセットとかも。","respondent":"河内環境課長","answer":"何が何でもお金を出して、ＣＯ２の削減を金で解決するというやり方がありますと、日本国中、削減が全然進みませんから、そういったところを基本にしながら、次世代の子どもたちによりよい環境を残してあげられるように、なかなか厳しい道であるということは理解しておりますが。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に、確かに全国で見ると、あっちとこっちで相殺してしまって、相殺されているから変わらないといったジレンマがあるのですけれども、その上で、品川区として掲げている目標は達成していきつつ、当然全国、そして世界の目標がしっかりと達成していくという努力の、まさに一歩がこうした取組なのかなというところでは、先日視察させていただいた環境学習交流のエコルとごしでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"それで、ロードマップの表１の、主な二酸化炭素発生分析における対策例別の想定削減量のところで伺いたいのですけれども、例えば家庭の1)のところで、住宅の省エネ化で３万５,０００戸となっていますが、その５０％ということで、１万７,５００戸が、これを２０３０年までに達成しましょうという目標で掲げられているのか、そこの確認をさせていただきたいと思います。","respondent":"河内環境課長","answer":"今後の見込みなのですが、先日、都知事から、新型の太陽光電池パネルを自分のところの都有施設に設置してみるような、自分で施工する写真なども併せて報道されておりましたが、様々なやり方が出てきて、今までと在り方も違ってくるのかもしれませんし。","id":"exchange-035"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"だから、こういうのもどんどん啓発というか、ＰＲもしていただいて、つけていただきたいし、それから、断熱性の高い建物も選択できるようにというところでは、私はここに対しても、区としても補助金をつけるなどしながら、３０年、４０年と建て替えないわけですから、建て替えるときにはそういうところを選択できるということに、ぜひとも誘導していただきたいと思うのですけれども。","respondent":"河内環境課長","answer":"多くの件数が受け答えできるように、予算額の要求を常に多くしている状況ではあるのですが、現実感を伴って言うと、それぐらいかなというところがございまして、今後、新しいものが出できますと、価格の相場も低減が進むと言われておりますので、状況に応じながら。","id":"exchange-036"},{"speaker":"鈴木副委員長","kind":"質問","question":"今回のロードマップの一番下の表というのは、１０年後の想定削減量ということで出されているわけです。それも１年ごとに、このような形で、これを達成するためにこれとこれをやりますという具体化と、計画というのを立てていって、さらに目標を超えて達成していこうということが必要なのではないかという思いがしているのですけれども、その点はいかがでしょうか。","respondent":"河内環境課長","answer":"国の補助金を用いながらつくる施設も大変多うありますので、そういったところの見合いの中で、最善を尽くして検討していると聞いておりますが、ただ、全部の施設でフルスペックで入れられるかというと、なかなかそうはいかないかなと感じているところです。","id":"exchange-037"},{"speaker":"鈴木副委員長","kind":"質問・要望","question":"区が関わって、学校から福祉施設から保育園から、様々な施設に関わって、建物も建てていくというところはありますので、ぜひそこのところは、最大限連携を取りながら活かしていただいて、省エネ、それから再エネを活用して、断熱とか、そういうことも含めて、ＣＯ２削減に取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-02","title":"令和５年度地区総合防災訓練の実施","agenda":"令和５年度地区総合防災訓練の実施","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"３地区が実施をしないということですけれども、理由がどういうことなのかお知らせください。それと、やります１０地区におきまして、今回この訓練の中で、障害のある方との訓練を一緒にやるという地域がありましたら、どのようにやっていくのかお知らせいただきたいと思います。","respondent":"伊藤災害対策担当課長","answer":"しかしながら、今後、訓練はまだ１１月の最後まですので、また計画等が変わる可能性がありますが、そういったときには、関係課と連携をしまして、誤りとか事故のないように対応させていただきたいと考えています。","id":"exchange-039"},{"speaker":"新妻委員","kind":"質問・要望","question":"障害のある方との訓練は、働きかけをしないとなかなか進まないと思いますので、ぜひ各地区に声かけを、区のほうからしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"学校自体は学業がメインなので、当然そこまでは考えないのも、それはそれで教育委員会の主張としても正しいと思うのですけれども、防災という皆さんの所管としては、そこにしっかり入っていって、学業があるのは、今の安全があるから学びができるというのは大前提としてあると思うので、今後の計画の中で、どうやって入り込んでいくのかという意気込みとかがあれば、教えていただきたい。","respondent":"平原防災課長","answer":"そういったところもあって、何をやればできるのかというのをきちんと教育委員会とも協議いたしまして、人工芝だから、イコール直ちにできないということではなくて、どこまでできるのか、できないことは何なのか、そういったことを明らかにして。","id":"exchange-041"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"すごく曖昧な記憶なのですが、３年前ぐらいに人工芝化が始まったときに、火が使えないのだと。人工芝化があろうがなかろうが、火はおこさないと、かまども何も使えないですし、災害時にはもちろん、そうなるのですけれども、防災のときにも火を使った訓練というのができるようにしていかなければ、フルスペックで防災訓練ができるような体制というのを、ぜひ整えてほしいと、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/556800?Template=document&Id=6640#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":51112,"voices":97}},{"id":"r05-20230824-10","meetingId":"r05-cm08","date":"2023年8月24日","dateIso":"2023-08-24","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"令和６年度予算（議会費）","agenda":"令和６年度予算（議会費）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それが１つ。それと、いろいろ書かせていただいたのですけれど、５や１１あたりは、やはり議会機能の強化に直接関わってくるようなことだと考えていますので、検討していただいたのかなということは、こちらについては伺いたいなと思います。","respondent":"渡辺議長","answer":"各論については、それぞれというよりは総合的に、来年度予算に直結するものを中心に検討した結果ということで、個別にいい・悪いはそんなにこだわりはなく進めてまいりました。それが検討経緯です。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5514#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":6479,"voices":31}},{"id":"r05-20230920-10","meetingId":"r05-cm09","date":"2023年9月20日","dateIso":"2023-09-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"副区長なのですけれど、既におられる桑村副区長と、新井さんの担任事項はどのように分担するのか、ご説明いただければと思います。事前の説明では、新井氏のほうは、特命に関することという事項も担任事項に入っておりましたけども、特命というのはどんなことを指すのか伺いたいと思います。","respondent":"森澤区長","answer":"それ以外を桑村副区長に引き続き担っていただくこととなります。特命に関しましては、政策推進を含めまして、区長が特命ということで任ずるものと考えております。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"教育委員のほうですけれど、公募には何名の応募があったのでしょうか。それと、選考委員会のメンバーについては、６月に総務委員会と教育委員会で報告があって、その際は検討中ということで、その説明がなかったのですけれども、正式にこれからあるのかもしれないのですが、どなたがその選考委員会のメンバーで、どういう基準を重視したのかというのをもう少しご説明いただければと思います。","respondent":"森澤区長","answer":"応募は３４名で、論文審査を経て、７名の方を面接させていただきました。面接は、私と副区長、総務部長、教育次長です。それで、教育委員にふさわしい適性ということで、それぞれが面接において質問をさせていただきまして、審査をさせていただいたという次第になります。","id":"exchange-002"},{"speaker":"若林副委員長","kind":"確認","question":"ただいま区長より説明がありました２件の人事議案につきましては、後ほど議事日程の中で確認してまいりますが、２２日の本会議２日目に議決予定となりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"若林副委員長","kind":"確認","question":"ないようでしたら、本件につきましても、２２日の本会議２日目に議決予定となります。そのため、後ほど、議事日程の中で、本件に対する各会派の態度を確認します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"若林副委員長","kind":"確認","question":"説明が終わりました。９月２２日の追加議事日程第１の副区長の選任同意につきまして、各会派の態度を確認していきたいと思います。自民からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"若林副委員長","kind":"質問","question":"維新、無所属のうち、反対の方がいるですので、本件の取扱いについては、起立採決ということでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"若林副委員長","kind":"確認","question":"さよう決定いたします。資料No.６の追加議事日程第１の右端の欄の、起立採決に丸の記入をお願いいたします。続いて、追加議事日程第２の教育委員会委員の任命同意につきまして、各会派の態度を確認していきたいと思います。自民からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"若林副委員長","kind":"質問","question":"全会派および維新、無所属議員が賛成ですので、本件の取扱いについては、簡易採決ということでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"若林副委員長","kind":"確認","question":"さよう決定いたします。資料No.６の追加議事日程第２の右端の欄の、簡易採決に丸の記入をお願いいたします。次に、議事日程(2)の日程第１５、議員派遣の件につきまして、各会派の態度を確認していきたいと思います。自民からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"若林副委員長","kind":"質問","question":"全会派および維新、無所属議員が賛成ですので、本件の取扱いについては簡易採決ということでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"若林副委員長","kind":"質問","question":"正副委員長互選につきましても、先ほどの局長の説明のとおりですが、本件につきましても、ご異議ございませんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"若林副委員長","kind":"質問","question":"さよう決定いたします。なお、総括質疑および意見表明の氏名報告と意見表明の原稿の提出につきましては、予定表に記載のとおりですので、各会派での周知のほどよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"若林副委員長","kind":"質問","question":"(1)の日程についてから(3)の質問者の氏名報告についてまでの３件を一括して、局長より説明願います。","respondent":"大澤区議会事務局長","answer":"(2)一般質問の順序については、予定表に記載のとおりです。順序は大会派順に頭順送りで、第４回定例会は、未来からとなっています。(3)質問者の氏名報告ですが、１０月１０日午後５時までに事務局へお願いいたします。","id":"exchange-013"},{"speaker":"若林副委員長","kind":"質問","question":"ないようですので、第４回定例会の一般質問者の氏名につきましては、１０月１０日火曜日までに事務局へご報告願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"若林副委員長","kind":"質問","question":"ほかにいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"若林副委員長","kind":"意見","question":"ないようですので、以上でその他を終了いたします。以上で、本日の予定は全て終了いたしました。次回の開催は、１０月２３日月曜日、午前１０時３０分からを予定しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/105128?Template=document&Id=5516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":11280,"voices":67}},{"id":"r05-20230922-4","meetingId":"r05-c-settlement","date":"2023年9月22日","dateIso":"2023-09-22","committee":"決算特別委員会","time":"午後 ３時２９分～午後 ３時３７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松永副委員長","kind":"意見","question":"ただいまご推挙いただきました副委員長を務めします、しながわ未来の松永よしひろです。重要な役割を担うに当たってしっかりと議会運営、そして委員長を支えて頑張ってまいりますので、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/491466?Template=document&Id=1530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":2048,"voices":17}},{"id":"r05-20230925-6","meetingId":"r05-cm09","date":"2023年9月25日","dateIso":"2023-09-25","committee":"区民委員会","time":"午前１０時００分～午後 ０時２９分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","agenda":"令和５年陳情第３１号、行政が運営主体となる新規火葬場建設を求める陳情","exchanges":[{"speaker":"山本委員","kind":"質問","question":"質問したいところは、陳情の理由の４のところで、「例えば、大規模災害が起こったような場合でも、同様に火葬を受け入れない可能性が当然に想定される」と書かれていて、確かに大規模災害が起こったときに、火葬の必要性がある中で使えないとなると、いろいろ困る状況になるのかなと思いまして、そういったところにおいて、大規模災害発生時を想定し、行政に協力をいただけるような協定締結とか。","respondent":"舩木生活衛生課長","answer":"１点目のご指摘の部分につきましては、国からの火葬等のガイドラインが発出される前からも本事業所は、当時、どういうウイルスかが分からないような段階からも、国であるとか東京都に対して、取扱いに十分丁寧にというか、適宜確認しながら。","id":"exchange-001"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。それから、この陳情の理由の６に書かれているところです。一定数というか、４割ぐらいにご利用いただけている状況と。ここでお願いしたいのは、まず、ぜひ連携を取っていただきたいというところと、足元でも利用率が上がっているということを聞いておりますので、ぜひ早く増設の計画が進むことをお願いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"先ほど区の条例のご説明がありましたけれども、原則的にはこちらの３つを先ほど例示された上で、区長が特別に認めたもの、陳情に書いてあるとおり、公益性の関係から永続性と非営利性が確保できる、そういう民間も認めているのだよというご説明のように聞こえたのですけれども、これはあれですか、６区において当然民間を置いているわけですから、ここについてのいわゆる法解釈としては。","respondent":"舩木生活衛生課長","answer":"経営主体の適格性というところですけれども、まず大本の墓地、埋葬等に関する法律の第９条では、市町村長の葬祭又は火葬の義務という条項がございまして、まず、第一義的には「死亡地の市町村長が、これを行わなければならない」という規定があります。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。先ほど戸籍住民課長からご説明があった、令和３年度は４５.３％、令和４年度は４６.９％というのは、いわゆる区内死亡者数の中で、約半数弱が臨海斎場を利用されている。私もお通夜とかご葬儀によく伺うのですけれども、やはり臨海斎場の利用率は民間斎場と比べてもかなり多いなという印象を受けています。こういった理解でいいのかどうか、もう１回確認させてください。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、臨海斎場につきましては、半分の方がご利用になっているということです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"今後いわゆる多死社会と、高齢化が進むにつれて多くの方がお亡くなりになる時代が来るということが盛んに言われていますが、同じ臨海斎場組合議会の資料の中に、臨海斎場の火葬需要というのが、２０１５年から２０１９年の年間の平均８,４２１人が、２０６０年から２０６４年では平均１万３,００７人になるという、こんなデータも推計で出ている中で、先ほど戸籍住民課長からあったとおり。","respondent":"吉野戸籍住民課長","answer":"失礼いたしました。既に令和５年度から、いわゆる組合の中では一応お話は出ておりまして、実際に議会に出てくるのは、やはり令和６年とか令和７年になると思われます。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"増設の計画もあるということで、ここについては本当にご要望に沿うのかなと思いつつ、ただ、どうしてもスピード感が、先ほど山本委員からもありましたけれども、スピード感からいって、これは２０３０年度に増築施設での事業開始ということで、あともう７年ですか。何かあればぜひお願いします。","respondent":"吉野戸籍住民課長","answer":"去年、前年度ですが、臨海部広域斎場組合議会というのがありまして、そこで委員のご指摘のとおり、これから来るであろう大規模な災害に向けて、やはり少しでも前倒ししたほうがいいのではないかという意見がありまして、組合からも、その辺も、先ほど答弁でも言いました。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"確認","question":"すみません、さっき少し質問し忘れてしまって、最後にしますけれども、生活衛生課長にお伺いしたいのですけれども、先ほど、民間斎場を置いている６区の共通見解として、今回、コロナ感染症でお亡くなりになった方を受け入れなかったことについて、新宿区と葛飾区、いわゆる落合斎場と四ツ木斎場を使ったのだと。だから、このご指摘は当たらないというようなご説明があったと思うのです。","respondent":"舩木生活衛生課長","answer":"繰り返しの答弁になりますが、本民間事業者が運営している６か所の火葬場では、新宿区と葛飾区のみで受け入れてきたという認識でおりますので、品川区の方がコロナに感染されてお亡くなりの方は、臨海斎場を使用されたほか、受入れを可能とする他の斎場で火葬というか。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"臨海斎場というのが今、公で、５区でという形で運営をしているわけです。もう一つ品川区内には民間の火葬場があるわけですけれども、民間ですから、価格設定というのはそこが決められるわけですよね。幾ら以上は駄目ですよとか、そういう法律というか条例の担保というのは、まず民間の葬祭場に関してはあるのか、分かれば教えていただけますか。","respondent":"舩木生活衛生課長","answer":"その部分につきましては実はいろいろご指摘もいただいておりますので、今後につきまして、火葬業に関する収支を保健所に報告いただくということであるとか、大幅な、大規模な修繕計画がある場合にも、そういった大きな修繕計画があるということを事前に共有するとか。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"そこはすごく大事だと私は思っていまして、今で言うならば、資源等が、原材料等高騰したからしようがないのですよ、うちも経営ですからと言われたら、火葬する親族の方にとっては、やはりどうしようと悩むと思うのです。地域性かもしれませんけれども。その辺について、行きやすくしていただきたいとすごく思っていますので、その辺については、これからどういうふうに考えていくか。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、もう少し便がよくなるようにというところでのいわゆる増便とか、そういったところも今後の検討課題だと認識しております。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"増やしますよね。新しくできるのが６基でしょう。さっき答弁があったけれども、時期もそうなのですけれども、私は、それを１つでも多く要望していただいて、何週間も火葬するのを待っていただくという状況にならないようにしていくのが、そして安価で火葬できるようにしていくのが、行政の役目だと思っていますので、その辺については臨海部広域斎場組合に要望してほしいということも含めて、いかがでしょう。","respondent":"吉野戸籍住民課長","answer":"先ほど答弁させていただいたとおり、平成２７年度の数字が基になっておりますので、現状に合った数値でもう一度計算するということを臨海部広域斎場組合は言っておりまして、そちらの見解を見た後、こちらの要望も伝えていきたいと考えています。","id":"exchange-010"},{"speaker":"えのした委員","kind":"意見","question":"今、本当に全国的に火葬場不足ですとか、ニュースにもなっていますが、民間施設の価格の高騰も取り上げられておりますけれども、やはり令和１２年度利用開始の、臨海斎場の施設増設、やはり早めに検討していただいて、会派としてもお願いするところでありますが、先ほど大規模災害時に斎場と協定をほとんど結ばれていないというお話でしたが、現状、そういった協定を結ばれているのか、他区の状況ですとか。","respondent":"吉野戸籍住民課長","answer":"大規模災害になった場合ですけれども、品川区で、例えば臨海斎場と桐ヶ谷斎場がもう使えないほど被害者の方が増えてしまった場合は、品川区の災害対策本部から東京都に、いわゆる広域火葬といったものを要請しまして、そこで東京都の指示の下、どこ、どこという形での。","id":"exchange-011"},{"speaker":"えのした委員","kind":"質問・要望","question":"継続です。やはり今すぐ開設できない。でも、課題としては、今ニーズがありますので、継続ということで。会派としても施設増設の時期を早めていただきたいと要望していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"継続でお願いします。一応意見を述べると、先ほど確認させていただきましたが、この陳情と品川区の見解で若干異なる部分もありますけれども、おっしゃっている意味はよく分かります。その上で、臨海斎場がこれから増設をすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"山本委員","kind":"意見","question":"継続でお願いいたします。ほかの委員からもお話がありましたけれども、今後の進捗を見守るということで、継続といたします。区民の皆様にも関わるとても大事なことですし、一刻も早い、そして、安価に使えるようにしていただけることを望みます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"せらく委員","kind":"質問・要望","question":"継続です。意見を述べしますと、やはり場所だとか、住民の皆様のご理解を得ながら火葬場は設置しなければいけないというところで、今ある臨海斎場の炉を増やす、そういうところはスピード感を持ってやっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"横山委員","kind":"確認","question":"現時点では継続でお願いします。ほかの組織区ですとか近隣区、あと都全体の将来火葬需要などの状況というのが、コロナ前ということで、平成２７年度から少し現状が、少しというか、大分変わってきているというところがあるので、そうした状況を確認する必要があると思います。今後も引き続き、各方面からの情報を注視していくことが重要と考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-02","title":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"ただ、なかなか役所の分かりやすい場所にないという感じで、故人のご家族に対しての配慮、そういったところを丁寧にお考えいただいて、また、職員の負担にならないように、そしてワンストップ、これ、例えば何課と何課と何課が、申請手続きが必要な課がどのぐらいあるのだというところを教えていただけますでしょうか。","respondent":"吉野戸籍住民課長","answer":"中には、一番多くの処理としまして、国保医療年金課、高齢者福祉課、子育て応援課、障害者支援課、あとは保健センター、健康課、税務課があります。そういったところと連携しながら行いたいと考えています。","id":"exchange-017"},{"speaker":"えのした委員","kind":"意見","question":"やはり８課にわたるということになると、区民にとってもサービスの向上、おくやみコーナーをつくってよかったなという話になると思いますが、やはりその場所ですね。何かパーテーションを作るなり、見えないようにするなり、ご配慮いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"この手続きの流れのところで幾つか教えていただきたいのですけれども、１日最大４組ということで、８時間ぐらいの稼働の中であるので、２時間ぐらいが取られている時間なのかなと思うのですが、予約制ということで、あらかじめどういういったことかを事前に聞いておいて、当日に各課、先ほど、委員からのご質問でもありましたけど、８課ですかね、それらには事前に連絡をしておいて。","respondent":"吉野戸籍住民課長","answer":"電子申請書にチェックボックスみたいなものを用意する予定でおりまして、亡くなられた方が何を持っていたのかとか、そこをチェックするような形にしたいと思っています。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"今おっしゃったように、最初に、行政書士が受け付けて、そこから各課に話をするとすると、そこからすぐに来てもらえれば、その場でできると思いますし、でも、すぐ来られないとすると、また次のタイミングになったりということで、やはりそういった効率的にするというところで言うと、事前に確認できたりするのが好ましいなどというのもあると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"質問・要望","question":"我が会派の一般質問でも申し上げましたけれども、これは２００３年から我々もワンストップサービスのこういった手続きをずっと求めてまいりまして、ようやく、しかも新庁舎ではなく現庁舎のほうで実現をするということで、非常にうれしく思っています。そこで、少し細かいことを幾つかお伺いしたいと思います。一旦そこまでお伺いをしたいと思います。","respondent":"吉野戸籍住民課長","answer":"まだ契約前なのですが、今の想定では、相談受付としましてお二人の方を常駐で想定しております。それから、予約ということで、午前２件、午後２件という形で対応していただこうと考えております。","id":"exchange-021"},{"speaker":"あくつ委員","kind":"確認","question":"そこで、先ほど電子申請とあったのですが、窓口に来ていらっしゃったときに、先ほど例示があったものだけで８課、私もよく回ったときに、ほかのところの課もあるのですけれども、例えば申請書に前もってその方のお名前とかご住所とか、必要事項はもう既に印字をされている状況、いわゆる書かない窓口とよく言いますけれども、そういう形でブースでご用意をされているのかどうか。","respondent":"吉野戸籍住民課長","answer":"実は、書かない窓口というのを情報推進課といろいろと話をしている最中でして、始まった当初は無理かなと思うのですが、来年度に向けて、事前にもう入力しておいて、申請書も出るような感じに、バージョンアップをしていきたいなと考えております。","id":"exchange-022"},{"speaker":"あくつ委員","kind":"確認","question":"私どもは、豊島区等のおくやみ窓口を見てまいりましたけれども、かなり見やすくて、非常にビジュアル的に分かりやすいものを作っていらっしゃったので、これも少し一般質問の繰り返しになってしまうかもしれないのですけれども、当然ネットでご覧になる方もいらっしゃると思いますので、このあたりについてどのようにお考えになっているのか、最後に確認したいと思います。","respondent":"吉野戸籍住民課長","answer":"一般質問でもありましたとおり、少し小さめのものになっておりますので、少し大きくして、他区のいいところを取り入れながら、刷新していきたいなと考えております。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問","question":"これは戸籍住民課ではないです、広報広聴課ですが、そういったところについて、今のところどういうお考えなのかというところと、ごめんなさい、これも聞き忘れていました。今回、これは委託契約をして、行政書士は品川区役所のいわゆる区長の出先機関という形になるのか、それとも代理として申請書類を書くのか、このあたりの法的な関係がもし分かれば教えてください。","respondent":"吉野戸籍住民課長","answer":"相続に関しましては、委員のおっしゃるとおり、それ以上のことはできないのですけれども、ただ、相談という形ではできるかなと考えています。場合によっては、区民相談室の司法書士や弁護士に予約を取って引き継ぐとか、そういったことも、今想定しているところです。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。幾つか伺ってまいります。３、事業の流れの（２）で、各種相談受付ということで、相続という話も一般質問のご答弁でもありましたし、先ほどの質疑の中でもあったのですけれども、相続以外にどういったご相談をされているのかというのが分かりましたら、教えてください。","respondent":"吉野戸籍住民課長","answer":"大体ほかの区は、試行的にまず１日４組というところから始めておりますので、それに倣いまして、まずそこから試行的に進めまして、増えた場合にはまた考えていきたいなと考えているところです。","id":"exchange-025"},{"speaker":"横山委員","kind":"質問・要望","question":"様々なご相談が寄せられる可能性があるということで、まずは試行的に４組というところからスタートして、１月から３月までの様子を見つつ、来年度どうするかというところを考えて進めていかれるのかなということで、確認させていただきました。","respondent":"吉野戸籍住民課長","answer":"委員ご指摘のとおり、まず専門性というところ、我々はやはり異動してしまうこともありますので、そういった中で、行政書士という行政手続きに精通した方のノウハウといいますか、そういったものを我々は勉強させていただいたりして。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひそのあたりも進めていただけたらと考えていますので、どうぞよろしくお願いいたします。グリーフケアについては、現在、区としてどういったご案内といいますか、どういった対応をされているのか。そういった手続きの中で、大丈夫かなとか、気づきとか、お声かけとか、そういった様々な機会にもなるのかなと思っているのですけれども、そのあたり、現在どういうふうになっているのかを確認させてください。","respondent":"吉野戸籍住民課長","answer":"遺族の方に寄り添うというところでは、委員のご指摘のとおりでして、どういったしつらえがいいのかというところを今ちょうど考えている最中でありますので、やはり寄り添ったサービスができるようなしつらえを、今後考えていきたいと考えています。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問","question":"次の質問にもなるのですけれども、死亡届が提出されるタイミングで冊子をお渡しされるということがあるかと思うのですけれども、例えば周知方法のところで、広報しながわとホームページやＳＮＳなどということであるのですけれども、冊子が新しくなるまでの間に、そうしたおくやみコーナーのご案内とか、そのあたりもどうされていくのかなというのが少し気になっていましたので、その２点を教えてください。","respondent":"吉野戸籍住民課長","answer":"こちらの冊子につきましては、できるまで少しお時間をいただきますので、やはり少し違った案内のものを作りたいなと考えているところです。ご案内につきましても、この冊子を渡すときに、こういったものを作りますというものをつけてと、考えております。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ必要な方に情報が届くように、適切なタイミングで、冊子ができるまでの間もご案内につなげていただけたらなと思っています。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"予約等ができなかった方へのフォローといいますか、対応はどういうふうにしていくのでしょうか。今までもそういうことをしてきたと思うのですけれども、せっかくワンストップという形でおくやみコーナーが、補正予算が通ればできていくわけですけれども、その辺の、残り二千何百人の方に関してはどのように考えているのか、教えていただけますか。","respondent":"吉野戸籍住民課長","answer":"予約を取らずに来られる方は恐らくいらっしゃると思いますので、そのときには、まずは、例えば相談窓口がいっぱいでなければ、そこで臨機応変に対応していただくというような形を取ろうかなと思ってはいるのですけれども、もし窓口がいっぱいの場合には、冊子をお渡ししてという。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、いろいろな質疑応答を伺っていて、悲しみとかで、人と人というお話をしているわけでしょう。だから、葬儀屋ですかと伺うのもあれですけれども、葬儀屋にその冊子をある程度渡しておいて、葬儀をやる方、また火葬する方にお渡ししておいて、品川区ではこういうことをしていますよということを広報していくべきだと私は思うのですけれども、その辺についてはいかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、亡くなられたということでご心情を察しまして、どのように対応したら寄り添えるのかというところを含めて、もう一度、その辺につきましては検討させていただきたいと考えております。","id":"exchange-031"},{"speaker":"山本委員","kind":"確認","question":"さんざん待たされるというのはかなりつらいのではないかというところから、再度お聞きをすることなのですが、行政書士は、役割としては補助だということだったのですが、例えば死亡一時金とか遺族年金とか、それぞれ書類を提出したりする手続きが発生するのかなと想像しているのですけれども、そういったものは、そこの窓口に行ったときに、行政書士の方がお相手になって、必要事項を書いて、それで。","respondent":"吉野戸籍住民課長","answer":"そちらで書類を書いていただきまして、関係各課と、書類の内容が合っているかどうかという確認を取らなければいけませんので、共有のフォルダー、もしくはＬｏＧｏチャットというのがあるのですけれども、そちらでデータを見ていただいて、間違いないねというような。","id":"exchange-032"},{"speaker":"山本委員","kind":"確認","question":"その場に各課の方が来なくても、デジタルで共有できることでリアルタイムに確認いただけて、手続きは進められるということで、それはとても効率的でいいのではないかと思いましたので、ぜひそのように進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"せらく委員","kind":"意見","question":"先ほど年間の受付可能数といいますか、最大の受付可能件数というようなお話があったところですけれども、少しそれに関連しまして、今回関わる各課は８課あることをお話しいただきましたが、その各課の日曜日の開庁状況なども含めて、今後、日曜日の窓口開設が可能かどうかというところをお聞かせいただければと思います。","respondent":"吉野戸籍住民課長","answer":"おくやみコーナーに関しましては月曜日から金曜日で、日曜日の開設は今は考えていないところではあります。やはり今後のニーズ、そういった状況によって、検討課題になるかなと考えています。","id":"exchange-034"}]},{"id":"topic-03","title":"令和５年陳情第３５号、適格請求書等保存方式（インボイス制度）で新たな負担を受ける事業者に対して区独自の支援策を求める陳情","agenda":"令和５年陳情第３５号、適格請求書等保存方式（インボイス制度）で新たな負担を受ける事業者に対して区独自の支援策を求める陳情","exchanges":[{"speaker":"山本委員","kind":"質問","question":"区は現状、インボイスに特定した支援策というのはないようですが、インボイス制度導入に伴って、例えば資金繰りが悪化したりして経営に困る事態の方向けの制度ということで言うと、物価高騰等総合支援資金があるということですが、それは使えるという理解で合っていますでしょうか。","respondent":"小林商業・ものづくり課長","answer":"物価高騰等総合支援資金は、区がもっている融資あっ旋制度の１つのメニューですけれども、いわゆる設備資金、運転資金というところで、区の事業者の経営課題、あるいは経営困難を乗り越えるために必要だということであれば、こういった支援制度が使えるです。","id":"exchange-035"},{"speaker":"山本委員","kind":"質問・要望","question":"最後に、税負担が増える方、免税事業者から課税事業者になったときに、国の経過措置で８割、売上げ税額が控除されるというところもありますが、残りの部分で言えば増えるというところ、ここに対する助成はなかなか厳しいところではあるかと思いますけれども、品川区の経済を支えていくという観点から、経済の混乱を起こさないという観点からも。","respondent":"小林商業・ものづくり課長","answer":"税負担のところにつきましては、今回、導入に当たって激変緩和措置というのが約６年間ありますけれども、この部分については、国の税制措置の対応の考え方というところで、区として直接申し上げるのは難しいところです。","id":"exchange-036"},{"speaker":"山本委員","kind":"質問・要望","question":"国の制度との兼ね合いで進めていくことは、地方行政としてなかなか難しいところもあるとは思いますが、区民は、今回始まるということでどうなっていくか分からないということ、それから、不安を抱えている方が多くおりますし、品川区の経済に影響を与える懸念もありますので、ぜひそういったことも踏まえて、前向きにできることをご検討いただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"えのした委員","kind":"質問","question":"結論を出すで不採択です。今、ご答弁がありましたように、国の税制に関わるものでもあります。品川区では、事業者の皆様からの経営相談について窓口相談を実施しておりますし、区民の方に広く周知いただいて、国の助成や取組をご案内して、小規模事業者の方の負担軽減につながるようにご対応をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回の陳情の中で、品川区独自で区内事業者の支援を図ることのご要望ですけれども、先ほどもありましたけれども、国の様々な手当といいますか制度、先ほどあったレジ等の買い換え、またソフト等の導入においては、ＩＴ導入補助金というものを国が置いているということと、税理士へのオンラインでの相談体制もつくっているということ、また、小規模事業者持続化補助金というものも置いているということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"山本委員","kind":"意見","question":"本日、結論を出すということで、私どもは採択でお願いいたします。先ほどの質疑の中でもお話をさせていただきました。国の制度というところで、それから、国の補助だったり相談窓口があるということは理解しております。そういった理由から、先ほどの質疑でも申し上げましたとおり、区としての独自の支援策をしていくことがふさわしいと思いますので、この陳情は採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"本日、結論を出すで、採択でお願いします。理由としましては、維新としては、インボイス制度については公正な納税をするべきだと考えておりまして、この陳情の理由にあります制度の反対という部分は、維新としては考えには反するものの、区でできる支援は考えるべきだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"本日、結論を出すで、先ほどの説明、議論を踏まえて、不採択でお願いします。私は、適切な場で議論されることが最善だと考えています。業界ごとにその構造やビジネスモデルは異なります。ご相談があった際には、業界ごとの違いや、お一人おひとりのご事情に寄り添ったご対応を引き続きお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"}]},{"id":"topic-04","title":"「品川区再犯防止推進計画（素案）」およびパブリックコメントの実施","agenda":"「品川区再犯防止推進計画（素案）」およびパブリックコメントの実施","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"これからまたパブリックコメント等も１０月１日から始まりますが、本当に、犯罪によって、再犯率が高いという犯罪の内容もありますので、そういったところも注視していただいて、やはり細やかな支援をこの計画の中に入れていただいて、寄り添った支援、計画を立てていただければと思います。私からは要望として以上ですが、何かご見解があればお願いします。","respondent":"宮澤地域活動課長","answer":"犯罪をした方の中には、貧困や疾病、障害など、様々な生きづらさを抱えている方がいらっしゃいます。今回の再犯防止推進計画を策定しまして、就労、住居、保健医療や福祉といった多岐にわたっている施策というのを、整合性をもって総合的に進めていくです。","id":"exchange-043"},{"speaker":"横山委員","kind":"確認","question":"幾つか伺っていきます。素案の概要版の部分ですけれども、第２章、品川区における再犯防止を取り巻く状況のところに、課題として、「犯罪をした者の改善および更生を助けるとともに、犯罪の予防のための活動を行う“保護司”の適任者の確保」が挙げられているかと思うのですけれども、保護司の適任者の方には、今後どういった方が必要とされるのかという区の考えを確認させていただけたらと思います。","respondent":"宮澤地域活動課長","answer":"今年６月１日現在、区内で保護司として活動されている方は９５名と伺っておりまして、充足率を含めまして、また保護司の方の平均年齢というのも上がってきているというところから、この再犯防止につきまして。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問","question":"次の質問ですけれども、素案の２ページの、今、４をお聞きしたのですが、５の計画推進体制で、品川区再犯防止推進委員会ということで今お話もありましたけれども、その委員会のメンバーとして、委員としてはいらっしゃらないけれども、支援団体ですとか、実際に立ち直られた方ですとか、あとはまた、区内の各警察署ということであるのですけれども、例えば学校等と連携した就学支援の実施の取組ですとか。","respondent":"宮澤地域活動課長","answer":"この再犯防止に関しても、７月が国での強調月間ですので、こちらを合わせまして、社会を明るくする運動等を通じて、関係団体等のご協力も得ながらやっていく中で、関係づくり、連携というのも深めていきたいと考えているところです。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"再犯防止推進計画ということで、様々な施策の整合性をもたせる意味で策定をされたというご説明が先ほどありました。そのあたりについてのご見解があればということ。それから、これはすごく素朴な疑問で恐縮なのですが、保護司の所管が地域活動課だから、今回、地域活動課長がこういったものの取りまとめをされていらっしゃるということなのでしょうか。","respondent":"宮澤地域活動課長","answer":"所管の考え方というところからお答えします。地域活動課におきまして、社会を明るくする運動というのを所管しております。その関係から、保護司会も所管させていただいているところです。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"そういったところをしっかり埋めていただくために、７月の社会を明るくする運動であったり、これまで区としてすごく頑張っていただいているかなと思うのですけれども、先ほどおっしゃっていただいたような講演会であったり、もう一段階深く、実際の立ち直りを目指す方というのがどういった方々なのかというところの理解が深まるような、そうしたところもイメージをしていただきながら。","respondent":"宮澤地域活動課長","answer":"周知も含めて、行政として取り組んでいきたいと考えているところです。","id":"exchange-047"}]},{"id":"topic-05","title":"まちぐるみ文化イベント","agenda":"まちぐるみ文化イベント","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"先ほどの「エシカルベント ｉｎ しながわ」が中小企業センターで行われて、それと連動して同時開催、「サステナブルイベント ｉｎ とごし」ということで、エコルとごし等で行われる。このまちぐるみ文化イベントも同じ日に行われるということなのですが、この企画もあえて意図的にそういう形にされたのかどうか。このチラシに載っていますけれども、そのあたりを教えてください。","respondent":"篠田文化観光課長","answer":"えばら」に関しましては、荏原地区で広く実施するですので、関係の各所管等にもお声かけをしまして、この時期のタイミングで合わせて、様々なイベントを実施していただけるということであったものですから、併せて連携を、関係を取りながら開催するという形を取ったものです。","id":"exchange-048"},{"speaker":"あくつ委員","kind":"意見","question":"連携を取って各所管で行うということで、何かそれで効果が見込める、集客効果が見込めるとか、何かＳＤＧｓに資するとか。先ほどの２つのイベントについてはそうなのですけれども、今回は文化イベントということなので、その目的というのは、連動してやる目的というのは何でしょう。","respondent":"篠田文化観光課長","answer":"荏原地区というのは非常に広くて、どうしても荏原地区というと、武蔵小山商店街ですとか西小山地域ですとかが中心になってしまうのですけれども、この区役所の手前までが荏原地区ということになりますので、できるだけ広く地域を知っていただこうということもあって。","id":"exchange-049"},{"speaker":"えのした委員","kind":"意見","question":"もちろんこの１枚で分かるとは思うのですけれども、ポイントで違う地域からまた違う地域へ来街を促すような方法も取っていただけると、いろいろな地域を超えた交流ですとか、また新しい発見などにもつながるとは思うのですが、その辺は何か考えておられますか。","respondent":"篠田文化観光課長","answer":"その辺を踏まえますと、それぞれうまく地域間の連携が図れるといいなと思っているのですけれども、何分荏原地区は広うありますので、１日で全部回るのは、正直なかなか難しいかなという思いもあります。","id":"exchange-050"},{"speaker":"えのした委員","kind":"意見","question":"そうですよね。この「リアル謎解きゲームｉｎしながわ」、こういうものも回遊型のイベントということで、興味を持っていただければと思います。お願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238887?Template=document&Id=2968#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":44975,"voices":155}},{"id":"r05-20230925-7","meetingId":"r05-cm09","date":"2023年9月25日","dateIso":"2023-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を113件抜き出しています。","topics":[{"id":"topic-01","title":"幹部職員紹介","agenda":"幹部職員紹介","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"よろしくお願いします。ただいまこちら、現行は大起エンゼルヘルプが行われており、そしてまた、こちら１５年たちましたので、改めて公平に公募したところ、応募してきた１件がこちらという認識でよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"こちらの指定管理者候補者のことにつきましては、現行も、こちらの大起エンゼルヘルプのほうが１５年間行ってきておりまして、今回公募した結果、選定をしまして、また、同じく株式会社大起エンゼルヘルプになったという次第です。","id":"exchange-001"},{"speaker":"ひがし委員","kind":"質問","question":"今回公募の結果、このエンゼルヘルプ１社から公募、申請があったということなのですけれども、この１社になった理由、品川区としては何社からも公募が来たほうがいいのか、それとも前回と慣れていたこの１社が来てくれて、そこで思っているところをクリアできていればよいとしているのか、区のお考えとしてはどうなのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"ただ、１社としても、きちんと選定予備委員会、選定委員会のほうは実施させていただきまして、適正な形で提案書も見させていただきまして、選定に至ったと考えています。","id":"exchange-002"},{"speaker":"ひがし委員","kind":"質問","question":"やはり何社からも来て、その中から選ぶということがいいと区も思っているということなのですが、そうなると、課題としてはやはり１社からしか申請が来ないというところは問題なのかなと思います。これからそういった公募を募集するときの課題などについても教えていただけますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今回は１社になってしまったというところは、いろいろと、公募の期間を長くすれば多くの事業者が来るのかといったら、またそれも違うのかなと思いますので、その辺りのところ、例えば運営経費など全体の経費のバランスとか、そういったところに。","id":"exchange-003"},{"speaker":"ひがし委員","kind":"質問・要望","question":"公募も今後ホームページに載せるだけではなくて、その内容も含めて検討していただいて、窓口を広く、ほかの人たちが手を挙げやすいような公募方法というものを考えていただきたいと思います。こちらは要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"私からも、せっかく公募をしたのに、結局これまでの体験でしか応募しなかったということになったわけですけれども、ここのところでは、例えば先日の障害者の福祉などにしても、４００事業者に対して、このように公募しますという通知をしたというようなことも伺いましたが、ただホームページに載せるというだけではなく、そのような周知の工夫というものはないのかなと思ったのですけれども。","respondent":"菅野高齢者福祉課長","answer":"国のほうも、今第９期の介護保険事業計画のところで審議会等開いておりますが、その中でも、小規模多機能居宅介護についてはもっと数を増やしていきたいというところで、課題にしているところで、先日も厚生労働省のほうから。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"提案","question":"それと、今回新たに公募という形で、大起エンゼルヘルプがまた応募したわけですけれども、これまでと違う新たな提案というものがあるのか、あったらその中身についてもお聞かせいただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらの大起エンゼルヘルプにつきましては、委員もちょっと触れていただきましたが、その辺り、介護人材の採用、海外人材の技能実習生の受入れというところで、そういった採用をしたいとか、あとは見守りシステム等を入れて、業務の効率化というか。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、同じように西大井のこうほうえんのケアホームがあると思うのですけれども、ここのケアホームは、ここは指定管理者ではないので、このようなモニタリングというものがなくて、どれぐらいの利用率になっているのかということは分からないのですが、でも聞くところによると、西大井のこうほうえんのケアホームはなかなか入れなくて、希望しても結構、安いほうが特になのですけれども、２年ぐらい、１年。","respondent":"菅野高齢者福祉課長","answer":"同じくこうほうえんについてのことなのですけれども、ちょっとすみません、こうほうえんについては指定管理施設等ではないというところもございまして、入居率については詳しく把握はできないのですが、こうほうえんの中でもお部屋の内部がいろいろございまして。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問","question":"この大起エンゼルヘルプは株式会社ですけれども、同じところで、同じ系列で社会福祉法人をつくっているではないですか。様々、社会福祉法人では特別養護老人ホームの運営などもしているわけですけれども、なぜ東大井の多機能ホームは、そのような社会福祉法人、同じ系列の中で社会福祉法人ではなくて、株式会社というようなことで区としても選んでいくのか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"こちらのケアホームの料金等につきましては、介護度によって少し差はありますが、おおむね２０万円前後が、引き続きまたご利用様に負担されるものというところで認識しております。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問","question":"公募要領の中で、利用料収入が超過した場合の区への還付というものがあって、各年度の収支決算時に、指定管理業務における利用料収入額が支出を一定程度上回った場合は、その差額を品川区に還付するものとしますということで、なお還付の有無および金額については、区と指定管理者が協議の上、会計年度ごとに決定いたしますというようになっているのですけれども、この一定程度上回った場合というものの。","respondent":"菅野高齢者福祉課長","answer":"この形態の福祉施設におきましては、平成２１年に開設以来、収入額が支出額を上回ったという事例がございませんので、このような還付の事例がないということが実情となっております。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"提案","question":"分かりました。この取る取らないという、無償貸付けというものもあるではないですか。それからもう一つ、公募要領の中に、提案のあった経費を精査して区の予算の範囲内で認められた指定管理料を支払うと書いてあるのですけれども、その指定管理料というものが毎年毎年違っていますが、これは、これまでは何に対して指定管理料というものが算定されて額も決められてきたのか、そのことも教えてください。","respondent":"菅野高齢者福祉課長","answer":"その部分については、事業者と協議の上ということはご指摘のとおりなのですけれども、基本的に小規模多機能の生活相談支援業務として約５００万円のお支払いと、あとは建物全体の維持管理をお願いしておりますので。","id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"質問","question":"はですけれども、今回公募１社だけだったということなのですが、仮にこれ１社もなかった場合、結構最近１社の公募だけということはよく聞くのですけれども、公募がなかった場合というものはどうなるのですか。","respondent":"菅野高齢者福祉課長","answer":"公募がなかった場合は、応募していただく事業者が出るまで、また公募をするという次第になります。","id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問","question":"となると、例えば指定管理の期間が過ぎてしまったりなどということは、考えられなくもないかもしれません。そういった場合はどのように対応される予定でしょうか。","respondent":"菅野高齢者福祉課長","answer":"もしもの場合のお話なのですけれども、そのような場合には、例えば現事業者のほうに延長してやっていただくなど、そういった対応もあるとは聞いております。","id":"exchange-012"},{"speaker":"やなぎさわ委員","kind":"確認","question":"分かりました。改めて確認なのですけれども、品川区として介護人材というものは結構不足していて、各事業所、人材募集を集めるのは大変だというような認識の下取り組まれているのか、そうではないのか、ひとつその辺お伺いしたいです。","respondent":"菅野高齢者福祉課長","answer":"区においては、直接人材が集まらないので事業がままならない、そこまでのお声は聞いてはいないのですけれども、平成３年度に介護人材の確保戦略という、そういった報告のほうもさせていただきまして、法人のほうにはいろいろな介護人材の確保方策についての。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"質問","question":"となると、今区として取り組んでいる、こういった対策で、ある程度十分であるとお考えですか。","respondent":"菅野高齢者福祉課長","answer":"区として取り組んでいることで決して十分であるとは、そこまでは思ってはいないところで、今後どんどん生産年齢人口が減っていく、一方では高齢者の人口が増えていくというところで、厳しい状況にはなっていくと思いますので、常に事業者等のお声に耳を傾けながら。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問","question":"松永委員長は、本会議一般質問で介護人材の不足についてお話しされたときに、区としてご見解で、介護人材の不足は認識していないというようなお話があったのですけれども、その点、ちょっと今のお話と併せてなのですが、改めて区の見解をお聞かせいただけますか。","respondent":"菅野高齢者福祉課長","answer":"今のところ、そちらについての本会議答弁での内容につきましては、現在のところ、先ほども申し上げましたが、各事業者が介護人材が確保できないので事業のほうがままならないから、例えば撤退するなど、そこまでのお声は聞いていないというような表現だと認識しております。","id":"exchange-015"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その確保事業の１つに海外人材の確保が含まれているということでしょうか。","respondent":"菅野高齢者福祉課長","answer":"海外人材の確保につきまして、基本的には、人材の確保というものは、各事業者が努力していただくことが前提なのですけれども、例えば海外人材の確保となりますと、管理団体がどこでお願いするかとか、いろいろなルートとか、難しい部分もあります。","id":"exchange-016"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"すみません。この指定管理者の大起エンゼルヘルプが、運営がいいか悪いかなどということではないのですけれども、やはり毎回、結構このような指定管理関係などが１社しか応募がないということが、綱渡りなのかなという状況を考えて、想定できるかなと思いまして、民間活力ということをよくおっしゃられているのですが、やはりこれ結構限界なのかなと思ったりするのです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"筒井委員","kind":"提案","question":"ほかの業者が現れても、結局現行の業者が取ってしまうので、いくらこちらとしてもプレゼンしても無駄ではないかという、そういった意識効果がもう働いているとか、このような、１社しか公募に応募をしなかったということが続いたら、そうしたことがさらに拍車をかけて、ほかの業者の方の意識効果を生じさせてしまうのではないかという部分を懸念しているのですけれども、その辺り。","respondent":"菅野高齢者福祉課長","answer":"こちらにつきましては、令和３年度に指定管理者制度に係る基本方針というものを区としては改定させていただきまして、そこのところの改定によりまして、指定管理者の更新の年数が１５年ということに改められました。","id":"exchange-018"},{"speaker":"筒井委員","kind":"質問・要望","question":"もう１点といたしましては、選定予備委員会で出された採点表、３ページの（５）番の採点表と、その後の指定管理者候補者選定委員会の採点表、５ページの（６）番で、選定予備委員会が出した採点と選定委員会の出した採点と比較すると、選定委員会のほうが出した採点が、選定予備委員会で出した点より低くなっているのですけれども、この点、どのような経緯というか、理由で少し下がってしまったのか。","respondent":"菅野高齢者福祉課長","answer":"選定委員会におきましては、予備委員会での結果を踏まえて、対象事業者のプレゼンテーションとヒアリングを実施し、また、委員には有識者２名も入るということも考えますと、選定委員会のほうが若干厳しい点数になる傾向があるのではないかと分析しているところです。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問","question":"ここはやはり気になりますので、どうかこの離職者が高いという、国の平均よりも高くなっているといったところは非常に気になりますので、何が原因だったのか、どうしたらば離職者を減らしていくことができるのか、その辺をこの選定委員会のとき等々聞き取られたかと思いますけれども、いま一度その点、どのような原因でどのような対策を、この事業者は取られようとされていたのか。","respondent":"菅野高齢者福祉課長","answer":"１点目の、結局１社だったというところなのですけれども、こちらも令和３年度に基本方針を改定した際に、制度運営の透明性や公平性を図る観点からというところでの公募という決め事ができまして、今回公募というところに踏み切った次第ではあるのですが、委員おっしゃるとおり。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですから、必ずしも人材確保が、スキルをつけて人材確保をするのが難しいだけの話ではなく、その事業者内部で起きている、そうしたところまで寄せて、事業者の人材確保というところにもどうか視点を当てて、その点を両者で支援というか、サポートというか、そのところをしていっていただけると、また、この離職率は単純に離職する方の理由、先ほど言っていらっしゃいましたけれども、それには。","respondent":"菅野高齢者福祉課長","answer":"この事業者についても同じような認識でいると思いますので、その辺りのところは、何か問題なことがあったときには相談するなど、いろいろと連携を取りながら、離職率が改善していくように努めていきたいと思っています。","id":"exchange-021"},{"speaker":"こんの委員","kind":"提案","question":"ぜひお願いしたいと思います。この１５年間やってきてくださった実績、また新たな提案ということも先ほど伺いましたので、どうかこの大起エンゼルヘルプがよりいいサービスを区民の方に提供できるようにしていただくよう、先ほど申し上げた点も踏まえて進めていただきたい、このように考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"６ページのところに別添ということで、福祉部公の施設の指定管理者候補者選考基準評価項目・配点というものがあるのですけれども、これは今回の大起エンゼルヘルプのところでも、これを評価したということなのでしょうか。点数がそれぞれ出ているということなのか、もしも出ているのだったらば、それぞれ何点で合計何点なのかということを教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"結果報告書のほうには総合得点のみの記載となっているわけですけれども、こちらにつきましては、区の全体の指定管理者の選定の報告書の中で、総合得点のみ掲載することというような決め事等もありますので、今後そういったご意見をいただいた上で、よりよい。","id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなことであれば、しっかりと私は報告をしていただきたい。多分福祉部は福祉部でやってもいいという、そのような裁量などもあるのではないのかという気がするのですけれども、もしもそれがないというのであれば、区として検討していただいて、そのような情報としてはもっともっと出していただけるようにお願いしたいと思うのですが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"今の報告書の得点の部分につきましては、基本方針の中で、選定予備委員会または選定委員会の審議内容を取りまとめたものを、報告書を用いて公表することとしております。","id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"１点だけ、先ほどこんの委員からとてもすばらしいご指摘があったと思うのです。給料が安いということは介護業界で同じなので、それを上回る何かがあるから、多分離職率が平均よりも高いということなので、指定管理をしている品川区として、ぜひその辺をしっかりとチェックといいますか、していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"おぎの委員","kind":"提案","question":"すみません。２点をお聞かせ願います。５ページの、こちら地域等との連携について、こちらの評価の部分です。幅広い地域連携を視野に入れている提案があったということで、ここ非常に特色あるのかなと思いましたが、どういった提案がなされたのか、もしよろしければお聞かせください。よろしくお願いします。","respondent":"川原高齢者地域支援課長","answer":"そこの部分につきましては、収支計画のところで５年間分の事業の説明を受けているところでございまして、３年目に関しては、現状の施設長、副施設長、その施設での経験を有するという部分で。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのようなことも、何というのですか、区全体として決めないとつけられないとか、そのような縛りがあるのか、なかったらぜひつけていただきたいと思うのですけれども、また、もしあるようでしたらつけられるようにしていただきたいと思うのですが、その点、１点伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"１点目、ご質問いただきました、ご要望としていただきました、初の指定管理を受ける法人におきましての資料等につきましては、福祉部の公の施設の候補の選定や、あとは品川区全体の指定管理者公募に関する基本方針にのっとりまして。","id":"exchange-027"},{"speaker":"鈴木委員","kind":"提案","question":"事業メニューも豊富で期待感が持てる提案の内容ということで書かれているのですけれども、具体的にどのような中身なのかも伺いたいと思います。それから、運営収支について、区があらかじめ提示した金額に収めているということでも書かれているのですけれども、これは年間幾らくらいの委託料になっているのか、その点についても伺いたいと思います。","respondent":"川原高齢者地域支援課長","answer":"かなり多種にわたる事業を提案してくださっているのですけれども、中には必須提案というところで介護予防、社会参加認知症予防事業、生きがいづくり支援事業、幾つか上げてくださっている中で、唯一この事業者だけ提案してくださったのが。","id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この年間の委託料なのですけれども、これはほとんど、何というのですか、人件費になるということになっていくのでしょうか。そして、この多世代交流のところでは、あまり収入というものがそれほどないのかなという気がするのですけれども、収入としてはどのようなものがどれくらい考えられるというものはあるのか、この委託料がほぼ人件費になっていくのか、その点の考え方を教えていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"施設長についても、他区の老人福祉センターなどの経験者を着任をしてくださる予定ですが、ある程度経験値の高い施設長や、あと副施設長も配置をしていただく予定ですけれども、介護予防の事業も行えて。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ありがとうございました。半分となると、人件費としてもそれほど多くはない、たしか６人ぐらいでしたよね。３人、２人、委託職員１人というような。そうすると、何か人件費がすごく安いような気がするのですけれども、そのようなところでは、本当に人材がしっかりと確保できるような、そういうものの保障というようなところでも、ぜひしていっていただきたいということでお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"こんの委員","kind":"確認","question":"今回の、この公募で来た会社数、Ａ、Ｂ、Ｃ、Ｄと事業者の評価が載っているのですが、ちょっと確認で、事業者Ｂというところでの（１）の運営体制について、区内に事業所を構えているためというように載っているのですけれども、こちらは品川区でもう既に事業所をされている会社なのかということが、１点確認させてください。そこをお願いします。","respondent":"川原高齢者地域支援課長","answer":"事業者Ｂにつきましては、委員ご指摘のとおり、既に区内で運営をしてくださっている法人の１つです。ただ、北品川、こういった多世代交流施設ではなく、別の高齢者福祉施設の運営をしているです。","id":"exchange-031"},{"speaker":"こんの委員","kind":"提案","question":"そうした区内で事業所をされている事業者も応募してきている中で、今回新しいところが決まったということで、より提案がよかったというご説明だったのですけれども、先ほどの男性、女性の参加率から見て男性は少ないので、そちらのほうの視点を入れた取組もされる提案のお話を伺いました。本部経費も含め、事業費に応じた適正な配分が必要であると、このように評価しているわけですけれども。","respondent":"川原高齢者地域支援課長","answer":"こちらで区が指定している、経験値の高い人材をきちんと配置をしていただけるのかというところは、ぜひ念頭に置いて確認をさせていただきたいと考えています。","id":"exchange-032"},{"speaker":"こんの委員","kind":"提案","question":"ですから、この、いわゆる働いている方の報酬というところにも、非常に影響してくるものだと思いますので、どうか本部とのやり取りもされるということですので、せっかく報酬が、例えば職員の待遇改善というようなことが図られても、どこかで滞っているのではないかというようなことが話に出るものですので、そうしたところの滞りがない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"ひがし委員","kind":"質問・要望","question":"働き方がどのようなものなのかというところは気になるところであるのですけれども、やはりそこで考えても、介護のここに入ってくれる方々の人材の人件費というところが低くなっているのではないかなということは、皆さんご指摘のとおり私も気になるところでありますので、ぜひここに決まったとなったときには、その後の使い道、指定管理料がどのように使われているのかというところと。","respondent":"川原高齢者地域支援課長","answer":"人件費の割合が低いというところについては、実際に法人の本部の方との協議を今後していただく形になりますので、奉優会さんのほうとお話させていただきたいと考えています。","id":"exchange-034"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひそこの点については、利用者のことにも関わってきますし、やはり給料というものがしっかり払われて、そこでその方の能力を十分活かすことにつながると思うので、ここのところに書いてある、１０ページのところの上に書いてある、ボランティア活用についてということで、ボランティアの方も利用しながら、きっと運営なども広げていくのではないかなとは思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"提案","question":"１０ページの、そのボランティア活用に関して提案があって、育成や活動を視野に入れた養成講座と、何か非常に面白いなと思うのですけれども、具体的に何か、どのような提案だったのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"こちらのほうに提案がありました内容としては、ボランティア人材の発掘や育成、活動支援、ほかの施設のコーディネートを行うことで、施設の社会貢献活動の拠点としての仕組みを強化していきたいということで、実際にはやりたいというお声を。","id":"exchange-036"},{"speaker":"やなぎさわ委員","kind":"質問","question":"旧来から、奉優会はこういった活動はほかでもされていらっしゃるということでよろしいでしょうか。","respondent":"川原高齢者地域支援課長","answer":"そのとおりです。","id":"exchange-037"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"別の質問ですが、先ほどほかの委員からもご指摘ありましたとおり、やはり人件費のところが、もともと少し人件費が低い点が見受けられるというご指摘もあるとおりですし、やはり正規社員、職員４名、非常勤、これが週何回ぐらいの非常勤なのか、フルタイムの非常勤なのか分からないですけれども。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問","question":"お話で、この奉優会、多世代交流支援施設のノウハウがあるというお話でしたけれども、今奉優会のホームページを見ているのですが、事業所、支所がいっぱい出ておるのですけれども、具体的にこの多世代交流支援施設、現在奉優会がやっている施設はどこなのでしょうか。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました、具体的にどこで実施をしているか、多世代交流に準ずる施設をやっているかという質問です。私も、このホームページを拝見しまして、社会福祉本部の本部長のほうと少し面談というか、訪問をさせていただきまして、具体的なお話を聞いたところです。","id":"exchange-039"}]},{"id":"topic-02","title":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第６５号議案、令和５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"先ほど北品川のほうのシルバーセンターは、今回のこの案件に伴っての工期の変更はないというご説明をいただきましたが、確認です。グループホームの、こちらについての工期の変更を確認させてください。","respondent":"川崎障害者施策推進課長","answer":"こちらのほうも工程表どおりに進捗しておりまして、工期のほうに延長はございません。","id":"exchange-040"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今回賃金等の変更ということで、賃金以外でどういったものが該当するのでしょうか。","respondent":"川崎障害者施策推進課長、川原高齢者地域支援課長","answer":"物価上昇に伴うインフレスライド条項ということで、今回障害者グループホームのところにつきましては、資材の高騰、それから労務費に対して適用されるものになります。高齢者地域支援課所管の北品川シルバーセンターの改築の工事における詳細も、物価の部分もやはりインフレスライド適用となっています。","id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"質問","question":"昨今、物価高ということで、例えば大阪万博か何かが、もともと１,２００億円と言われていたものが、最近のニュースだと２,０００億円を超えるなどといって、もう倍近くなっているようなニュースを見て非常に驚いているのですけれども、例えば、これ以上さらに、大阪万博のように高騰したりということは心配はしているのですが、その点は大丈夫でしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"それで、今後またこの工事の間にインフレスライド条項が適用される可能性はあるのかということと、あと、今後ほかにも、この西大井三丁目障害者グループホームや北品川シルバーセンター改築以外にも、いろいろ施設の工事予定されていると思うのですけれども、こうしたインフレスライド条項が適用され得るということを見越して、ある程度予算立てや。","respondent":"東野福祉計画課長","answer":"ただし、今回の北品川シルバーセンター、それから西大井三丁目グループホームにつきましては、今年度末の工期ということになりますので、適用につきましては、賃金の変動につきましては、この公共工事の設計労務単価の改正が基準となりますので、そういったものを踏まえますと。","id":"exchange-043"}]},{"id":"topic-03","title":"第６６号議案、生活衛生関係営業等の事業活動の継続に資する環境の整備を図るための旅館業法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","agenda":"第６６号議案、生活衛生関係営業等の事業活動の継続に資する環境の整備を図るための旅館業法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"今回の旅館業法の一部を改正する法律ということなのですけれども、この問題、私も国の法律がどのように変わったのかという思いで、国会のほうの議事録なども読んでみたのですが、そこのところでは、やはり宿泊拒否制限の緩和というところに対しては、ハンセン病訴訟の全国弁護団や、それから障害者団体から。","respondent":"舩木生活衛生課長","answer":"現時点ではまだガイドラインも示されておりませんので、その部分も確認しながら進めていきたいと思います。","id":"exchange-044"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、許可の取り直しは必要ないということなのですけれども、これはその後はずっと、もともと取ったところが、何といいますか、許可の更新というようなところまでは何もしなくていいということになるのか、何かちょっと読んできたら、１年以内に、これ東京都になるのかどうか分からないのですが、その衛生関係のことも調査を、検査というか、そのようなことが必要というようなことが少し。","respondent":"舩木生活衛生課長","answer":"もう一つ、譲渡になるわけですけれども、これはもともと施設の構造基準に対して、しっかりとそれぞれの許可業種ごとに基準を満たしているのかということに対して審査をし、そして許可を出しておりますので、それをまた営業の成り手が変わったからといって、それを廃止して。","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問","question":"もう一つ、旅館業法のところなのですけれども、結構民泊よりも、旅館業法で本当に、何というのですか、小さな一戸建てが旅館業法でどんどん民泊のような、管理者もいない、そのような旅館業法でつくられた施設というものがすごく増えていまして、本当に住宅街の一私道の奥に、１５坪もないくらいの一戸建てが旅館業法でつくられるというような、そのようなものが今どんどん増えていると思うのですが。","respondent":"舩木生活衛生課長","answer":"ですから、いろいろ許可を出す際に、やはり地域の方からいろいろご不安、このようなところにそのような施設が建ったときに、安全上の問題であるとか、防犯上の問題であるとか、いろいろご意見も頂戴している状況もありますので。","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問","question":"すみません。今の１３６件というものは、１年間で許可した件数ということなのでしょうか。そうすると、では今までのトータルでこれが何件ぐらいまでになっていて、１年間で５０件がリモートで許可した件数ということであれば、それも含めてトータルでどれぐらいのボリュームになっているのか、その数字を教えていただけたらと思います。","respondent":"舩木生活衛生課長","answer":"トータルという件数は、すみません、ちょっと把握していないのですけれども、今申し上げた件数というものは、許可をし、そして廃止をしという現状の数ですので、今現在その数が現存しという、そのように捉えていただければと思います。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。では、実際に今１３６件あって、そのうちの５０件がリモートでという、そのような捉え方でいいですね。分かりました。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"こんの委員","kind":"質問","question":"２つの一部改正ということで、主な改正の内容をお聞きしました。","respondent":"舩木生活衛生課長","answer":"こういった中で、旅行業界が非常に国のほうに大きな声を上げられたというところも背景の１つかなと考えていますし、もう一方、事業譲渡のほうで申し上げますと、国のほうで規制改革実施計画ということが閣議決定されておりますけれども、この本件に限らず、様々なそういった。","id":"exchange-049"},{"speaker":"こんの委員","kind":"質問・要望","question":"ただ、むやみやたらに拒むことをしないといったところは、この感染症は、やはり緊急事態宣言とか、そうしたものが発令された、その期間というようなこともあると思いますので、期間に関係なく拒むものではないと理解しておりまして、その点が理解が合っているかどうか確認をさせていただきたいということと、あと、こちら譲渡ですけれども、そうすると。","respondent":"舩木生活衛生課長","answer":"１点目ですけれども、冒頭にご説明いたしましたように、特定感染症、１類・２類感染症であったり、新型インフルエンザ等感染症であったり、こういった部分が蔓延しているときに限ると、このような扱いは限るのだということで間違いないということで。","id":"exchange-050"},{"speaker":"こんの委員","kind":"質問・要望","question":"分かりました。手数料の関係、分かりました。そこで、区としての監視を強めていくと。指導、改善というところまでは求められるのか。明らかにそれは監視したときに、これは周りにも迷惑、あるいは、この事業としてはいかがなものかというようなところが、もし監視をされたときに分かったときには、どの程度その事業者に指導、改善を求める、その権限が区としてはあるのでしょうか。その辺を教えてください。","respondent":"舩木生活衛生課長","answer":"すみません。１点訂正です。先ほど私、たしか７,６００円と申し上げましたが、正しくは７,４００円だということで、訂正します。","id":"exchange-051"},{"speaker":"こんの委員","kind":"意見","question":"分かりました。案件によって、確かにそうだと思います。近隣の方が、これ事業が譲渡されて、ボンとできた民泊のような、旅館業法だというようなところでは、やはり懸念の声というものはあったりしますので、ぜひ、そうしたことが上がったときにはご対応をしていただくようお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-04","title":"および(2)につきまして、関連する内容のため、一括して議題に供します。進め方といたしまして、一括して説明、質疑を行い、その後、その取扱い","agenda":"および(2)につきまして、関連する内容のため、一括して議題に供します。進め方といたしまして、一括して説明、質疑を行い、その後、その取扱い","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、ちょっと具体的なところで何点か伺いたいのですけれども、品川区でいえば、国民健康保険と後期高齢者医療制度になりますが、国民健康保険と後期高齢者医療制度で、マイナンバーと、それから保険証がひもづけられた方がどれぐらいいるのか、何人中何人くらい、何％なのかということをそれぞれ伺いたいと思います。取りあえずお願いします。","respondent":"池田国保医療年金課長","answer":"３番目の質問ですけれども、登録していない医者があるかですが、今のような形で、ちょっと全部の医療機関を把握しておりませんので、ただ、実際のところは、１００％の登録がまだ国のほうでできていないということになっておりますので、多少は登録はされていないところです。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"意見","question":"マイナ保険証のトラブルというものについては、今日、私たちも紹介議員をさせていただいています保険協会、全国保険医団体連合会のドクターの方々が、何度も何度も声明を出しながら、また記者会見も本当に何か、何回か見たのですけれども、怒りの記者会見のような形で、様々、医療現場がどれほど大変な状況になっているのか、患者も１つも悪くもない、医療機関も何ひとつ悪くない。","respondent":"池田国保医療年金課長","answer":"医療を受診する際のトラブルにつきましては、残念ながら私どものほうには、医療機関のほうからの申出はまだございません。それから患者からも、今のところは、こちらのほうにできなかったという直接のお声はいただいていないところです。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区内の医療現場の方からも伺っていますし、保険協会の調査でも、実際に使っている方は四、五％しかいないという、そのようなデータも出ていると思うのですが、それが今度は保険証がなくなったら、そのようなことにはならなくなってしまうわけなので、それが大変になるという状況になると思うので、ちょっとその辺のところは、国民健康保険にしても、後期高齢者医療制度にしても。","respondent":"池田国保医療年金課長","answer":"後期高齢者医療制度につきましては、来年の８月、来年が更新なのですけれども、それまでに国のほうから、保険証の廃止の日にちが決定されたものが公布されると思いますので、それに応じて保険証の、次回保険証の発行について、今広域連合のほうで検討しています。","id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問・要望","question":"では取りあえず、いろいろまだ聞きたいことはたくさんあるのですけれども、皆さんもあると思いますので、もう１点、ではちょっと、マイナ保険証という形でマイナンバーと健康保険証をひもづけない場合は、資格確認書という形で、これは、これまでは申請ということで、１年ごとに申請というようなことで言われていたものが、これだけ大問題という世論が広がる中で、資格確認書は、保険証とひもづけない方には。","respondent":"池田国保医療年金課長","answer":"資格確認書の有効期限ですけれども、国のほうでは最大５年まで有効の資格確認書ということになってございまして、こちらのほうは社会保険のほうを考えているところであるかと思われます。社会保険というものは有効期限ございませんので、一応５年という形になっていると思います。","id":"exchange-056"},{"speaker":"ひがし委員","kind":"質問","question":"今、付託された請願と、参考送付の陳情も見させていただいたのですけれども、やはりマイナンバーや保険証というところで、いろいろと実際にトラブルが起きているという現状なのですが、先ほどご答弁のありましたとおり、区として、特に区民の方や事業者、トラブルの報告はないということだったのですけれども、近所のおばあちゃまたちとお話をしていて、保険証のことのご相談。","respondent":"池田国保医療年金課長","answer":"私としては、大変申し訳ありません、国民健康保険の保険証に対してのお答えしかできないところですけれども、マイナンバー制度そのものが、個人情報の部分しかチップのほうに入っていないですので、実際に個人のいろいろな情報が入っているわけではないということで。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ですから、そのような場合が起きたときに相談する窓口や、医療との連携というものをしっかり強化した上で進めていかないと、絶対トラブルが起きますし、今後何か問題があってからでは遅いと思いますので、その点についてはしっかりと強化をしていただきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちら、私のほうは登録の手続をしてから、実際にひもづけの完了で反映されるまでに、どれぐらいタイムラグが今起きているのかということをお聞かせいただきたいと思います。実際今回、私も何件か区内の医療機関を実際に訪問して、お話は聞かせていただきました。本人は、もう登録を、手続を完了しているので、これさえ持っていけばかかれると思っている。","respondent":"池田国保医療年金課長","answer":"ひもづけにつきましては、いろいろな変更があったという点で、保険者のほうでたしか５日から一月ぐらいで必ずやるというようなことになっているかとは思っておりますけれども、実際にひもづけ、品川区の場合に、これまで先ほど総点検のお話をさせていただいたところですが。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"先ほどのほかの委員の答弁の中でも、品川区のほうにはまだそういった苦情は上がってきていないということでしたが、実際苦情は病院の窓口でストップしている状態の部分も多々あって、病院が止めているので上に上がっていない部分あると思いますので、また現場のほうにも、ヒアリング等で足を運んでいただいて、対応を見て一緒に解決していただけたらと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お伺いします。カードリーダーなのですけれども、これは病院、歯科、薬局に設置されていると思うのですが、この費用負担というものはどういった形になっているのですか。設置の費用負担。","respondent":"池田国保医療年金課長","answer":"申し訳ございません。費用負担は把握してございません。","id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。例えば病院、歯科、薬局以外でも、保険証を使う医療機関はあると思うのですけれども、整骨院とか。そういったところに対して、今後このカードリーダーの普及などというものは、そういったことに関してはご存じでしょうか。","respondent":"池田国保医療年金課長","answer":"今お話がありました、柔道整復でしたか、そういった医療機関につきましても、今度の秋以降にマイナ保険証での請求というようなことが、国のほうで少し話題になっているということで、実際に令和６年の秋には実施という形になってまいります。","id":"exchange-062"},{"speaker":"やなぎさわ委員","kind":"質問","question":"来年の秋ということですか。はい、分かりました。すみません。ちょっと質問変わるのですけれども、マイナンバーカードというか、マイナ保険証の普及に当たって、写真を皆さん撮る必要があると思うのですが、例えば、なかなか自分で写真を撮ることが難しい方。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"やなぎさわ委員","kind":"質問","question":"よろしいですか。例えば施設に入られていて、写真を撮ることが難しいなどという方に対して、どういった配慮を区のほうでされるという予定はありますか。","respondent":"池田国保医療年金課長","answer":"マイナンバーの取得につきましては、大変申し訳ございません、私どものほうではお答えできないところですけれども、ただ、先ほど顔の部分ではなくて、暗証番号を覚えられない方については、暗証番号のないマイナンバーカードを発行する予定があるということ。","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問","question":"ちょっと介護従事者からも声が上がっていると思うのですけれども、現在、例えば品川区立の特別養護老人ホームとか、ケアホームとか、グループホームなどもそうなのかもしれないのですが、入所者の保険証を施設側が預かって、入所者の方が急変したり、病気になったりしたときには、その保険証で施設の職員が病院を受診するということもされていると思うのですけれども。","respondent":"菅野高齢者福祉課長","answer":"現在マイナ保険証等について、マイナンバーカードの登録については、特別養護老人ホーム等の高齢者施設について、どのように申請をするとか、そういった話も戸籍住民課のほうからお話をいただいたときがございまして、今調整をしているところですので、今後。","id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、保険証だったら本当に単なる保険証だけということになりますけれども、マイナ保険証ということで、マイナンバーとひもづけされたマイナンバーカードを預かるということになると、例えばスマホならマイナポータルとか、そのようなところまで個人情報を、閲覧できることにもつながりかねないと思うのですが、そのようなところで、マイナンバーカードを。","respondent":"菅野高齢者福祉課長","answer":"区内の施設に限らず、こちらについては全国共通のことだと思いますので、その辺りのところ、国の見解なども確認しながら、今後進めていきたいと思います。","id":"exchange-066"},{"speaker":"鈴木委員","kind":"確認","question":"それからもう一つ、先ほども資格確認書というものが、１回目は、もしかしたらマイナンバーと健康保険証をひもづけなかった人には届くというようなことになるのかもしれませんけれども、それが、これまでのように健康保険証だったらば、保険者が保険証を被保険者に届けることが義務づけられているので、自動的に、健康保険証が被保険者のところに渡るという仕組みによって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"こんの委員","kind":"意見","question":"そもそもなぜ一体化をしようとしたのかと。するところの利便性という、先ほど冒頭にご説明ありましたけれども、もう少し詳しくその利便性というところ、保険者がこれを一体化することによってどのようなメリットが、保険証を持っていったときにかかる医療と、マイナ保険証になったときにかかる医療とのメリット、そこの違いというか、そこをまずご説明ください。","respondent":"池田国保医療年金課長","answer":"これまで違う視点から言いますと、保険証は顔が今までなかったかと思いますので、なりすましというようなこともございまして、そういったなりすましによっての不当利得や、不当な医療受診というものが、マイナ保険証を使うことによって、先ほどから顔のお話が出ていますけれども。","id":"exchange-068"},{"speaker":"こんの委員","kind":"質問","question":"それが、このカードの中に、病歴というのでしょうか、そのようなものが全部データとして入ることによって、受診先である程度、その人がどのような病歴で、どのような薬を飲んで、どのような治療をされてきたのかがデータとしてあるということが、次の医者にとっても、これまでの患者の受診する参考にもなるというものだと理解をしております。そうしたことも防げるということにもつながるのかなと。","respondent":"池田国保医療年金課長","answer":"総点検のところでまとまった点検の結果ですけれども、全３,４１１保険者のうち１,３１３団体において、１,５７０万件の登録データを対象に総点検を実施したというところでございまして、８月１日現在では、１,５１５万件の作業を完了しているということになってあります。","id":"exchange-069"},{"speaker":"こんの委員","kind":"質問・要望","question":"総点検の今、実施状況をお伝えをいただきましたけれども、そうなると、この総点検をしました。その総点検で何がトラブルだったのか、原因を究明して、そして再発防止といったところを確立していくと。公明党としても、国でそれは求めております。情報として持っているようでしたら教えてください。","respondent":"池田国保医療年金課長","answer":"同姓同名の同じ誕生日の方がいらっしゃることが何人もいたというところがありまして、さらに、きちんと住所のほうの確認をするというような、４点を確認することによって間違いはなくなるということで、必ず４点以上を。","id":"exchange-070"},{"speaker":"こんの委員","kind":"確認","question":"総点検の状況も確認をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"筒井委員","kind":"確認","question":"もう答弁で出たかもしれないですけれども、確認として、マイナンバーカードのマイナ総点検の、自治体向けの総点検の対象には、品川区はなっていないということでよろしいですか。その判断基準は、国の判断基準というものはどうしたものなのかということを教えてもらいたいと思います。","respondent":"池田国保医療年金課長","answer":"細かなところは、ちょっと私も正確に申し上げられないのですけれども、まずマイナンバーカードの情報確認をする際に、どういったことで本人確認をしているかというところのアンケート調査が国から区役所に参りまして、そして区役所のほうで、本人確認について、住所、氏名。","id":"exchange-072"},{"speaker":"筒井委員","kind":"質問","question":"総点検の対象になっていないからといって、そのひもづけの誤りが今後起きないとまでは言い切れないということなのでしょうか。","respondent":"池田国保医療年金課長","answer":"今後起こり得ないかですけれども、本人確認について、最低４情報は点検するようにということで、Ｊ－ＬＩＳのほうに、Ｊ－ＬＩＳとは４点検を確認するようにということでやっていますので、品川区につきましては、それ以上のもので確認をされているということでございまして。","id":"exchange-073"},{"speaker":"筒井委員","kind":"確認","question":"分かりました。マイナ保険証と資格確認書では、患者が窓口で負担する受診料というものは差がある。つまり、マイナ保険証のほうが少し安くて、資格確認書だと受診料は高くなるということで、それで間違いないでしょうか。","respondent":"池田国保医療年金課長","answer":"先ほどの情報につきましては、国民健康保険につきましては、住民情報と連携しているのでまず間違いがないということで、国民健康保険ではない部分でのお話をさせていただいたところです。","id":"exchange-074"},{"speaker":"こしば副委員長","kind":"意見","question":"結論を出すで、不採択でお願いいたします。そのような中で、今回は８,５００件ほどの登録の過誤があったと。一方でこの健康保険証自体が、では、例えば登録の過誤がなかったということ、そのようなことはなくて、大体年間で２０億件の受付があって、そのうち大体５００万件の登録の過誤があったというデータも出ています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すでお願いします。マイナ保険証について、保険で医療サービスをきちんと、これまでと同様に受けられる権利を守るということ、また、マイナ保険証を持たない人に交付する資格確認書ですけれども、この手続については、できるだけ簡素化をすること、こうしたことを国に求めております。ですから、こうしたことから、本請願については沿い難いと結論します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"ひがし委員","kind":"意見","question":"本日結論を出すでお願いいたします。ただ、デジタル化を進めていく状況の中でメリットもあり、永遠に現行の健康保険証を存続するというものではなく、課題の解決、そして区民のプライバシーと安全を守った上で、安全性が確保できたときには、一定の移行期間などを設けた上でのデジタル化に移行なども今後検討していくことがふさわしいと考えるため、この第１２号の請願に関しては、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そのように大問題になっている中で、国民健康保険でも３５％しか登録できていないという、このような状況になっているのだと思います。これまでの健康保険証を廃止しないこと、そのような形で国民皆保険制度を守るという立場からも、マイナ保険証という形で、マイナンバーカードと保険証のひもづけというものはやめるべきだし、保険証の廃止を中止して、存続をするべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、まだまだマイナ保険証に対しての不安払拭は完全になされているとは言い難い状況なのですけれども、やはりマイナ保険証のメリット、医療ＤＸ化の推進ということはやらなくてはいけないので、これまでの健康保険証の廃止を中止するということは取り難いので、今回の請願第１２号に対しては不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日の議論を見まして、マイナンバー保険証はやはりトラブルも続出しており、今回、先ほど鈴木委員がおっしゃっていたように、こちらの今回参考送付となった陳情も併せますと、全部で陳情、請願４件のものが上がってきています。その中に、１つは４０名の署名つきのものもあります。それだけ現場が今混乱して困っているということは、非常に実感しております。私はこの請願は採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"結論を出します。採択です。メリットもお伺いしてはいるのですけれども、それを行使するかどうかは、本人が任せられるというか、選択できる状況が一番いいのかなとは、個人的に思います。やはりトラブルがあまりにも多いということで、メリットよりデメリットのほうが上回っているのかなというように感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"質問・要望","question":"結論を出すで、今回の第１３号、「健康保険証の廃止を延期し、今の健康保険証の存続を求める意見書」の提出を求める請願につきましては、採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すということで、採択でお願いします。本来、私は健康保険証の廃止はやめるべきだと考えていますが、これは廃止を延期して、存続を求める意見書ということなので、このことに対しても賛成をしたいと思います。ここに書かれているそのとおり、トラブルだらけ、そのような状況になっておりますので、これを採択して、ぜひ意見書を上げていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"筒井委員","kind":"確認","question":"マイナ保険証のメリットは認められまして、医療ＤＸを進めなくてはいけないという考えなのですけれども、まだ利用者や関係者の不安は払拭される状態ではないということと、資格確認書がどのようなものなのか、まだはっきりしていないこと、総点検作業の結果、まだ何かしらのトラブルが発生する可能性もあるということで、一定期間の延期は必要かなと考えるので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"おぎの委員","kind":"質問","question":"こちらの陳情に関しまして、本日結論を出すでお願いします。理由は、先ほど第１２号の議案で述べたものと同じものになります。やはり今こういった大きく混乱が起こっている、そしてそれが病院だけではなく、実際の患者が今一番不利益を被っている、こういった現状を国のほうへ伝えるためにも、こちらのほうも私は採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"意見","question":"結論を出します。採択でお願いします。先ほどの、私が第１２号で申し上げたとおり、あと鈴木委員もおっしゃったとおり、保険証廃止を延期するということで、我々れいわ新選組におきましては、本来であればマイナンバー制度自体異議を唱えておりますけれども、まず何よりも保険証を存続するということが大切だと思いますので、これに関して採択するものであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"}]},{"id":"topic-05","title":"令和５年陳情第３０号、福祉避難所となる心身障害者福祉会館の安全で快適な整備を求める陳情","agenda":"令和５年陳情第３０号、福祉避難所となる心身障害者福祉会館の安全で快適な整備を求める陳情","exchanges":[{"speaker":"ひがし委員","kind":"質問","question":"この心身障害者福祉会館の現状についてお伺いしたいのですけれども、現状の建物も定期点検というものをやっていると思うのですが。調べたところ、建物の検査は３年ごとで、建築設備に関しては１年以内ごとの点検を実施ということで、この点検の報告書でどのような不具合、または課題などがあったのかという点、もしありましたら教えてください。","respondent":"松山障害者支援課長","answer":"委員おっしゃられるとおり、点検の状況ですが、建築課のほうで、建物に係る点検は３年に一度しております。","id":"exchange-087"},{"speaker":"ひがし委員","kind":"質問・要望","question":"定期的に点検をされているということで、直近いつされたのかと、そのときに出てきた課題点、問題点などがあれば教えていただきたいという点と、あともう１点、そのようなところでもし問題が生じたときに、どこか情報載っているのか。","respondent":"松山障害者支援課長","answer":"点検に関わる公表なのですが、特に公表されているものはございません。どちらかというと、私どもと施設整備所管、それと指定管理者のところできめ細かく修繕をしていくというものになりますので、今のところ公表しているものは特にございません。","id":"exchange-088"},{"speaker":"ひがし委員","kind":"質問","question":"ごめんなさい。１点、多分返答いただいていないかと思うのですけれども、点検のときの不具合などはないのかという部分で、築が結構、４０年以上経過して古いというところでいうと、昇降機などが古かったり、そのようなところも既存不適格というものは、指摘として上がってきていないのでしょうか。","respondent":"松山障害者支援課長","answer":"今ちょっと点検の結果等、すごく細かく、こちらで今現在持っているわけではございません。その都度対応しているものです。","id":"exchange-089"},{"speaker":"ひがし委員","kind":"質問","question":"その点、もし改修、エレベーターの工事というものはまだ難しいというように、前回の陳情が出たときもお話をしていたと思っているので、その点について、もし改善がされていないのであれば、地震だけではなくて火災が起きたときの災害の対策というところが十分ではないのかなと思いますので、その点、もし定期点検の結果等ありましたら、ぜひ厚生委員会のメンバー、私でも誰でもいいのですけれども。","respondent":"松山障害者支援課長","answer":"昇降機につきましては、指定管理料の中に入っているものです。ご報告は受けているのですけれども、特に何か、すごく細かいことまで公表するというよりは、現在もう改築に向けて検討しているというところが大きな今回のところです。","id":"exchange-090"},{"speaker":"ひがし委員","kind":"意見","question":"防災訓練というものも毎月やられていることで、その点については毎月実施をして、実際の防災が起きたときの対応ができるという点ではいいと思うのですけれども、やはり建物の性能上、もし火が回りやすいとか、煙で逃げられないということになってくると、建て替えも含めた計画というものはもちろん、それこそ早急に進めていかなければいけないことなのではないかなと思いましたので。","respondent":"東野福祉計画課長","answer":"ただ、心身障害者福祉会館がそこに記載されているかどうかはちょっと手元にはないので、建築課のほうにお問合せいただければ、その確認はできると思われます。〔翌日「建築課で公表しているのは民間のみ。","id":"exchange-091"},{"speaker":"鈴木委員","kind":"質問","question":"心身障害者福祉会館が改築に向けて検討しているということなのですけれども、具体的にいつ頃までに改築を目指すという、そのようなスケジュール的なところで、おおよその見通しがついているのか、ちょっと見通しがついているのであれば、その時期的なところも教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"代替施設の確保ができれば、スケジュールはおのずから決まってくるものと考えております。代替施設が決まりましたら、またこちらの委員会のほうにもご報告させていただきたいと考えています。","id":"exchange-092"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ということは、代替施設を今探しているというところですか。それで、ちなみに心身障害者福祉会館の、何というのですか、敷地と延べ床面積の平米数が分かったら教えていただきたいということと、あとリボンがどれぐらい使えるのかという点が、もしも分かるようでしたら教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"それからあと、代替施設に関してなのですが、委員おっしゃられたところも様々なところがありますので、また、やはりなかなかこう、一括して移るということになりますと、またそれはそれで、様々な視覚障害者の方、あるいは訓練されている途中の方、いろいろ。","id":"exchange-093"},{"speaker":"鈴木委員","kind":"質問","question":"そのときにリボンなどは対象にならないのかということが、すぐ近くなので、心身障害者福祉会館のすぐそばなので、結構多くの方がそう思っているのではないかと思うのですけれども、全部が全部１か所でということはなかなか難しいのかなと思うのですが、そのような点では、何というのですか、どのような形で可能性を、代替施設の可能性を探していくというか、つくっていくということになるのか。","respondent":"松山障害者支援課長","answer":"今は実際に検討していますのは、１つは機能分散の方法です。それは東京都に相談に行っております。今も指定を受けているのは生活介護と自立訓練ということで、自立訓練センターが一緒になった多機能型ということで指定を取っております。","id":"exchange-094"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、今築４６年で、どれくらいのスパンで改築ができる、いつ頃までに改築を目指すという、そのような目指す、いつ頃までという、例えばこの５年間のうちにとか、何年のうちにというような、そのようなことというのはあるのか、ちょっとその点も伺いたいと思います。改築するわけです。そこのときに、建物のボリュームとしては、今よりも拡充はできるのか、その点も教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"まだ、特に候補地について、目星をつけているわけではございません。実際問題、本当に東京都の指定が取れなければ、安全なサービスが提供できないというのが大きなところになります。そのため、代替地を今探しているというところです。","id":"exchange-095"},{"speaker":"鈴木委員","kind":"質問","question":"なかなか具体的なところが見えなくて、すごいもどかしい感じなのですけれども、本当にここのところは、ずっと前から心身障害者福祉会館を建て替えて、何というのですか、荏原地域の拠点としても、拠点の１つとしても充実をさせてほしいということは、陳情や何かも何度も上がってきたりしていますので、いよいよ４６年たってこのような状況になっていますので、ぜひ具体化をよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"筒井委員","kind":"確認","question":"確認も含めてお聞きしたいのですけれども、今後バリアフリー法に適合したようなものの改築のご予定がある。そのための代替地、その改築の間の代替地が必要であるけれども、代替地を見つけやすくするために機能を分散させて、代替地を見つけやすくして、今お探しになっているという状況ということでよろしいのでしょうか。","respondent":"松山障害者支援課長","answer":"委員のおっしゃるとおりです。機能分散だけがもう決まっているわけではございませんので、１つの方法としてということで、東京都に相談に行っているところです。","id":"exchange-097"},{"speaker":"筒井委員","kind":"質問","question":"今後もこうした施設が古くなってきて、改築しなくてはいけないという状況が多々出てくるかと思うのですけれども、そのための代替地が見つけにくいという問題がどうしても生じてくると思うのですが、区として、ある程度一定の建て替えのための用地というものをある程度、２つ３つ取得しておいて。","respondent":"松山障害者支援課長","answer":"私どももそれぞれ、福祉部でそれぞれの施設を所管しておりますので、総合的に、やはり判断という、例えば施設のこれからの代替地の確保につきましては、企画の所管のほうで総合的にどうされるかということは考えるものと認識しております。","id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"そのためにと整備をして、計画策定をと求めている内容ですけれども、まずはこの施設の整備、改築というところでは、先日の本会議で、一般質問だけでなく、今年の３月の予算特別委員会においても、高橋伸明議員の質問で、そのときの答弁でも、理事者より代替地を検討して建て替えあるいは改修などという形で検討するように、必要と考えているという答弁が出て、今回また再度、同じ方からの質問で、改築。","respondent":"松山障害者支援課長","answer":"それは、それに向かっていくというところです。先ほど申し上げたのは、様々な方がいらっしゃるので、きちんとそのような方々に配慮しながら、代替地への移動車ですとか、新たな会館として、福祉の避難所として整備するというところで、様々な方に配慮しながら進めていくです。","id":"exchange-099"},{"speaker":"こんの委員","kind":"質問・要望","question":"サービスを継続しながらの作業というところが非常に大事だと思うのです。そこを次どのようにするかという、模索する段階にも入ってきているという中で、この心身障害者福祉会館の改築に当たって、これをどう活用していくかというところは、所管も多分企画のほうなどとやり取りをされていることも想像するのですけれども、その辺のところの取組についても確認させていただきたいと思います。","respondent":"松山障害者支援課長","answer":"もう１点は計画なのですが、計画につきましては、今年度策定する障害福祉計画、そして、今公共施設等の総合実施計画というものもありますので、そちらのほうに、どこまで明文化できるか、記載できるかという具体的なことはさておきましても、明文化はきちんと。","id":"exchange-100"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたことも一方で考えて、改築というところのアナウンスといったところが大事だろうと思うのですけれども、でも、きちんと明文化していくという、この計画の中で改築で検討していくというか、進めていくということは１つ決めて、ここはうたっていただきたいなと思います。先ほど町会の方々や地域の方々、あるいは団体の方々のご意見を伺いながらということですけれども、ぜひお願いしたいと思います。","respondent":"松山障害者支援課長","answer":"ご利用者の方、やはり改築ということが情報が流れますと、私たちどこに行けばいいのでしょうか、いつまでいられるのでしょうかというようなご不安をお持ちになる方はいらっしゃると想定されますので、ご利用者の方には、今区が考えていること。","id":"exchange-101"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ今ご答弁いただいたようなことで進めていただきたいなと思います。ですが、そこを払拭していく今回の改築に向けた区の方向性が出すわけですので、どうかそこは、区民の方、安心してくださいと。ここは福祉避難所としてきちんと改築していきますと、こう発信を、安心してもらうような発信と、また利用者、団体の方々、町会の方々とやり取りをして、丁寧に進めていただきたいと思います。いかがでしょうか。","respondent":"松山障害者支援課長","answer":"実際には、やはりあの地域で愛されている会館ですし、それぞれ地元の町会含め、障害者団体のご協力があって会館まつりという、実行委員会をつくって、皆さんのご意見を集約した形で、やはり毎年のようにお祭りを実施しているわけです。","id":"exchange-102"},{"speaker":"やなぎさわ委員","kind":"確認","question":"改築や建て替え、そういったものを含めて、なかなか計画策定ができないということは、今日改めて確認なのですけれども、やはりある程度まとまった用地の取得ができないからといいますか、めどがすぐには立たないからということでよろしいですか。","respondent":"松山障害者支援課長","answer":"幾つがまとまった土地というものは、恐らく区の中でもあるかと考えています。ただ、適切に会館の方が安心してサービスを継続できるところを、今現実的に検討しています。","id":"exchange-103"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この福祉会館が、あそこで１,５００m2あるということで、例えば同じサイズぐらいの用地があれば、分散という話もありましたけれども、そちらに新しくつくって、同じような施設をつくって、そこでサービスを継続するということは可能でしょうか。","respondent":"松山障害者支援課長","answer":"同じぐらいの用地があればという条件だけではなくて、送迎バスのこと、食事のこと、あるいは自立されて訓練、駅から歩くという訓練を今されている方、あと視覚障害の方、旗の台の駅からは会館まで点字ブロックで通われている方もいらっしゃいますので、ではそのような方に。","id":"exchange-104"},{"speaker":"やなぎさわ委員","kind":"確認","question":"分かりました。１つ確認なのですけれども、先ほどから東京都と相談というお話なのですが、こういった施設の指定権者が東京都だからという認識でよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"委員のおっしゃられるとおりです。東京都が指定権限を持っております。","id":"exchange-105"},{"speaker":"やなぎさわ委員","kind":"質問","question":"例えば、これ東京都の指定を受けずに、区で独自に何か取組を持って施設をつくるということは可能なのでしょうか。","respondent":"松山障害者支援課長","answer":"障害福祉サービスとして東京都に指定を受けるということで、国や都の財源が入ってくるということで、安定して継続するサービスということを考えたときに、やはり年単位、代替施設の場合は年単位になろうかと思いますので。","id":"exchange-106"},{"speaker":"こしば副委員長","kind":"質問","question":"結論を出すで、不採択でお願いします。理由としましては、先ほど来質疑応答がありましたけれども、３月の予算委員会、また、先般の高橋伸明議員の一般質問での回答を踏まえ、また、先ほど課長からも、具体的な対策のほうもお話を伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すでお願いします。それも理解をしました。だからこそ丁寧にしていくためにも、機能分散ということも含めて、今検討してくださっているということですので、どうかこの辺を利用者、団体の方々、町会の方々と常に連携をとりながら、不安払拭に努めていただいて、そして改築に向けていただきたい、このように思いますので、今請願については沿い難いと結論します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"ひがし委員","kind":"質問","question":"本日結論を出すでお願いいたします。先日の一般質問で、建て替えを含めた計画を検討するとご答弁されておりました。だからこそ、建て替えのために代替の施設なども、難しい課題はあると分かっておりますが、都や各所管と連携をして、代替地取得の方法も含めた具体的なロードマップを示した計画の策定を要請いたしますので、この陳情については採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すということで、この陳情に対しては採択でお願いしたいと思います。心身障害者福祉会館は、本当にもう築４６年で改築が必要ということで、検討に入ったということですけれども、やはり具体的に早くに計画を策定して、いつまでにどのような形でやるかということを具体化していただきたいと思います。その検討をぜひとも早急に進めていただきたいという思いを込めて、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"筒井委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。理由は、先ほどご答弁等々ありましたとおり、バリアフリー法適用にする施設に改築予定が、しっかりとそうした方向性が立てられているということであります。一方、その用地取得も含めた計画策定というものは、先ほどからご答弁にもあったとおり、なかなか現実的には厳しい点があるのかなと思いまして、この点をもって不採択ということにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"おぎの委員","kind":"意見","question":"私も本日決めるでお願いします。お話を聞きますと、区のほうでも前向きに検討していただいているということですが、ただ、ちょっとこのままのんびり待っていると、築今４６年間が、４７年、４８年とどんどん老朽化していってしまいますので、こちらのほうはやはり用地取得等の計画も含めて、都と連携して積極的にやっていったほうがいいと感じました。採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-112"},{"speaker":"やなぎさわ委員","kind":"意見","question":"もちろん品川区におかれましても、用地取得やいろいろ、建て替え含めて尽力されていらっしゃるということ、承知はしておりますけれども、私も障害団体の方、当事者の方とお話を重ねていて、やはり計画がなかなか進まないというところで不安になられている方も多くいらっしゃいまして、なかなか進まないなというようなことを私も実感しておりますので、ぜひ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/424146?Template=document&Id=3670#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":80667,"voices":318}}]);
